-- == Batch 1: feature descriptions & preset blurbs ============================
L["A CDM replacement focused on performance, customizations and alerts."] = "Un sostituto del CDM incentrato su prestazioni, personalizzazioni e avvisi."
L["A Frame Strata dropdown in the Character Crosshair cog controls whether the crosshair draws above or below other UI"] = "Un menu a tendina Livello finestra nell'ingranaggio del Mirino personaggio controlla se il mirino viene disegnato sopra o sotto le altre finestre dell'interfaccia"
L["A Horizontally Growing Anchor Target"] = "Un bersaglio di ancoraggio con crescita orizzontale"
L["A UI reload is needed to add this icon to the sidebar."] = "È necessario ricaricare l'interfaccia per aggiungere questa icona alla barra laterale."
L["A UI reload is needed to apply the extended chat background."] = "È necessario ricaricare l'interfaccia per applicare lo sfondo esteso della chat."
L["A UI reload is needed to apply your sidebar icon changes."] = "È necessario ricaricare l'interfaccia per applicare le modifiche alle icone della barra laterale."
L["A Vertically Growing Anchor Target"] = "Un bersaglio di ancoraggio con crescita verticale"
L["A beautiful visual refresh of Blizzard Bags with intuitive organization."] = "Un bellissimo rinnovamento visivo delle Borse di Blizzard con un'organizzazione intuitiva."
L["A blank bar to build from scratch."] = "Una barra vuota da costruire da zero."
L["A bright, minimalist layout with a clean aesthetic. Crafted for any role with clear information and a calm but focused feel."] = "Un layout luminoso e minimalista dall'estetica pulita. Pensato per qualsiasi ruolo, con informazioni chiare e un'atmosfera calma ma concentrata."
L["A checked Hide visibility condition now always hides its element in both match modes, and every condition has its own Show and Hide row, with new Out of Combat and Not Skyriding (Airborne) rows."] = "Una condizione di visibilità Nascondi selezionata ora nasconde sempre il proprio elemento in entrambe le modalità di corrispondenza, e ogni condizione ha le proprie righe Mostra e Nascondi, con le nuove righe Fuori dal combattimento e Non in Skyriding (In volo)."
L["A clean minimal setup"] = "Una configurazione pulita e minimale"
L["A clean, airy layout with a calm feel and clear information at a glance. Comfortable for long sessions in any content."] = "Un layout pulito e arioso con un'atmosfera calma e informazioni chiare a colpo d'occhio. Comodo per sessioni lunghe in qualsiasi contenuto."
L["A clean, updated reskin of Blizzard's Quest Tracker."] = "Un restyling pulito e aggiornato del Tracciamento missioni di Blizzard."
L["A dark, elegant healing setup built around raid frames and a clean display of information to help keep your team alive at a glance."] = "Una configurazione da guaritore scura ed elegante costruita attorno ai riquadri incursione e a una visualizzazione pulita delle informazioni, per tenere in vita la squadra a colpo d'occhio."
L["A luminous healing setup built around raid frames and crisp readability, keeping your team's health front and center at a glance."] = "Una configurazione da guaritore luminosa costruita attorno ai riquadri incursione e a una leggibilità nitida, con la salute della squadra sempre in primo piano a colpo d'occhio."
L["A modern friends list with built-in organization tools."] = "Una lista amici moderna con strumenti di organizzazione integrati."
L["A new Use Modifier option makes the spell and item ID lines on tooltips appear only while you hold Shift, Control, or Alt."] = "Una nuova opzione Usa modificatore fa apparire le righe con l'ID di incantesimo e oggetto nei tooltip solo mentre tieni premuto Maiusc, Ctrl o Alt."
L["A new age minimap with clean styling and square layout options."] = "Una minimappa moderna con uno stile pulito e opzioni di layout quadrato."
L["A new built-in profile preset: the damage dealer cut of Midnight Lily, a focused low-clutter layout that keeps your rotation and cooldowns front and center."] = "Un nuovo preset di profilo integrato: la versione da danno di Midnight Lily, un layout essenziale e ordinato che mantiene rotazione e recuperi sempre in primo piano."
L["A new option that makes enemy nameplates pulse with a red glow the moment a target drops below 30% health, so a whole pack tells you at a glance which mobs are in execute range."] = "Una nuova opzione che fa pulsare le targhette nemiche con un bagliore rosso nel momento in cui un bersaglio scende sotto il 30% di salute, così un intero gruppo ti mostra a colpo d'occhio quali mob sono a tiro di esecuzione."
L["A profile named \"%1$s\" already exists. Please choose a different name."] = "Esiste già un profilo chiamato \"%1$s\". Scegli un nome diverso."
L["A quick view of every font setting in one place."] = "Una panoramica rapida di ogni impostazione dei caratteri in un unico posto."
L["A quick view of every texture setting in one place."] = "Una panoramica rapida di ogni impostazione delle texture in un unico posto."
L["A raid control panel with ready check, pull timer and raid markers. In a raid it only shows while you are the leader or an assistant, since none of its buttons work without that; in a party it always shows."] = "Un pannello di controllo incursione con ready check, timer di pull e indicatori raid. In un'incursione è visibile solo se sei il capogruppo o un assistente, poiché nessuno dei suoi pulsanti funziona senza; in un gruppo è sempre visibile."
L["A shadowed, understated layout that keeps the screen quiet and the essentials close. Information appears exactly when you need it."] = "Un layout ombreggiato e sobrio che mantiene lo schermo silenzioso e l'essenziale a portata di mano. Le informazioni appaiono esattamente quando servono."
L["A simple Mythic+ timer with full tracking customizations."] = "Un semplice timer per Mitica+ con personalizzazioni di tracciamento complete."
L["A spec override owns this setting, so this conditional value never applies outside an editing session. Remove the spec override to let it through."] = "Un override di specializzazione possiede questa impostazione, quindi questo valore condizionale non si applica mai al di fuori di una sessione di modifica. Rimuovi l'override di specializzazione per lasciarlo passare."
L["A spec override setting Visibility to Never no longer leaves the frame missing after switching back to another spec."] = "Un override di specializzazione che imposta Visibilità su Mai non lascia più il riquadro mancante dopo essere tornati a un'altra specializzazione."
L["A standalone cast bar for this unit, placeable anywhere in Unlock Mode. Runs alongside the Unit Frames cast bars."] = "Una barra di lancio autonoma per questa unità, posizionabile ovunque in Modalità sblocco. Funziona insieme alle barre di lancio dei Riquadri unità."
L["A sync group needs at least two profiles"] = "Un gruppo di sincronizzazione richiede almeno due profili"
L["A target you can attack."] = "Un bersaglio che puoi attaccare."

