L["Add diminishing-returns detail (adjusted rating, wasted rating, and current penalty bracket) to the Secondary and Tertiary stat tooltips."] = "Aggiungi dettagli sui rendimenti decrescenti (valutazione corretta, valutazione sprecata e fascia di penalità attuale) ai tooltip delle statistiche secondarie e terziarie."
L["Add in Blizzard CDM"] = "Aggiungi nel CDM di Blizzard"
