L["Addon"] = "Addon"
L["Adds Bonus Roll and Group Loot movers to Unlock Mode."] = "Aggiunge gli spostatori di Tiro bonus e Bottino di gruppo alla Modalità sblocco."
L["Adds Bonus Roll, Group Loot, and Alert Toast movers to Unlock Mode."] = "Aggiunge gli spostatori di Tiro bonus, Bottino di gruppo e Notifica avviso alla Modalità sblocco."
L["Adds a 'Train All' button next to the Train button at profession trainers, allowing you to learn all available skills with one click."] = "Aggiunge un pulsante 'Addestra tutto' accanto al pulsante Addestra presso gli istruttori di professione, permettendoti di imparare tutte le abilità disponibili con un clic."
L["Adds a Calc toggle button to the character sheet that opens and closes the Upgrade Calculator."] = "Aggiunge alla scheda personaggio un pulsante di attivazione/disattivazione Calc che apre e chiude il Calcolatore di miglioria."
L["Adds a Shadow border to your player frame when you pull or hold threat as a non-tank. Only active in dungeons, raids and delves."] = "Aggiunge un bordo Ombra al riquadro del tuo personaggio quando attiri o mantieni l'aggro come non tank. Attivo solo in spedizioni, incursioni e Delve."
L["Adds a Targeting line showing who the hovered player or NPC is targeting, in green when it's you."] = "Aggiunge una riga Bersaglio che mostra chi sta bersagliando il giocatore o il PNG sotto il cursore, in verde se sei tu."
L["Adds a compact Raid Tools window -- target/world markers, ready check, role check and pull timer in one resizable row. It runs alongside whichever Show as layout is picked above (or with Raid Tools fully off), moves and resizes independently through Unlock Mode, and only appears while you're actually in a raid group."] = "Aggiunge una finestra compatta degli Strumenti raid: indicatori bersaglio/mondo, ready check, controllo ruolo e timer di pull in un'unica riga ridimensionabile. Funziona insieme a qualsiasi layout Mostra come scelto sopra (o con gli Strumenti raid completamente disattivati), si sposta e si ridimensiona indipendentemente tramite la Modalità sblocco, e appare solo quando sei effettivamente in un gruppo raid."
L["Adds a mover for Blizzard's top-center event text and widgets (scenario, event, and encounter bars)."] = "Aggiunge uno spostatore per il testo degli eventi e i widget in alto al centro di Blizzard (barre di scenario, evento e scontro)."
L["Adds a small filled dot at the center of the cursor circle. Uses the same color and opacity as the circle."] = "Aggiunge un piccolo punto pieno al centro del cerchio del cursore. Usa lo stesso colore e la stessa opacità del cerchio."
L["Adds a steady red glow around the nameplate while the Near Aggro color is active."] = "Aggiunge un bagliore rosso costante attorno alla targhetta mentre è attivo il colore Aggro vicino."
L["Adds a strip down the left edge of a loot toast in the item's quality color. The flat skin drops Blizzard's quality ring around the icon, so this puts that rarity cue back."] = "Aggiunge una striscia lungo il bordo sinistro della notifica di bottino nel colore di qualità dell'oggetto. Lo skin piatto rimuove l'anello di qualità di Blizzard attorno all'icona, quindi questo ripristina quell'indicazione di rarità."
L["Adds the mount a player is riding to their tooltip, with a green check if you own it or a red X if you don't."] = "Aggiunge al tooltip la cavalcatura che un giocatore sta usando, con un segno di spunta verde se la possiedi o una X rossa se non la possiedi."
L["Adds three optional world-marker keybinds that remain usable in combat. Place drops the first free marker at the cursor in Star to Skull order; Undo removes the last marker placed through Quick Fire; Clear removes all world markers. Every binding starts empty. Marker changes made elsewhere during combat are picked up afterward."] = "Aggiunge tre associazioni tasti opzionali per gli indicatori mondo, utilizzabili anche in combattimento. Posiziona piazza il primo indicatore libero sul cursore nell'ordine Stella-Teschio; Annulla rimuove l'ultimo indicatore piazzato tramite Fuoco rapido; Cancella rimuove tutti gli indicatori mondo. Ogni associazione parte vuota. Le modifiche agli indicatori effettuate altrove durante il combattimento vengono rilevate in seguito."
L["Adds timestamps to system messages, loot, achievements, and addon messages, not just player chat."] = "Aggiunge indicatori orari ai messaggi di sistema, al bottino, agli obiettivi e ai messaggi degli addon, non solo alla chat dei giocatori."
L["AdiBags"] = true
L["Adjust Crop"] = "Regola ritaglio"
L["Adjust Volume"] = "Regola volume"
