L["Always on for Whirlwind and Sweeping Strikes charges: range coloring at/above the threshold is the only way these bars can display thresholds."] = "Sempre attivo per le cariche di Turbine e Colpi Fendenti: la colorazione in base al raggio d'azione a/sopra la soglia è l'unico modo in cui queste barre possono mostrare le soglie." -- NAO-OFICIAL
L["Always show Blizzard's bright rotating edge on cooldowns in this bar. Hide Recharge Edge still overrides this for individual charge spells."] = "Mostra sempre il bordo rotante luminoso di Blizzard sui tempi di recupero in questa barra. Nascondi bordo di ricarica ha comunque la precedenza per i singoli incantesimi a cariche."
L["Always show less common settings instead of collapsing them behind a Show Less Common link."] = "Mostra sempre le impostazioni meno comuni invece di comprimerle dietro un link Mostra meno comuni."
L["Always show the crosshair."] = "Mostra sempre il mirino."
