L["Automatic follows the zone name. Manual holds the block at a fixed width and clips longer names, so it never shifts the blocks beside it."] = "Automatico segue il nome della zona. Manuale mantiene il blocco a una larghezza fissa e taglia i nomi più lunghi, così non sposta mai i blocchi accanto ad esso."
L["Automatic shows XP while leveling and reputation at max level."] = "Automatico mostra l'esperienza durante la progressione di livello e la reputazione al livello massimo."
