L["Automatically add a bar to this group for every spell in Blizzard's Tracked Bars section, now and whenever a new one appears."] = "Aggiunge automaticamente una barra a questo gruppo per ogni incantesimo nella sezione Barre tracciate di Blizzard, ora e ogni volta che ne appare uno nuovo."
L["Automatically dismisses the 'new mount/pet/toy' fanfare notification when you receive one, so you don't have to click through the collections journal."] = "Chiude automaticamente la notifica di fanfara \"nuova cavalcatura/famiglio/giocattolo\" quando ne ricevi una, così non devi passare attraverso il diario delle collezioni."
L["Automatically duplicates the raid's tanks into the Extra Frames group. Shares the 5-frame cap with hotkey picks."] = "Duplica automaticamente i tank dell'incursione nel gruppo Riquadri extra. Condivide il limite di 5 riquadri con le selezioni da tasto di scelta rapida."
L["Automatically duplicates the raid's tanks into the Extra Frames group. Shares the frame cap with hotkey picks."] = "Duplica automaticamente i tank dell'incursione nel gruppo Riquadri extra. Condivide il limite di riquadri con le selezioni da tasto di scelta rapida."
L["Automatically enables the 'Current Expansion Only' filter whenever you open the Auction House."] = "Attiva automaticamente il filtro \"Solo espansione corrente\" ogni volta che apri la Casa d'aste."
L["Automatically hides unused action slots and resizes the bar to fit its assigned actions. Empty slots return while dragging an action so you can place it anywhere."] = "Nasconde automaticamente gli slot azione inutilizzati e ridimensiona la barra per adattarla alle azioni assegnate. Gli slot vuoti ricompaiono mentre trascini un'azione, così puoi posizionarla ovunque."
L["Automatically inserts your key into the Font of Power."] = "Inserisce automaticamente la tua chiave nella Fonte di potere." -- TODO: confirmar termo oficial
L["Automatically opens and closes the Upgrade Calculator when the Character Sheet is opened or closed."] = "Apre e chiude automaticamente il Calcolatore di miglioria quando la Scheda personaggio viene aperta o chiusa."
L["Automatically opens bags, boxes and parcels in your inventory when they are added to your bags.\n\nContainers received from the mailbox are held until you close the mailbox, so opening them cannot collide with mail still delivering items."] = "Apre automaticamente borse, scatole e pacchi nel tuo inventario quando vengono aggiunti alle tue borse.\n\nI contenitori ricevuti dalla posta vengono trattenuti finché non chiudi la posta, così la loro apertura non può interferire con la posta che sta ancora consegnando oggetti."
L["Automatically opens the Upgrade Calculator when the Crest Upgrade NPC window is opened."] = "Apre automaticamente il Calcolatore di miglioria quando viene aperta la finestra del PNG di miglioria delle Creste." -- TODO: confirmar termo oficial (Crest)
L["Automatically refreshes the Premade Groups list every few seconds while you are browsing, so newly posted groups appear without clicking Refresh."] = "Aggiorna automaticamente l'elenco dei Gruppi precostituiti ogni pochi secondi mentre lo stai sfogliando, così i gruppi appena pubblicati appaiono senza dover cliccare su Aggiorna."
L["Automatically removes cosmetic transforms when they are applied to you, such as profession gear, holiday costumes, toys and consumables. Use the cog to pick exactly which transforms are removed. Transforms applied during combat are removed when combat ends."] = "Rimuove automaticamente le trasformazioni estetiche quando vengono applicate a te, come equipaggiamento da professione, costumi festivi, giocattoli e consumabili. Usa l'ingranaggio per scegliere esattamente quali trasformazioni vengono rimosse. Le trasformazioni applicate durante il combattimento vengono rimosse alla fine del combattimento."
L["Automatically repair all gear when visiting a repair vendor."] = "Ripara automaticamente tutto l'equipaggiamento quando visiti un venditore di riparazioni."
L["Automatically sell all junk items when visiting a vendor."] = "Vende automaticamente tutti gli oggetti di scarto quando visiti un venditore."
L["Automatically starts and stops combat logging when entering or leaving a loggable instance."] = "Avvia e interrompe automaticamente la registrazione del combattimento quando entri o esci da un'istanza registrabile."
L["Automatically types DELETE when throwing away a valuable item. Also allows you to press enter to accept the deletion."] = "Digita automaticamente ELIMINA quando getti via un oggetto di valore. Ti permette anche di premere invio per confermare l'eliminazione."
L["Automatically zoom back out to maximum distance after this many seconds of no manual zoom change. 0 disables the reset."] = "Esegue automaticamente lo zoom indietro alla distanza massima dopo questo numero di secondi senza modifiche manuali dello zoom. 0 disattiva il ripristino."
L["Available only when Anchor to Windows is set to Free Move."] = "Disponibile solo quando Ancora alle finestre è impostato su Movimento libero."
