L["Choose which addons you want enabled. You can change any of these later in the EllesmereUI settings panel."] = "Scegli quali addon vuoi attivare. Potrai modificarli in seguito nel pannello delle impostazioni di EllesmereUI."
L["Choose which channels get a bubble.\n\nSay, Yell, NPCs and Emotes share one Blizzard switch. It is turned on while at least one of the four is ticked, and put back the way you had it once you clear the last one. Party and Raid have switches of their own and start out matching what you already had, so no group bubbles turn up in a chat that had none.\n\nGuild is not offered: Blizzard draws no bubble for guild chat, and there is nothing for us to restyle."] = "Scegli quali canali ricevono un fumetto.\n\nDire, Urlare, PNG ed Emote condividono un unico interruttore di Blizzard. È attivo finché almeno uno dei quattro è selezionato, e viene ripristinato come lo avevi impostato una volta deselezionato l'ultimo. Gruppo e Incursione hanno interruttori propri e partono già allineati a quello che avevi, quindi non compaiono fumetti di gruppo in una chat che non ne aveva.\n\nLa Gilda non è inclusa: Blizzard non disegna alcun fumetto per la chat di gilda, e non c'è nulla da rivestire."
