L["ClickCast Settings"] = "Impostazioni ClickCast"
L["Clickable Teleports"] = "Teletrasporti cliccabili"
L["Clickable links and player names on lines with shortened channel names now respond exactly where they appear, and the wheel scrolls into restored history right after a reload."] = "I link e i nomi dei giocatori cliccabili sulle righe con nomi di canale abbreviati ora rispondono esattamente dove appaiono, e la rotella scorre nella cronologia ripristinata subito dopo un ricaricamento."
L["Clique controls click-casting on the same Raid Frames as EllesmereUI's HoverCast, so they conflict. Disable the Clique addon to use HoverCast."] = "Clique controlla il click-casting sugli stessi Riquadri incursione di HoverCast di EllesmereUI, quindi sono in conflitto. Disattiva l'addon Clique per usare HoverCast."
L["Clique"] = true
