L["Closes an open menu without using anything. Escape always does this as well. One key shared by every menu, claimed only while a menu is up -- a mouse button keeps its normal use the rest of the time."] = "Chiude un menu aperto senza usare nulla. Anche Esc lo fa sempre. Un tasto condiviso da ogni menu, riservato solo mentre un menu è aperto -- un pulsante del mouse mantiene il suo uso normale nel resto del tempo."
L["Closes an open menu without using anything. Escape always does this as well. One key shared by every menu, claimed only while a menu is up -- a mouse button keeps its normal use the rest of the time.\n\nLeft-click to set a keybind, then press any key or\nclick any mouse button to use it.\nEscape cancels. Right-click here to unbind."] = "Chiude un menu aperto senza usare nulla. Anche Esc lo fa sempre. Un tasto condiviso da ogni menu, riservato solo mentre un menu è aperto -- un pulsante del mouse mantiene il suo uso normale nel resto del tempo.\n\nClic sinistro per impostare un'associazione tasti, poi premi un tasto qualsiasi o\nfai clic su un pulsante del mouse per usarlo.\nEsc annulla. Clic destro qui per rimuovere l'associazione."
L["Cobra Shot"] = "Colpo di Cobra" -- NAO-OFICIAL
L["Coin Colored"] = "Colorato come le monete"
L["Coin Icons"] = "Icone monete"
L["Collapse Sidebar"] = "Comprimi barra laterale"
L["Collapse subgroups that have no members so the remaining groups close ranks. For example, if only groups 1, 2, 3 and 6 have players, they show with no gaps instead of leaving empty space where groups 4 and 5 would be. Real raid frames only."] = "Comprime i sottogruppi senza membri in modo che i gruppi rimanenti si compattino. Ad esempio, se solo i gruppi 1, 2, 3 e 6 hanno giocatori, vengono mostrati senza spazi vuoti invece di lasciare spazio libero dove sarebbero i gruppi 4 e 5. Solo riquadri incursione reali."
L["Collapses the windows back to the icon on their own after they've been open (and the cursor hasn't been over them) for the delay below -- the same result as clicking the close button, just on a timer. Moving the cursor over the windows pauses the timer and it starts over once you look away."] = "Le finestre si riducono da sole all'icona dopo essere rimaste aperte (senza il cursore sopra di esse) per il ritardo sottostante -- lo stesso risultato di un clic sul pulsante di chiusura, ma con un timer. Spostare il cursore sopra le finestre mette in pausa il timer, che riparte una volta distolto lo sguardo."
L["Collections Journal"] = "Diario delle collezioni"
L["Collections"] = "Collezioni"
L["Color Bands"] = "Fasce di colore"
L["Color Name by Reaction"] = "Colora il nome in base alla reazione"
L["Color Out of Melee Range"] = "Colore fuori dalla portata di mischia"
L["Color Out of Range"] = "Colore fuori portata"
L["Color Picker"] = "Selettore colore"
L["Color by Rarity"] = "Colora per rarità"
L["Color by Type (Magic/Enrage)"] = "Colora per tipo (Magia/Furia)"
L["Color by Type"] = "Colora per tipo"
L["Color of the flat overlay behind the Compact Band's buttons."] = "Colore della sovrapposizione piatta dietro i pulsanti della Fascia compatta."
L["Color of the out-of-range darken overlay. Defaults to gray -- pick something else if it's hard to see against your Fill Color."] = "Colore della sovrapposizione di oscuramento fuori portata. Il valore predefinito è grigio -- scegline un altro se è difficile da vedere rispetto al tuo Colore riempimento."
L["Color the bar by ranges instead of a single threshold.\nUp to (<=) / From (>=)\nAny remaning values outside the bands will use fill color.\n|cff888888Bars can use % or actual value; pip resources use counts.|r"] = "Colora la barra in base a intervalli invece di una singola soglia.\nFino a (<=) / Da (>=)\nQualsiasi valore rimanente fuori dalle fasce userà il colore di riempimento.\n|cff888888Le barre possono usare % o il valore reale; le risorse a pip usano i conteggi.|r"
L["Color the bar differently at several stack counts. The highest count you have reached wins."] = "Colora la barra in modo diverso a più conteggi di cariche. Vince il conteggio più alto raggiunto."
L["Color the health bar by how much health is left, instead of a flat color. Classic runs green at full health through yellow to red at empty. Custom Colors blends between the three stop swatches on this row -- full (100%), half (50%) and empty (0%). Class Reactive shows the class color at full health, bleeding into the 50% and 0% colors as the unit takes damage. Off leaves the flat Fill Color swatches in charge; either way the Gradient below still applies, running from whichever color this picks."] = "Colora la barra salute in base alla salute rimanente, invece di un colore uniforme. Classico va dal verde a salute piena, passando per il giallo, fino al rosso a salute vuota. Colori personalizzati sfuma tra i tre campioni di colore su questa riga -- pieno (100%), metà (50%) e vuoto (0%). Reattivo alla classe mostra il colore di classe a salute piena, sfumando nei colori del 50% e dello 0% man mano che l'unità subisce danni. Off lascia il comando ai campioni di Colore riempimento uniforme; in entrambi i casi il Gradiente sottostante continua ad applicarsi, partendo dal colore scelto qui."
L["Colored Empowered Stages"] = "Fasi di potenziamento colorate"
L["Colored Percentages"] = "Percentuali colorate"
L["Colored Values"] = "Valori colorati"
L["Colors are shared globally from the \"%1$s\" profile.\nSwitch to it (or set Pull Colors From to this profile) to edit."] = "I colori sono condivisi globalmente dal profilo \"%1$s\".\nPassa ad esso (oppure imposta Preleva colori da su questo profilo) per modificarli."
L["Colors enemy nameplates for quest mobs you still need to kill."] = "Colora le targhette nemiche dei mob missione che devi ancora uccidere."
L["Colors group and raid member names by their class when they appear in the text of Say, Yell, Party, and Raid messages."] = "Colora i nomi dei membri di gruppo e incursione in base alla loro classe quando appaiono nel testo dei messaggi Dire, Urlare, Gruppo e Incursione."
L["Colors the cast segment during which your interrupt will be available."] = "Colora il segmento di lancio durante il quale la tua interruzione sarà disponibile."
L["Colors the enemy nameplate name text to match the unit's reaction (Hostile or Neutral) instead of the Enemy Name Text color."] = "Colora il testo del nome sulla targhetta nemica in base alla reazione dell'unità (Ostile o Neutrale) invece del colore Testo nome nemico."
L["Colors the full-size spell icon border with your target border color while the cast bar wrap border is active."] = "Colora il bordo dell'icona incantesimo a grandezza intera con il colore del bordo bersaglio mentre il bordo avvolgente della barra di lancio è attivo."
