L["EllesmereUI WonderBar was renamed to EllesmereUI DataBars. The old WonderBar addon is still installed and both create the same bar. Please disable or delete the EllesmereUIWonderBar addon."] = "EllesmereUI WonderBar è stato rinominato in EllesmereUI DataBars. Il vecchio addon WonderBar è ancora installato ed entrambi creano la stessa barra. Disattiva o elimina l'addon EllesmereUIWonderBar."
