L["EllesmereUI could not save this change to your Edit Mode layout, so it has to be set by hand. The Cooldown Manager has to be off while you do it, because it hides Blizzard's cooldown viewers and a hidden viewer cannot be selected in Edit Mode.\n\n"] = "EllesmereUI non è riuscito a salvare questa modifica nel tuo layout Modalità modifica, quindi deve essere impostata manualmente. Il Gestore recuperi deve essere disattivato mentre lo fai, perché nasconde i visualizzatori dei tempi di recupero di Blizzard e un visualizzatore nascosto non può essere selezionato in Modalità modifica.\n\n"
L["EllesmereUI could not save this change to your Edit Mode layout, so it has to be set by hand. The Cooldown Manager has to be off while you do it, because it hides Blizzard's cooldown viewers and a hidden viewer cannot be selected in Edit Mode.\n\n1. Disable EllesmereUI Cooldown Manager (button below).\n2. Open Edit Mode from the Game Menu.\n3. Select each Cooldown Manager viewer and set Visibility to Always.\n4. On Tracked Buffs and Tracked Bars, tick Hide When Inactive.\n5. Save the layout and leave Edit Mode.\n6. Re-enable EllesmereUI Cooldown Manager."] = "EllesmereUI non è riuscito a salvare questa modifica nel tuo layout Modalità modifica, quindi deve essere impostata manualmente. Il Gestore recuperi deve essere disattivato mentre lo fai, perché nasconde i visualizzatori dei tempi di recupero di Blizzard e un visualizzatore nascosto non può essere selezionato in Modalità modifica.\n\n1. Disattiva il Gestore recuperi di EllesmereUI (pulsante sottostante).\n2. Apri Modalità modifica dal Menu di gioco.\n3. Seleziona ogni visualizzatore del Gestore recuperi e imposta Visibilità su Sempre.\n4. Su Potenziamenti monitorati e Barre monitorate, seleziona Nascondi quando inattivo.\n5. Salva il layout ed esci da Modalità modifica.\n6. Riattiva il Gestore recuperi di EllesmereUI."
L["EllesmereUI has updated your CDM Edit Mode settings to ensure cooldown tracking works correctly.\n\nA UI reload is required for the changes to take effect."] = "EllesmereUI ha aggiornato le tue impostazioni CDM di Modalità modifica per assicurare che il monitoraggio dei tempi di recupero funzioni correttamente.\n\nÈ necessario un ricaricamento dell'interfaccia perché le modifiche abbiano effetto."
L["EllesmereUI matches the window-skin shell; Modern is a flat color."] = "EllesmereUI corrisponde al guscio della skin finestre; Moderno è un colore uniforme."
L["EllesmereUI restyles Blizzard's chat bubbles and turns on the switches it needs. Party and Raid keep your current setting, and everything is put back when you turn this off."] = "EllesmereUI riveste i fumetti chat di Blizzard e attiva gli interruttori necessari. Gruppo e Incursione mantengono la tua impostazione attuale, e tutto viene ripristinato quando disattivi questa opzione."
