L["Hide and show every damage meter window at once. The state is not saved; a reload restores the configured visibility.\n\nThe bound key is taken over while it is set. Use the cog to include the combat timer and Spell History.\n\nLeft-click to set a keybind.\nRight-click to unbind."] = "Nascondi e mostra tutte le finestre del misuratore danni contemporaneamente. Lo stato non viene salvato; un ricaricamento ripristina la visibilità configurata.\n\nIl tasto associato viene riservato mentre è impostato. Usa l'ingranaggio per includere il timer di combattimento e Cronologia incantesimi.\n\nClic sinistro per impostare un'associazione tasti.\nClic destro per rimuovere l'associazione."
L["Hide combat indicator preview"] = "Nascondi anteprima indicatore combattimento"
L["Hide consumable items (potions, healthstone) from the bar when you have none in your bags, instead of showing them dimmed. They reappear automatically once you have the item again."] = "Nascondi gli oggetti consumabili (pozioni, pietra della salute) dalla barra quando non ne hai nelle borse, invece di mostrarli attenuati. Riappaiono automaticamente non appena hai di nuovo l'oggetto."
L["Hide crafted items from the gear tile list.\nCrafted items cannot be upgraded at the Upgrade NPC."] = "Nascondi gli oggetti lavorati dall'elenco delle caselle equipaggiamento.\nGli oggetti lavorati non possono essere migliorati presso il PNG Miglioramenti."
L["Hide debuffs on preview"] = "Nascondi indebolimenti nell'anteprima"
L["Hide defensives on preview"] = "Nascondi difensivi nell'anteprima"
L["Hide dispel overlay preview"] = "Nascondi anteprima sovrapposizione dissolvimento"
L["Hide dispels on preview"] = "Nascondi dissolvimenti nell'anteprima"
L["Hide enemy nameplates while you are out of combat; they return the moment combat starts. Drives the same game setting as the Show Enemy Name Plates keybind."] = "Nascondi le targhette nemiche mentre sei fuori dal combattimento; tornano nel momento in cui inizia il combattimento. Comanda la stessa impostazione di gioco dell'associazione tasti Mostra targhette nome nemico."
L["Hide entries this character cannot use: another class's specializations and spells, and macros this character does not have. One shared menu then fits every character. The menu editor always shows every entry."] = "Nascondi le voci che questo personaggio non può usare: specializzazioni e incantesimi di un'altra classe, e macro che questo personaggio non ha. Un unico menu condiviso si adatta così a ogni personaggio. L'editor del menu mostra sempre ogni voce."
L["Hide every Cooldown Manager glow out of combat and bring them all back the moment you enter combat."] = "Nascondi ogni bagliore del Gestore recuperi fuori dal combattimento e riportali tutti indietro nel momento in cui entri in combattimento."
L["Hide every Cooldown Manager glow while you are out of combat: proc glows, active state, max stacks, buff and pandemic glows, cooldown ready glows and bar glows.\n\nThey come back the moment you enter combat, including a glow that started before the pull.\n\nApplies to every CDM bar and to the Tracking Bars at once. Glows from other EllesmereUI modules are not affected.\n\nThe Bar Glows page keeps its own per-mapping Only In Combat toggle; this one applies on top of it."] = "Nascondi ogni bagliore del Gestore recuperi mentre sei fuori dal combattimento: bagliori proc, stato attivo, cariche massime, bagliori potenziamento e pandemic, bagliori CD pronto e bagliori barra.\n\nTornano nel momento in cui entri in combattimento, incluso un bagliore iniziato prima del pull.\n\nSi applica a ogni barra CDM e alle Barre di monitoraggio contemporaneamente. I bagliori di altri moduli EllesmereUI non sono interessati.\n\nLa pagina Bagliori barra mantiene il proprio interruttore Solo in combattimento per mappatura; questo si applica sopra di esso."
L["Hide friendly player health bars and instead only see their names.\n\nRequires 'Simplified Friendly Nameplates' to be disabled in Blizzard's Nameplate settings (Esc > Options > Nameplates)."] = "Nascondi le barre salute dei giocatori amici e mostra solo i loro nomi.\n\nRichiede che 'Targhette amiche semplificate' sia disattivato nelle impostazioni Targhette di Blizzard (Esc > Opzioni > Targhette)."
L["Hide heal absorb preview"] = "Nascondi anteprima assorbimento cura"
