L["Hide shield effects on preview"] = "Nascondi effetti scudo nell'anteprima"
L["Hide sidebar categories that have no items in them."] = "Nascondi le categorie della barra laterale che non contengono oggetti."
L["Hide targeted spells on preview"] = "Nascondi incantesimi mirati nell'anteprima"
L["Hide the 1-pixel border around the cast bar spell icon."] = "Nascondi il bordo di 1 pixel attorno all'icona dell'incantesimo della barra di lancio."
L["Hide the 1-pixel outline around the bar."] = "Nascondi il contorno di 1 pixel attorno alla barra."
L["Hide the Reset Data button from the damage meter header."] = "Nascondi il pulsante Reimposta dati dall'intestazione del misuratore danni."
L["Hide the brief GCD swipe that flashes when you cast any spell. The actual ability cooldown swipe still shows."] = "Nascondi il breve swipe GCD che lampeggia quando lanci un incantesimo qualsiasi. Lo swipe del tempo di recupero effettivo dell'abilità rimane visibile."
L["Hide the charge number on action buttons when it reaches 0, instead of showing a 0. The number returns as soon as a charge or item comes back."] = "Nascondi il numero delle cariche sui pulsanti azione quando raggiunge 0, invece di mostrare uno 0. Il numero ritorna non appena una carica o un oggetto torna disponibile."
L["Hide the charge number while a spell has no charges left, instead of showing a 0. The number returns as soon as a charge comes back."] = "Nascondi il numero delle cariche mentre un incantesimo non ha più cariche, invece di mostrare uno 0. Il numero ritorna non appena torna una carica."
L["Hide the enemy name text while that nameplate's cast bar is visible."] = "Nascondi il testo del nome nemico mentre la barra di lancio di quella targhetta è visibile."
L["Hide the icon texture, border, and duration swipe, leaving only the stack count. Forces icon opacity, border, and duration swipe off."] = "Nascondi la texture, il bordo e lo swipe di durata dell'icona, lasciando solo il conteggio cariche. Forza la disattivazione di opacità icona, bordo e swipe di durata."
L["Hide the preview"] = "Nascondi l'anteprima"
L["Hide the randomize (dice) button in the OneBag view."] = "Nascondi il pulsante randomizza (dado) nella vista OneBag."
L["Hide the tooltip when hovering a buff/HoT icon on a raid or party frame."] = "Nascondi il tooltip quando passi il mouse su un'icona di potenziamento/HoT su un riquadro incursione o gruppo."
L["Hide the warning text at the top of the OneBag and MultiBag views."] = "Nascondi il testo di avviso in cima alle viste OneBag e MultiBag."
L["Hide the warning text at the top of the OneBag view."] = "Nascondi il testo di avviso in cima alla vista OneBag."
L["Hide these instead of showing them"] = "Nascondi questi invece di mostrarli"
L["Hide this bar completely while out of combat, even when the tracked buff/cooldown is active."] = "Nascondi completamente questa barra mentre sei fuori dal combattimento, anche quando il potenziamento/tempo di recupero monitorato è attivo."
L["Hide this bar's icon art, cooldown swipe, recharge edge and cooldown text, leaving only the charge or stack count."] = "Nascondi la grafica dell'icona, lo swipe del tempo di recupero, il bordo di ricarica e il testo del tempo di recupero di questa barra, lasciando solo il conteggio cariche."
L["Hide this bar's icons and show only the duration text."] = "Nascondi le icone di questa barra e mostra solo il testo della durata."
L["Hide when Dragonriding"] = "Nascondi durante la Cavalcata Draconica" -- TODO: confirmar termo oficial (Dragon Riding)
L["Hide when Mounted"] = "Nascondi quando in cavalcatura"
L["Hide when Skyriding Mounted"] = "Nascondi quando in cavalcatura Skyriding"
L["Hide while this condition is true"] = "Nascondi mentre questa condizione è vera"
L["Hide without Enemy Target"] = "Nascondi senza bersaglio nemico"
L["Hide without Target"] = "Nascondi senza bersaglio"
L["Hides Blizzard's \"Loot Rolls\" window -- the running list of dropped items showing who rolled what and who won. Use the cog to let it appear briefly and close itself instead. The Need/Greed roll popups themselves are not affected."] = "Nasconde la finestra \"Tiri per il bottino\" di Blizzard -- l'elenco continuo degli oggetti droppati che mostra chi ha tirato cosa e chi ha vinto. Usa l'ingranaggio per farla apparire brevemente e chiudersi da sola. I popup di tiro Necessario/Avidità stessi non sono interessati."
L["Hides Blizzard's own micro menu while any bar has this on."] = "Nasconde il menu micro di Blizzard mentre qualsiasi barra ha questa opzione attiva."
L["Hides Blizzard's tutorial UI: the yellow HelpTip bubbles and the glowing (i) help-plate buttons on the spellbook, talents, map, collections, and other panels."] = "Nasconde l'interfaccia tutorial di Blizzard: i fumetti gialli HelpTip e i pulsanti luminosi (i) di aiuto sul libro degli incantesimi, talenti, mappa, collezioni e altri pannelli."
L["Hides Pinned Items. Re-show in settings."] = "Nasconde gli oggetti appuntati. Mostrali di nuovo nelle impostazioni."
L["Hides Recent Items. Re-show in settings."] = "Nasconde gli oggetti recenti. Mostrali di nuovo nelle impostazioni."
L["Hides most red error messages (such as 'Not enough rage' or 'Ability is not ready yet'). Important errors like a full bag or quest log are still shown."] = "Nasconde la maggior parte dei messaggi di errore rossi (come 'Ira insufficiente' o 'Abilità non ancora pronta'). Gli errori importanti come una borsa piena o il registro missioni pieno vengono comunque mostrati."
L["Hides the 'Screenshot saved' notification that appears on screen after taking a screenshot."] = "Nasconde la notifica 'Screenshot salvato' che appare sullo schermo dopo aver scattato uno screenshot."
L["Hides the Add Category button at the bottom of the bag sidebar."] = "Nasconde il pulsante Aggiungi categoria in fondo alla barra laterale della borsa."
L["Hides the EllesmereUI button from the game's Escape/pause menu."] = "Nasconde il pulsante EllesmereUI dal menu Esc/pausa del gioco."
L["Hides the Lua error popup. The same setting as Global Settings > Developer."] = "Nasconde il popup di errore Lua. La stessa impostazione di Impostazioni globali > Sviluppatore."
L["Hides the Top Bar Event Text mover in Unlock Mode while keeping its saved position applied."] = "Nasconde lo spostamento di Testo evento Barra superiore in Modalità sblocco, mantenendo applicata la sua posizione salvata."
L["Hides the Unlock Mode button from the game's Escape/pause menu. You can still toggle Unlock Mode from the EUI options panel."] = "Nasconde il pulsante Modalità sblocco dal menu Esc/pausa del gioco. Puoi comunque attivare/disattivare la Modalità sblocco dal pannello opzioni EUI."
L["Hides the collapsed Blizzard party/raid sidebar panel on the side of the screen."] = "Nasconde il pannello laterale compresso gruppo/incursione di Blizzard sul lato dello schermo."
L["Hides the health bar Blizzard shows at the bottom of unit tooltips."] = "Nasconde la barra salute che Blizzard mostra in fondo ai tooltip delle unità."
L["Hides the large NPC dialogue popup that appears during quests and dungeons."] = "Nasconde il grande popup di dialogo PNG che appare durante missioni e dungeon."
L["Hides the loot window movers in Unlock Mode while keeping their saved positions applied."] = "Nasconde gli spostamenti della finestra bottino in Modalità sblocco, mantenendo applicate le loro posizioni salvate."
L["Hides the master header and its minimize button at the top of the tracker. When shown, it's skinned to match the section headers below it (Quests, Achievements, ...)."] = "Nasconde l'intestazione principale e il suo pulsante di riduzione in cima al tracciamento. Quando mostrata, è rivestita per abbinarsi alle intestazioni di sezione sottostanti (Missioni, Obiettivi, ...)."
L["Hides the rank number (1. 2. 3.) before each player name."] = "Nasconde il numero di rango (1. 2. 3.) prima di ogni nome giocatore."
L["Hides the ready check glyph above the prompt, leaving just the question and the Yes / No buttons. Applies while the Ready Check reskin is enabled."] = "Nasconde il glifo del controllo di prontezza sopra il messaggio, lasciando solo la domanda e i pulsanti Sì / No. Si applica mentre il restyling di Controllo prontezza è attivo."
L["Hides the resize handle on the main chat frame, preventing accidental resizing."] = "Nasconde la maniglia di ridimensionamento sul riquadro chat principale, evitando ridimensionamenti accidentali."
L["Hides the sync icons on the sidebar module list."] = "Nasconde le icone di sincronizzazione nell'elenco moduli della barra laterale."
L["Hides this element while you are on a skyriding (glide-capable) mount, where Blizzard shows its vigor HUD."] = "Nasconde questo elemento mentre sei su una cavalcatura Skyriding (capace di planare), dove Blizzard mostra il suo HUD del vigore."
