L["Hold a key to open a menu of actions; point or scroll to choose, release to fire."] = "Tieni premuto un tasto per aprire un menu di azioni; punta o scorri per scegliere, rilascia per attivare."
L["Hold a keybind to open a menu of actions; point or scroll to choose, release to fire. Build up to 16 menus in Arc, Fan, or Grid layouts, nest menus inside menus, and tune every setting per menu."] = "Tieni premuta un'associazione tasti per aprire un menu di azioni; punta o scorri per scegliere, rilascia per attivare. Crea fino a 16 menu in layout ad Arco, Ventaglio o Griglia, annida menu dentro altri menu, e personalizza ogni impostazione per menu."
L["Hold a keybind to open a menu of actions; point or scroll to choose, release to fire."] = "Tieni premuta un'associazione tasti per aprire un menu di azioni; punta o scorri per scegliere, rilascia per attivare."
L["Hold a keybind to open a palette of actions; point or scroll to choose, release to fire."] = "Tieni premuta un'associazione tasti per aprire una tavolozza di azioni; punta o scorri per scegliere, rilascia per attivare."
L["Holds the block at this width and clips longer text, so a plugin whose text keeps changing length never shifts the blocks beside it. Zero sizes the block to whatever the plugin currently says."] = "Mantiene il blocco a questa larghezza e ritaglia il testo più lungo, così un plugin il cui testo cambia continuamente lunghezza non sposta mai i blocchi accanto ad esso. Zero dimensiona il blocco in base a ciò che il plugin indica al momento."
