L["Hovering names in the Guild & Communities roster no longer errors, and member tooltips keep their race and class lines."] = "Passare il mouse sui nomi nell'elenco di Gilda e Comunità non genera più errori, e i tooltip dei membri mantengono le righe di razza e classe."
L["How Blizzard's next-spell suggestion is drawn on the button. Button Overlay replaces the blue ring with a flat tint, leaving the button edge free for the proc glow."] = "Come viene disegnato sul pulsante il suggerimento del prossimo incantesimo di Blizzard. Sovrapposizione pulsante sostituisce l'anello blu con una tinta uniforme, lasciando libero il bordo del pulsante per il bagliore proc."
L["How extra columns grow when the second column appears or disappears. Grow Right keeps the left column in place, Grow Left keeps the right column in place, Grow Centered keeps the bar centered."] = "Come crescono le colonne extra quando la seconda colonna appare o scompare. Cresci a destra mantiene la colonna sinistra al suo posto, Cresci a sinistra mantiene la colonna destra al suo posto, Crescita centrata mantiene la barra centrata."
L["How extra rows grow when the second row appears or disappears. Grow Down keeps the top row in place, Grow Up keeps the bottom row in place, Grow Centered keeps the bar centered."] = "Come crescono le righe extra quando la seconda riga appare o scompare. Cresci verso il basso mantiene la riga superiore al suo posto, Cresci verso l'alto mantiene la riga inferiore al suo posto, Crescita centrata mantiene la barra centrata."
L["How far along the arc a nest may spread its entries. Contained keeps it clear of the next nest either side, so two of them are never drawn on top of one another. Overflowing lets it use the whole of Max Nest Span. A nest reaches over the plain entries it passes, and they only give up their angles while it is open."] = "Fino a che punto dell'arco un nido può estendere le sue voci. Contenuto lo mantiene distante dal nido successivo su entrambi i lati, così due di essi non vengono mai disegnati uno sopra l'altro. Straboccante gli permette di usare l'intera Estensione massima nido. Un nido si estende sopra le voci semplici che attraversa, e queste cedono i loro angoli solo mentre è aperto."
L["How far along the arc a nest may spread its entries. Contained keeps it clear of the next nest either side, so two of them are never drawn on top of one another. Overflowing lets it use the whole of Max Nest Span."] = "Fino a che punto dell'arco un nido può estendere le sue voci. Contenuto lo mantiene distante dal nido successivo su entrambi i lati, così due di essi non vengono mai disegnati uno sopra l'altro. Straboccante gli permette di usare l'intera Estensione massima nido."
L["How far along the arc a nest may spread its entries."] = "Fino a che punto dell'arco un nido può estendere le sue voci."
L["How long the windows stay open, cursor off them, before Auto-Minimize collapses them."] = "Per quanto tempo le finestre restano aperte, con il cursore lontano da esse, prima che Riduzione automatica le comprima."
L["How many decimal places the number carries."] = "Quante cifre decimali porta il numero."
L["How many entries a row of the grid holds. 1 stacks them into a single column; %1$s -- the most slots an action menu can hold -- lays them out in a single row."] = "Quante voci contiene una riga della griglia. 1 le impila in un'unica colonna; %1$s -- il massimo numero di slot che un menu azioni può contenere -- le dispone in un'unica riga."
L["How many icons to show on the base row (the row that fills first and that Row Growth keeps in place). The rest go on the second row."] = "Quante icone mostrare sulla riga base (la riga che si riempie per prima e che Crescita riga mantiene al suo posto). Il resto va sulla seconda riga."
L["How many icons to show on the bottom row. The rest go on the top row."] = "Quante icone mostrare sulla riga inferiore. Il resto va sulla riga superiore."
L["How many icons to show on the top row. The rest go on the bottom row."] = "Quante icone mostrare sulla riga superiore. Il resto va sulla riga inferiore."
L["How many pixels the custom effect extends beyond the icon."] = "Di quanti pixel l'effetto personalizzato si estende oltre l'icona."
L["How much is trimmed from the icon's top and bottom, as a percentage per side. 10% is the classic cropped look."] = "Quanto viene ritagliato dalla parte superiore e inferiore dell'icona, in percentuale per lato. 10% è l'aspetto ritagliato classico."
L["How precise the coordinates read. More decimals make the block wider."] = "Quanto sono precise le coordinate mostrate. Più decimali rendono il blocco più largo."
L["How wide the block stays, whatever the zone is called."] = "Quanto resta largo il blocco, qualunque sia il nome della zona."
