L["In raid groups under 10 players, show group 1 as party frames and hide everyone else."] = "Nei gruppi di incursione con meno di 10 giocatori, mostra il gruppo 1 come riquadri gruppo e nascondi tutti gli altri."
L["In the All Items bag view, show each category's items under indented expansion sub-headers (newest expansions first), even when everything in that category is from one expansion."] = "Nella vista borsa Tutti gli oggetti, mostra gli oggetti di ogni categoria sotto sotto-intestazioni rientrate per espansione (le più recenti per prime), anche quando tutto in quella categoria proviene da una sola espansione."
L["In the OneBank and OneWarbank views, split the grid under expansion headers, newest first. Per-tab views are unaffected."] = "Nelle viste OneBank e OneWarbank, dividi la griglia sotto intestazioni per espansione, le più recenti per prime. Le viste per singola scheda non sono interessate."
