L["Include fonts, custom colours, dark mode, accent colour and UI scale with this export. Off = only the selected modules' own settings export, keeping the recipient's global look."] = "Includi caratteri, colori personalizzati, modalità scura, colore accento e scala interfaccia in questa esportazione. Off = vengono esportate solo le impostazioni proprie dei moduli selezionati, mantenendo l'aspetto globale del destinatario."
