L["Include your Blizz UI Enhanced settings from the Window Skins and Tooltips, Menus & Popups tabs. These are account-wide: if the importer opts in, they overwrite that player's settings across ALL of their profiles."] = "Includi le tue impostazioni di Blizz UI Enhanced dalle schede Rivestimenti finestra e Tooltip, menu e popup. Queste sono valide per l'intero account: se chi importa le accetta, sovrascrivono le impostazioni di quel giocatore su TUTTI i suoi profili."
L["Include your Cooldown Manager spell layout (which spells sit on which bars) plus all per-spell settings for any specs you choose."] = "Includi il layout degli incantesimi di Cooldown Manager (quali incantesimi si trovano su quali barre) più tutte le impostazioni per singolo incantesimo per le specializzazioni che scegli."
L["Include your complete override setup: spec and conditional override values, groups, their custom Unlock Mode layouts, and Buff Manager overrides. On import this replaces the recipient's overrides entirely."] = "Includi la tua configurazione completa delle sostituzioni: valori di sostituzione per specializzazione e condizionali, gruppi, i loro layout personalizzati in Modalità sblocco e le sostituzioni di Buff Manager. All'importazione questo sostituisce interamente le sostituzioni del destinatario."
