L["Keep Action Bar 1 on its current page when you shapeshift, stealth, or change stance, instead of swapping to that form's bar.\n\nKeybinds follow what the bar shows, so the key always casts the icon you see. Press-and-hold repeat casting is turned off on Action Bar 1 while this is enabled."] = "Mantieni la Barra azione 1 sulla sua pagina attuale quando cambi forma, ti nascondi o cambi posizione di combattimento, invece di passare alla barra di quella forma.\n\nLe associazioni tasti seguono ciò che la barra mostra, quindi il tasto lancia sempre l'icona che vedi. Il lancio ripetuto tenendo premuto viene disattivato sulla Barra azione 1 mentre questa opzione è attiva."
L["Keep Action Bar 1 on its current page while skyriding, instead of swapping to the skyriding bar.\n\nYour skyriding abilities live on that bar, so put them on another bar before enabling this. Press-and-hold repeat casting is turned off on Action Bar 1 while this is enabled."] = "Mantieni la Barra azione 1 sulla sua pagina attuale mentre voli con lo skyriding, invece di passare alla barra dello skyriding.\n\nLe tue abilità di skyriding si trovano su quella barra, quindi posizionale su un'altra barra prima di attivare questa opzione. Il lancio ripetuto tenendo premuto viene disattivato sulla Barra azione 1 mentre questa opzione è attiva."
L["Keep Buffs in Same Place"] = "Mantieni i potenziamenti nella stessa posizione"
L["Keep Colored (On CD)"] = "Mantieni colorato (in tempo di recupero)"
L["Keep Enabled"] = "Mantieni attivato"
L["Keep Focus Full Opacity"] = "Mantieni opacità piena sul focus"
L["Keep Keys on Bar Swap (global)"] = "Mantieni i tasti al cambio barra (globale)"
L["Keep Mine"] = "Mantieni il mio"
L["Keep Raid Frames"] = "Mantieni riquadri incursione"
L["Keep keybind text identical when your action bar swaps -- rogue stealth, druid forms, skyriding. Also covers conditional macros like \"/cast [bonusbar:1] Backstab; Shadow Dance\", where the key would otherwise jump to whichever branch is live.\n\nThe key then only changes when you actually move the ability or rebind it.\n\nOn by default. Applies to every CDM bar at once."] = "Mantieni identico il testo di associazione tasti quando la tua barra azione cambia -- furtività ladro, forme druido, skyriding. Copre anche le macro condizionali come \"/cast [bonusbar:1] Pugnalata alle Spalle; Danza dell'Ombra\", dove altrimenti il tasto salterebbe al ramo attivo di volta in volta.\n\nIl tasto cambia quindi solo quando sposti davvero l'abilità o la riassoci.\n\nAttivo per impostazione predefinita. Si applica a ogni barra CDM contemporaneamente."
L["Keep the GCD bar visible (sitting empty) when no global cooldown is running, instead of hiding it."] = "Mantieni visibile la barra GCD (vuota) quando non è in corso nessun tempo di recupero globale, invece di nasconderla."
L["Keep the cast bar visible (sitting empty) when you are not casting, instead of hiding it."] = "Mantieni visibile la barra di lancio (vuota) quando non stai lanciando, invece di nasconderla."
L["Keep the item count visible and show 0 instead of hiding it when you have none of the item (e.g. potions, healthstone)."] = "Mantieni visibile la quantità oggetto e mostra 0 invece di nasconderla quando non ne possiedi nessuno (ad es. pozioni, pietra della salute)."
L["Keep the timer visible out of combat, showing the last fight's duration."] = "Mantieni visibile il timer fuori dal combattimento, mostrando la durata dell'ultimo combattimento."
L["Keep this menu open when you let go of its keybind.\nPoint at an entry and press the Select Action key to use it.\nPress the menu's own keybind again, or Escape, to close it."] = "Mantieni questo menu aperto quando rilasci la sua associazione tasti.\nPunta una voce e premi il tasto Seleziona azione per usarla.\nPremi di nuovo l'associazione tasti del menu, oppure Esc, per chiuderlo."
L["Keep your own UI scale. Off = apply the UI scale this profile was made with (changes the scale for all your characters)."] = "Mantieni la tua scala dell'interfaccia. Off = applica la scala dell'interfaccia con cui è stato creato questo profilo (cambia la scala per tutti i tuoi personaggi)."
L["Keep"] = "Mantieni"
L["Keeps Artisan's Consortium Payouts closed while Shard of Dundun is at its maximum, then resumes automatic opening after you spend shards."] = "Mantiene chiusi i pagamenti del Consorzio degli Artigiani finché il Frammento di Dundun è al massimo, poi riprende l'apertura automatica dopo aver speso i frammenti."
L["Keeps Blizzard's own buff and debuff display and turns off the built-in Buffs and Debuffs bars. Custom bars keep working."] = "Mantiene la visualizzazione nativa di potenziamenti e indebolimenti di Blizzard e disattiva le barre integrate Potenziamenti e Indebolimenti. Le barre personalizzate continuano a funzionare."
L["Keeps a saved signup note you can copy into the Sign Up dialog with the Copy button."] = "Mantiene una nota di iscrizione salvata che puoi copiare nella finestra di iscrizione con il pulsante Copia."
L["Keeps the first row in place when the second row appears or disappears."] = "Mantiene la prima riga in posizione quando la seconda riga appare o scompare."
L["Keeps this bar fully visible while flying on a skyriding mount (or Druid Flight Form), or while it's paged onto the vehicle bar (Action Bar 1 while the player is in a vehicle), regardless of the Visibility mode above."] = "Mantiene questa barra completamente visibile mentre voli su una cavalcatura da skyriding (o in Forma di Volo del druido), oppure quando viene visualizzata sulla barra veicolo (Barra azione 1 mentre il giocatore è in un veicolo), indipendentemente dalla modalità Visibilità sopra." -- NAO-OFICIAL
L["Keeps your note text in the Sign Up dialog instead of clearing it each time you open it."] = "Mantiene il testo della tua nota nella finestra di iscrizione invece di cancellarlo ogni volta che la apri."
