L["Keybinds respond on key down instead of key up. This helps make your abilities feel more responsive."] = "Le associazioni tasti rispondono alla pressione invece che al rilascio del tasto. Questo rende le tue abilità più reattive."
L["Keybinds set in EllesmereUI's own key fields now fire when two or more modifiers are held (for example Ctrl+Alt+1); re-bind any that never triggered."] = "Le associazioni tasti impostate nei campi tasto propri di EllesmereUI ora si attivano quando vengono tenuti premuti due o più modificatori (ad esempio Ctrl+Alt+1); riassocia quelle che non si sono mai attivate."
