L["Liquid Luster is available as a Custom Buff Bar potion preset alongside Light's Potential and Potion of Recklessness."] = "Lucentezza Liquida è disponibile come preset pozione per Barra potenziamenti personalizzata insieme a Potenziale della Luce e Pozione della Sconsideratezza."
