L["List item categories in the bank sidebar the way the bags sidebar does -- groups such as The Armory with Weapons and Armor under them. Selecting one filters the grid to that category. Categories that split further list their parts as a third level while selected: Professions by profession, Armor by equipment slot, Trade Goods by material. Spans your character bank and warband together, so a category shows everything you own."] = "Elenca le categorie degli oggetti nella barra laterale della banca come fa quella delle borse -- gruppi come Armeria con Armi e Armatura sotto di essa. Selezionandone una filtri la griglia su quella categoria. Le categorie che si suddividono ulteriormente elencano le loro parti come terzo livello quando selezionate: Professioni per professione, Armatura per slot di equipaggiamento, Materiali da commercio per materiale. Copre insieme la banca del tuo personaggio e quella del warband, così una categoria mostra tutto ciò che possiedi." -- JARGAO (warband mantido em inglês, mesma decisão já usada em "Warbound")
L["Lists every group member against the consumables a raid expects -- flask, food, augment rune, vantus -- whenever a ready check starts, whoever started it."] = "Confronta ogni membro del gruppo con i consumabili attesi in un'incursione -- fiala, cibo, runa di potenziamento, runa Vantus -- ogni volta che parte un controllo di preparazione, chiunque lo abbia avviato."
L["Lists only the people something is actually wrong with, so a thirty-man roster becomes the three names you need to whisper. Someone whose client has not reported yet is not counted as missing."] = "Elenca solo le persone che hanno effettivamente qualcosa che non va, così un roster di trenta persone diventa i tre nomi a cui devi scrivere in privato. Chi ha un client che non ha ancora segnalato non viene conteggiato come mancante."
