L["Major catch-ups for German, Korean, Brazilian Portuguese, Simplified Chinese, and Traditional Chinese, plus Bags menus, prompts, and bank headers now translate."] = "Grandi recuperi per tedesco, coreano, portoghese brasiliano, cinese semplificato e cinese tradizionale, inoltre ora sono tradotti i menu delle Borse, le richieste e le intestazioni della banca."
