L["Make friendly player and NPC nameplates click-through so their names never block your mouse or cause accidental friendly targeting.\n\nUse this when friendly names get in the way of clicking the world or the enemy nameplates behind them."] = "Rendi le targhette di giocatori e PNG amici trasparenti al clic, così i loro nomi non bloccano mai il mouse né causano bersagli amici accidentali.\n\nUsa questa opzione quando i nomi amici intralciano il clic sul mondo o sulle targhette nemiche dietro di essi."
L["Make the spell icon a large square the combined height of the health bar plus the cast bar, flush with the top of the health bar and the bottom of the cast bar."] = "Rendi l'icona dell'incantesimo un grande quadrato con l'altezza combinata della barra della salute più la barra di lancio, allineato al bordo superiore della barra della salute e al bordo inferiore della barra di lancio."
L["Makes partially filled Soul Shards and Essence darker than completed ones."] = "Rende i Frammenti d'Anima e l'Essenza parzialmente pieni più scuri rispetto a quelli completi."
L["Makes the boss frames taller or shorter relative to the raid frame size."] = "Rende i riquadri boss più alti o più bassi rispetto alla dimensione dei riquadri incursione."
L["Makes the extra frames taller or shorter relative to the raid frame size."] = "Rende i riquadri extra più alti o più bassi rispetto alla dimensione dei riquadri incursione."
L["Makes the game tooltip follow your mouse cursor instead of appearing in the default screen corner. Use the arrows icon to pick the position relative to the cursor and fine-tune the X/Y offset."] = "Rende il tooltip di gioco tale da seguire il cursore del mouse invece di apparire nell'angolo predefinito dello schermo. Usa l'icona delle frecce per scegliere la posizione relativa al cursore e regolare con precisione l'offset X/Y."
L["Makes the game tooltip follow your mouse cursor instead of showing at its fixed screen position (drag the Tooltip box in Unlock Mode to change that). Use the arrows icon to pick the position relative to the cursor and fine-tune the X/Y offset."] = "Rende il tooltip di gioco tale da seguire il cursore del mouse invece di mostrarsi nella sua posizione fissa sullo schermo (trascina il riquadro Tooltip in Modalità sblocco per cambiarla). Usa l'icona delle frecce per scegliere la posizione relativa al cursore e regolare con precisione l'offset X/Y."
L["Makes this the override. It replaces the whole Visibility setting, so the conditions below no longer apply while it does. Click it again to remove the override."] = "Rende questa la sostituzione. Sostituisce l'intera impostazione Visibilità, quindi le condizioni sottostanti non si applicano più finché è attiva. Clicca di nuovo per rimuovere la sostituzione."
