L["Not overridable. These conditions are shared and can only be changed while no override is being edited. An override replaces the Visibility setting outright -- Never, Always or Mouseover -- and ignores everything set here while it applies. Mouseover is sealed here too for this element: its hover mechanism follows the shared setting, so an override could only leave it shown."] = "Non sostituibile. Queste condizioni sono condivise e possono essere modificate solo quando nessuna sostituzione è in fase di modifica. Una sostituzione rimpiazza direttamente l'impostazione Visibilità -- Mai, Sempre o Al passaggio del mouse -- e ignora tutto ciò che è impostato qui mentre si applica. Anche qui il passaggio del mouse è bloccato per questo elemento: il suo meccanismo di hover segue l'impostazione condivisa, quindi una sostituzione potrebbe solo lasciarlo mostrato."
L["Not overridable. These conditions are shared and can only be changed while no override is being edited. An override replaces the Visibility setting outright -- Never, Always or Mouseover -- and ignores everything set here while it applies."] = "Non sostituibile. Queste condizioni sono condivise e possono essere modificate solo quando nessuna sostituzione è in fase di modifica. Una sostituzione rimpiazza direttamente l'impostazione Visibilità -- Mai, Sempre o Al passaggio del mouse -- e ignora tutto ciò che è impostato qui mentre si applica."
