L["Off (default): the cast bar fades with real transparency, matching the whole-frame Out of Range Alpha (best if you're colour-matching the frame and cast bar). On: the old behavior -- a black overlay dims the bar instead of fading it, which can't discolor a shielded/uninterruptible cast's tint but won't visually match the frame's fade."] = "Off (predefinito): la barra di lancio si dissolve con trasparenza reale, corrispondendo all'Alpha fuori portata dell'intero riquadro (ideale se stai abbinando i colori di riquadro e barra di lancio). On: il comportamento precedente -- una sovrapposizione nera oscura la barra invece di dissolverla, il che non può alterare la tinta di un lancio scudato/ininterrompibile ma non corrisponderà visivamente alla dissolvenza del riquadro."
