L["On quest mobs in the open world, replaces the quest icon with the objective progress (a kill quest shows 0/6, a percentage quest shows 50%). Falls back to the icon when no progress is available. Never shown in instances."] = "Sui mostri di missione nel mondo aperto, sostituisce l'icona di missione con il progresso dell'obiettivo (una missione di uccisione mostra 0/6, una missione percentuale mostra 50%). Torna all'icona quando il progresso non è disponibile. Mai mostrato nelle istanze."
L["On quest mobs in the open world, replaces the quest icon with the objective progress (ex: kill quests show 0/6, percentage objectives show 50%)."] = "Sui mostri di missione nel mondo aperto, sostituisce l'icona di missione con il progresso dell'obiettivo (es: le missioni di uccisione mostrano 0/6, gli obiettivi percentuali mostrano 50%)."
