L["One video walks you through the most important changes in 12.1 and how to get the most out of EllesmereUI under them. Copy the link and give it a watch before you dive in."] = "Un video ti guida attraverso i cambiamenti più importanti della 12.1 e come sfruttare al meglio EllesmereUI con essi. Copia il link e guardalo prima di iniziare."
L["One"] = "Uno"
L["One-time copy of the Raid Frames Buff Manager filters into these filters. Same-named filters are OVERWRITTEN; the two lists stay separate afterwards."] = "Copia una tantum dei filtri di Buff Manager dei Riquadri incursione in questi filtri. I filtri con lo stesso nome vengono SOVRASCRITTI; le due liste rimangono separate in seguito."
L["One-time copy of your Player Aura Bars filter setups into these filters. Same-named filters are OVERWRITTEN; the two lists stay separate afterwards."] = "Copia una tantum delle configurazioni filtro delle tue Barre aure giocatore in questi filtri. I filtri con lo stesso nome vengono SOVRASCRITTI; le due liste rimangono separate in seguito."
