L["Only Show for % Health"] = "Mostra solo per % di salute"
L["Only Show in Housing"] = "Mostra solo nelle case"
L["Only Show in Instances"] = "Mostra solo nelle istanze"
L["Only Show when Mounted"] = "Mostra solo quando in sella"
L["Only Target Out of Combat"] = "Bersaglia solo fuori dal combattimento"
L["Only Tracked Auras"] = "Solo aure monitorate"
L["Only With Multiple Boss Frames"] = "Solo con più riquadri boss"
L["Only affects the vertical (Right/Left Edge) positions"] = "Interessa solo le posizioni verticali (Bordo destro/sinistro)"
L["Only applies when Name > Target is selected."] = "Si applica solo quando è selezionato Nome > Bersaglio."
L["Only applies when Name or Name > Target is selected."] = "Si applica solo quando è selezionato Nome o Nome > Bersaglio."
L["Only applies when the selected text includes a Name."] = "Si applica solo quando il testo selezionato include un Nome."
L["Only available in Detached or Inside modes"] = "Disponibile solo in modalità Separato o Interno"
L["Only available when Portrait Mode is Detached"] = "Disponibile solo quando la Modalità ritratto è Separato"
L["Only available with Custom fill color"] = "Disponibile solo con colore di riempimento Personalizzato"
L["Only available with the 'From' direction -- it highlights the pips at/above the threshold."] = "Disponibile solo con la direzione 'Da' -- evidenzia i pip alla soglia o sopra."
L["Only color at/above threshold"] = "Colora solo alla soglia o sopra"
L["Only glow once the buff's stack count matches the comparison set via the gear."] = "Bagliore solo quando il conteggio cariche del potenziamento corrisponde al confronto impostato tramite l'ingranaggio."
L["Only if Power Bar Hidden"] = "Solo se Barra risorsa nascosta"
L["Only in Combat"] = "Solo in combattimento"
L["Only play alerts while in combat."] = "Riproduci avvisi solo in combattimento."
L["Only preset or custom buff bars can be added to all specs"] = "Solo le barre potenziamento preset o personalizzate possono essere aggiunte a tutte le specializzazioni"
L["Only recolor the fill when more than one boss frame is active at once (a multi-boss phase). With a single boss frame up, it keeps its normal color even while targeted. Off (default) recolors regardless of how many boss frames are active."] = "Ricolora il riempimento solo quando più di un riquadro boss è attivo contemporaneamente (una fase multi-boss). Con un solo riquadro boss attivo, mantiene il colore normale anche se bersagliato. Off (predefinito) ricolora indipendentemente da quanti riquadri boss sono attivi."
L["Only show buffs cast by you."] = "Mostra solo i potenziamenti lanciati da te."
L["Only show debuffs that have a duration, excluding permanent ones. Combines with the filters below; checked alone it shows every timed debuff."] = "Mostra solo gli indebolimenti con una durata, escludendo quelli permanenti. Si combina con i filtri sottostanti; selezionato da solo mostra ogni indebolimento a tempo."
L["Only show debuffs whose full duration is at most this many seconds. Combines with the filters; Unlimited applies no cap."] = "Mostra solo gli indebolimenti la cui durata totale è al massimo questo numero di secondi. Si combina con i filtri; Illimitato non applica alcun limite."
L["Only show the GCD bar for instant-cast abilities. While hard-casting or channeling a spell, the bar stays hidden (the cast bar already shows that progress)."] = "Mostra la barra GCD solo per le abilità a lancio istantaneo. Mentre lanci normalmente o canalizzi un incantesimo, la barra resta nascosta (la barra di lancio mostra già quel progresso)."
L["Only show the GCD bar while in a dungeon, raid, arena or battleground."] = "Mostra la barra GCD solo mentre sei in un dungeon, incursione, arena o campo di battaglia."
L["Only show the alert while in combat."] = "Mostra l'avviso solo in combattimento."
L["Only show the cast bar while a cast is in progress; hide it the rest of the time."] = "Mostra la barra di lancio solo mentre un lancio è in corso; nascondila il resto del tempo."
L["Only show these buffs when you cast them."] = "Mostra questi potenziamenti solo quando li lanci tu."
L["Only show this bar while the tracked buff/cooldown is active. Turn off to keep an empty bar on screen at all times."] = "Mostra questa barra solo mentre il potenziamento/tempo di recupero monitorato è attivo. Disattiva per mantenere una barra vuota sempre sullo schermo."
L["Only show this bar while the tracked buff/cooldown is active. Unchecked keeps an empty bar on screen at all times."] = "Mostra questa barra solo mentre il potenziamento/tempo di recupero monitorato è attivo. Deselezionato mantiene una barra vuota sempre sullo schermo."
L["Only shows the GCD circle while you are in combat."] = "Mostra il cerchio GCD solo mentre sei in combattimento."
L["Only shows the cast bar circle while you are in combat."] = "Mostra il cerchio della barra di lancio solo mentre sei in combattimento."
L["Only shows the cursor circle while the mouse is hidden -- that is, while you hold the left and/or right mouse button to pan the camera or move your character."] = "Mostra il cerchio del cursore solo mentre il mouse è nascosto -- cioè mentre tieni premuto il pulsante sinistro e/o destro del mouse per muovere la telecamera o il tuo personaggio."
L["Only shows the cursor circle while you are in combat."] = "Mostra il cerchio del cursore solo mentre sei in combattimento."
L["Only while AIRBORNE on a glide-capable mount or flight form. For the mount itself, ground included, use Skyriding Mount."] = "Solo mentre sei IN VOLO su una cavalcatura capace di planare o in forma di volo. Per la cavalcatura stessa, terra inclusa, usa Cavalcatura da skyriding."
L["Only while airborne on a skyriding mount."] = "Solo mentre sei in volo su una cavalcatura da skyriding."
L["Only works for Blizzard's whitelisted healer spell IDs (non-private auras)."] = "Funziona solo per gli ID incantesimo di guaritore nella whitelist di Blizzard (aure non private)."
L["Only works outside of Instances"] = "Funziona solo fuori dalle istanze"
L["Opacity of the Button Overlay tint."] = "Opacità della tinta di sovrapposizione pulsante."
L["Opacity of the background overlay. 0 removes it entirely; the 9.0.7 default is 62."] = "Opacità della sovrapposizione di sfondo. 0 la rimuove completamente; il valore predefinito 9.0.7 è 62."
L["Opacity of the bar fill; below 100 the world shows through the fill instead of the background."] = "Opacità del riempimento della barra; sotto 100 il mondo si vede attraverso il riempimento invece che lo sfondo."
L["Opacity of the bar's background; the swatch picks the Modern color."] = "Opacità dello sfondo della barra; il campione sceglie il colore Moderno."
L["Opacity of the cast bar fill; below 100 the world shows through the fill instead of the background."] = "Opacità del riempimento della barra di lancio; sotto 100 il mondo si vede attraverso il riempimento invece che lo sfondo."
L["Opacity of the cooldown swipe (the dark radial sweep); use the swatch to set its colour."] = "Opacità della spazzata del tempo di recupero (la scia radiale scura); usa il campione per impostarne il colore."
L["Opacity of the resource fill; below 100 the world shows through the fill instead of the background."] = "Opacità del riempimento della risorsa; sotto 100 il mondo si vede attraverso il riempimento invece che lo sfondo."
L["Opacity used for enemy nameplates outside the selected attack range."] = "Opacità usata per le targhette nemiche fuori dal raggio d'attacco selezionato."
