L["Others are missing my buff: remind when a groupmate is missing a buff you can cast.\nI am missing others' buffs: remind when you are missing a buff a groupmate could give you (only shown when someone who can cast it is present). Off by default."] = "Altri non hanno il mio potenziamento: avvisa quando un membro del gruppo non ha un potenziamento che puoi lanciare.\nMi mancano i potenziamenti degli altri: avvisa quando ti manca un potenziamento che un membro del gruppo potrebbe darti (mostrato solo quando è presente qualcuno che può lanciarlo). Disattivato per impostazione predefinita."
