L["Out-of-range coloring now tracks the spell actually on the icon while a proc or talent override replaces it, instead of the base spell's range."] = "La colorazione fuori portata ora segue l'incantesimo effettivamente sull'icona quando un proc o una sostituzione da talento lo rimpiazza, invece della portata dell'incantesimo base."
L["Out-of-range frames darken instead of fading transparent, matching Blizzard's default party/raid frame look. Uses the same Out of Range Alpha % as brightness: 100% = no visible difference in/out of range, 10% = out-of-range frames drop to 10% brightness."] = "I riquadri fuori portata si scuriscono invece di dissolversi in trasparenza, in linea con l'aspetto predefinito dei riquadri gruppo/incursione di Blizzard. Usa la stessa percentuale Alpha fuori portata come luminosità: 100% = nessuna differenza visibile dentro/fuori portata, 10% = i riquadri fuori portata scendono al 10% di luminosità."
