L["Outline style override for all Action Bars text. EUI Global Outline follows the global Outline Mode setting above."] = "Sostituzione stile contorno per tutto il testo di Barre delle azioni. Contorno globale EUI segue l'impostazione Modalità contorno globale sopra."
L["Outline style override for all AuraBuff Reminders text. EUI Global Outline follows the global Outline Mode setting above."] = "Sostituzione stile contorno per tutto il testo di Promemoria aure. Contorno globale EUI segue l'impostazione Modalità contorno globale sopra."
L["Outline style override for all Bags text. EUI Global Outline follows the global Outline Mode setting above."] = "Sostituzione stile contorno per tutto il testo di Borse. Contorno globale EUI segue l'impostazione Modalità contorno globale sopra."
L["Outline style override for all Blizz UI Enhanced text. EUI Global Outline follows the global Outline Mode setting above."] = "Sostituzione stile contorno per tutto il testo di Interfaccia Blizz migliorata. Contorno globale EUI segue l'impostazione Modalità contorno globale sopra."
L["Outline style override for all Chat text. EUI Global Outline follows the global Outline Mode setting above."] = "Sostituzione stile contorno per tutto il testo di Chat. Contorno globale EUI segue l'impostazione Modalità contorno globale sopra."
L["Outline style override for all Cooldown Manager text. EUI Global Outline follows the global Outline Mode setting above."] = "Sostituzione stile contorno per tutto il testo di Gestore recuperi. Contorno globale EUI segue l'impostazione Modalità contorno globale sopra."
L["Outline style override for all Damage Meters text. EUI Global Outline follows the global Outline Mode setting above."] = "Sostituzione stile contorno per tutto il testo di Misuratore danni. Contorno globale EUI segue l'impostazione Modalità contorno globale sopra."
L["Outline style override for all DataBars text. EUI Global Outline follows the global Outline Mode setting above."] = "Sostituzione stile contorno per tutto il testo di DataBar. Contorno globale EUI segue l'impostazione Modalità contorno globale sopra."
L["Outline style override for all Friends List text. EUI Global Outline follows the global Outline Mode setting above."] = "Sostituzione stile contorno per tutto il testo di Lista amici. Contorno globale EUI segue l'impostazione Modalità contorno globale sopra."
