L["Outline style override for all Mythic+ Tools text. EUI Global Outline follows the global Outline Mode setting above."] = "Sostituzione stile contorno per tutto il testo di Strumenti Mitica+. Contorno globale EUI segue l'impostazione Modalità contorno globale sopra."
L["Outline style override for all Nameplates text. EUI Global Outline follows the global Outline Mode setting above."] = "Sostituzione stile contorno per tutto il testo di Targhette. Contorno globale EUI segue l'impostazione Modalità contorno globale sopra."
L["Outline style override for all Quality of Life text. EUI Global Outline follows the global Outline Mode setting above."] = "Sostituzione stile contorno per tutto il testo di Qualità della vita. Contorno globale EUI segue l'impostazione Modalità contorno globale sopra."
L["Outline style override for all Quest Tracker text. EUI Global Outline follows the global Outline Mode setting above."] = "Sostituzione stile contorno per tutto il testo di Tracciamento missioni. Contorno globale EUI segue l'impostazione Modalità contorno globale sopra."
L["Outline style override for all Quickdraw text. EUI Global Outline follows the global Outline Mode setting above."] = "Sostituzione stile contorno per tutto il testo di Quickdraw. Contorno globale EUI segue l'impostazione Modalità contorno globale sopra."
