L["Override any setting for a group of specs, or for the content you're in. Everything else keeps your normal profile settings."] = "Sostituisci qualsiasi impostazione per un gruppo di specializzazioni, o per il contenuto in cui ti trovi. Tutto il resto mantiene le tue normali impostazioni di profilo."
