L["Overrides Hide Keybind Text while this bar is paged onto the vehicle bar (Action Bar 1 while the player is in a vehicle), so the keybinds stay visible instead of hidden."] = "Sostituisce Nascondi testo associazione tasti mentre questa barra viene visualizzata sulla barra veicolo (Barra azione 1 mentre il giocatore è in un veicolo), così le associazioni tasti restano visibili invece di essere nascoste."
L["Overrides are locked: this page's custom Buff Manager is active. Leave the Buff Manager tab to manage overrides."] = "Le sostituzioni sono bloccate: il Buff Manager personalizzato di questa pagina è attivo. Esci dalla scheda Buff Manager per gestire le sostituzioni."
L["Overrides the Frame Strata set in the main frames for this frame only. Controls the order that overlapping frames display in; set higher to show above other frames."] = "Sostituisce lo Strato riquadro impostato nei riquadri principali solo per questo riquadro. Controlla l'ordine in cui i riquadri sovrapposti vengono visualizzati; imposta un valore più alto per mostrarlo sopra gli altri riquadri."
L["Overrides the border size from the main frames for this frame only. Border color and texture still follow the main frames."] = "Sostituisce la dimensione del bordo dai riquadri principali solo per questo riquadro. Colore e texture del bordo seguono comunque i riquadri principali."
L["Overrides"] = "Sostituzioni"
