L["Raid frame absorbs and health ticks, nameplate health updates, tracking bar pairing and unit frame absorbs all do less work per event"] = "Gli assorbimenti dei riquadri incursione, gli aggiornamenti graduali della salute, gli aggiornamenti della salute delle targhette nome, l'abbinamento delle barre di tracciamento e gli assorbimenti dei riquadri unità svolgono tutti meno lavoro per evento"
L["Raid frame buffs and debuffs are rebuilt for Midnight's new aura engine. Track whole spell categories with filters, then give each one its own display."] = "I potenziamenti e indebolimenti dei riquadri incursione sono stati ricostruiti per il nuovo motore delle aure di Midnight. Traccia intere categorie di incantesimi con filtri, poi assegna a ciascuna il proprio display."
L["Raid only. Left-click the Durability column's header icon anytime to use the Auto-Hammer (item 132514) -- no one needs to be low first. When a player's Durability reading drops to 25% or below, their name blinks as a heads-up, but that's just a warning, not a requirement to click."] = "Solo incursione. Clic sinistro sull'icona dell'intestazione della colonna Durabilità in qualsiasi momento per usare l'Auto-Martello (oggetto 132514) -- nessuno deve avere la durabilità bassa per primo. Quando la Durabilità di un giocatore scende al 25% o meno, il suo nome lampeggia come avviso, ma è solo un avviso, non un obbligo di cliccare."
L["Raid only. Left-click the Food column's header icon anytime to drop a feast at your own feet: Feast of Knowledge, falling back to Amani Cornucopia and then Loa's Gathering depending on what's in your bags. Disarmed while you already have a Well Fed buff active, so there's no wasted click."] = "Solo incursione. Clic sinistro sull'icona dell'intestazione della colonna Cibo in qualsiasi momento per posare un banchetto ai tuoi piedi: Feast of Knowledge, ricadendo su Amani Cornucopia e poi Loa's Gathering in base a cosa hai nelle borse. Disattivato mentre hai già attivo un potenziamento Well Fed, così non c'è alcun clic sprecato."
