L["Recolor the bar while you have a buff. The first active buff in the list wins, so order = priority. Overrides threshold coloring while active.\nYou must be tracking the buff in Blizzard CDM, added to EUI CDM, and this only works with CDM trackable buffs."] = "Ricolora la barra mentre hai un potenziamento attivo. Il primo potenziamento attivo nell'elenco prevale, quindi l'ordine = priorità. Sovrascrive la colorazione a soglia mentre è attivo.\nDevi tracciare il potenziamento nel CDM di Blizzard, aggiunto al CDM di EUI, e funziona solo con i potenziamenti tracciabili dal CDM."
