L["Reminder threshold while you are in a dungeon before a Mythic+ key starts (Mythic 0 / keystone lobby). Set it high enough that you top up buffs and food before pulling, so you begin the key with enough duration to last it.\n0 = only when fully expired.\nIgnored once the key is active or you are in combat (then only when the buff is fully gone)."] = "Soglia promemoria mentre sei in un dungeon prima che inizi una chiave Mitica+ (Mitica 0 / lobby chiave). Impostala sufficientemente alta da rinnovare potenziamenti e cibo prima di iniziare, così inizi la chiave con abbastanza durata per portarla a termine.\n0 = solo quando è completamente scaduto.\nIgnorato una volta che la chiave è attiva o sei in combattimento (allora solo quando il potenziamento è del tutto esaurito)."
L["Reminders are always hidden in rested areas (cities and inns)."] = "I promemoria sono sempre nascosti nelle aree di riposo (città e locande)."
