L["Repaired all items for %s"] = "Ha riparato tutti gli oggetti per %s"
L["Replace Quest Icon with Objective"] = "Sostituisci icona missione con l'obiettivo"
L["Replace with Buff"] = "Sostituisci con potenziamento"
L["Replaces Blizzard's default buff and debuff display with fully customizable bars."] = "Sostituisce la visualizzazione predefinita di Blizzard per potenziamenti e indebolimenti con barre completamente personalizzabili."
L["Replaces Buff Glow: the icon glows when its stack count matches the comparison below, using this spell's Buff Glow style (Modern WoW Glow if none is set)."] = "Sostituisce il Bagliore potenziamento: l'icona si illumina quando il suo conteggio pile corrisponde al confronto sotto, usando lo stile Bagliore potenziamento di questo incantesimo (Bagliore WoW moderno se non impostato)."
L["Replaces the class resource bar with an Ignore Pain tracker: the fill shows your current absorb amount scaled against your maximum health, and the bar text shows the absorb value."] = "Sostituisce la barra risorsa di classe con un localizzatore di Ignora il Dolore: il riempimento mostra la tua quantità di assorbimento attuale in proporzione alla tua salute massima, e il testo della barra mostra il valore di assorbimento."
L["Replaces the class resource bar with an Ironfur tracker. Each Ironfur cast adds a hash line that slides from right to left as its buff decays. Duration is talent-aware (Ursoc's Endurance and Guardian of Elune)."] = "Sostituisce la barra risorsa di classe con un localizzatore di Pelle di Ferro. Ogni lancio di Pelle di Ferro aggiunge una tacca che scorre da destra a sinistra mentre il potenziamento decade. La durata tiene conto dei talenti (Resistenza di Ursoc e Guardiano di Elune)."
L["Replaces the spendable amount with the crests you have earned this season, out of the season cap. The tooltip lists both numbers side by side."] = "Sostituisce l'importo spendibile con le creste guadagnate in questa stagione, sul totale del limite stagionale. La descrizione elenca entrambi i numeri fianco a fianco." -- TODO: confirmar termo oficial (Crest)
