L["Restyle Blizzard's chat bubbles for the channels you pick beside this.\n\nEllesmereUI keeps Blizzard's bubbles switched on and draws over them, so every bubble stays where the game put it, including the one over your own head. Nameplates are not involved and do not need to be visible.\n\nChannels you leave off keep Blizzard's own look."] = "Applica un nuovo stile ai fumetti di Blizzard per i canali che scegli accanto a questo.\n\nEllesmereUI mantiene attivi i fumetti di Blizzard e disegna sopra di essi, così ogni fumetto rimane dove il gioco lo ha posizionato, incluso quello sopra la tua testa. Le targhette nome non sono coinvolte e non devono essere visibili.\n\nI canali che lasci disattivati mantengono l'aspetto originale di Blizzard."
L["Restyles Blizzard's on-screen progress bars (event objectives, nameplate counters) to the EUI look. Requires reload to apply.\n\nThese bars are drawn over rather than modified, so if the game ever reports their contents as protected the original bar is shown instead.\n\nUse the cog to set a minimum size, so bars on shrunken nameplates stay readable."] = "Applica un nuovo stile alle barre di progresso a schermo di Blizzard (obiettivi evento, contatori targhetta nome) con l'aspetto EUI. Richiede un ricaricamento per applicarsi.\n\nQueste barre vengono disegnate sopra invece di essere modificate, quindi se il gioco segnala il loro contenuto come protetto viene mostrata invece la barra originale.\n\nUsa l'ingranaggio per impostare una dimensione minima, così le barre sulle targhette nome rimpicciolite rimangono leggibili."
