L["Seconds counts the time down in tenths. GCD Count counts whole global cooldowns instead, so inside Arcane Soul it reads as the number of Arcane Barrages that still fit, ending on a coloured LAST. Seconds + GCD in Soul mixes the two: tenths counting down to the window, Barrage count once it opens."] = "Secondi conta il tempo alla rovescia in decimi. Conteggio CGC conta invece interi tempi di recupero globali, così dentro Anima Arcana viene letto come il numero di Raffiche Arcane che ci stanno ancora, terminando su un colorato ULTIMO. Secondi + CGC in Anima mescola i due: decimi in conto alla rovescia verso la finestra, conteggio Raffiche una volta aperta."
