L["Seconds of Arcane Surge left when the countdown appears. Always in seconds, including in GCD mode."] = "Secondi di Aumento Arcano rimanenti quando appare il conto alla rovescia. Sempre in secondi, anche in modalità CGC." -- TODO: confirmar termo oficial (Arcane Surge)
