L["Sets the accent color used across all EllesmereUI elements (tabs, glows, highlights, borders). Defaults to your theme color."] = "Imposta il colore accento usato in tutti gli elementi di EllesmereUI (schede, bagliori, evidenziazioni, bordi). Il predefinito è il colore del tuo tema."
L["Sets the font for the names that float above players, NPCs and enemies in the world.\n\nSeparate from Global Font - changing this does not affect the rest of the UI, and Global Font does not affect it.\n\nBlizzard Default leaves the name text completely untouched.\n\n|cffff4d4dRequires a re-log or restart of WoW to take effect.|r"] = "Imposta il carattere per i nomi che fluttuano sopra giocatori, PNG e nemici nel mondo.\n\nSeparato dal Carattere globale - modificarlo non influisce sul resto dell'interfaccia, e il Carattere globale non lo influenza.\n\nPredefinito Blizzard lascia il testo del nome completamente intatto.\n\n|cffff4d4dRichiede un rilogin o un riavvio di WoW per avere effetto.|r"
L["Sets the scale of the entire game UI. Lower values make everything smaller, higher values make everything larger."] = "Imposta la scala dell'intera interfaccia di gioco. Valori più bassi rendono tutto più piccolo, valori più alti rendono tutto più grande."
