L["Show a 1-decimal countdown (2.7) below Threshold Seconds."] = "Mostra un conto alla rovescia a 1 decimale (2.7) sotto Secondi soglia."
L["Show a 1-decimal countdown on presets and custom spell/item IDs when under the cog's Seconds Left threshold -- their active state on cooldown/utility bars, their buff duration on buff bars (both are hardcoded, so the remaining time is exact)."] = "Mostra un conto alla rovescia a 1 decimale su preset e ID incantesimo/oggetto personalizzati quando sotto la soglia Secondi rimanenti dell'ingranaggio -- il loro stato attivo sulle barre di recupero/utilità, la loro durata potenziamento sulle barre potenziamento (entrambi sono hardcoded, quindi il tempo rimanente è esatto)."
L["Show a glow on icons when the remaining duration is in the pandemic window (last 30%)"] = "Mostra un bagliore sulle icone quando la durata rimanente è nella finestra pandemica (ultimo 30%)"
L["Show a glow on the bar when the remaining duration is in the pandemic window (last 30%)"] = "Mostra un bagliore sulla barra quando la durata rimanente è nella finestra pandemica (ultimo 30%)"
L["Show a glow on the cast bar when the enemy is casting a spell Blizzard marks as important."] = "Mostra un bagliore sulla barra di lancio quando il nemico sta lanciando un incantesimo che Blizzard contrassegna come importante."
L["Show a panel of equipped-gear sockets on the character sheet; click a socket to gem it."] = "Mostra un pannello degli incastri dell'equipaggiamento indossato sulla scheda personaggio; clicca un incastro per incastonarvi una gemma."
L["Show a pulsing dot on the Patch Notes button whenever EllesmereUI updates to a new version."] = "Mostra un punto pulsante sul pulsante Note di patch ogni volta che EllesmereUI si aggiorna a una nuova versione."
L["Show a reminder when you don't have an active pet summoned. Only applies to pet classes (Hunter, Warlock, Death Knight, Mage)."] = "Mostra un promemoria quando non hai un pet attivo evocato. Si applica solo alle classi con pet (Cacciatore, Stregone, Cavaliere della Morte, Mago)."
L["Show a reminder when your Demonology Warlock has the wrong pet summoned (not Felguard)."] = "Mostra un promemoria quando il tuo Stregone Demonologia ha evocato il pet sbagliato (non Guardia Vil)."
L["Show a reminder when your active pet is set to Passive stance. Only applies to pet classes (Hunter, Warlock, Death Knight, Mage)."] = "Mostra un promemoria quando il tuo pet attivo è impostato in postura Passiva. Si applica solo alle classi con pet (Cacciatore, Stregone, Cavaliere della Morte, Mago)."
L["Show a shield icon on the cast bar when an enemy's cast cannot be interrupted."] = "Mostra un'icona scudo sulla barra di lancio quando il lancio di un nemico non può essere interrotto."
L["Show a shield icon on the cast bar when the cast cannot be interrupted."] = "Mostra un'icona scudo sulla barra di lancio quando il lancio non può essere interrotto."
L["Show a small glowing spark that moves along the leading edge of the fill."] = "Mostra una piccola scintilla luminosa che si muove lungo il bordo anteriore del riempimento."
L["Show a tracked buff in this slot while it is active."] = "Mostra un potenziamento monitorato in questo slot mentre è attivo."
L["Show absorbs on Boss Frames, styled independently from the Boss tab's own Absorbs section."] = "Mostra gli assorbimenti sui Riquadri boss, con uno stile indipendente dalla sezione Assorbimenti propria della scheda Boss."
L["Show as"] = "Mostra come"
L["Show aura tooltips when hovering buff and debuff icons on all unit frames except boss frames."] = "Mostra le descrizioni delle aure al passaggio del mouse sulle icone di potenziamenti e indebolimenti su tutti i riquadri unità eccetto i riquadri boss."
L["Show aura tooltips when hovering buff and debuff icons on boss frames."] = "Mostra le descrizioni delle aure al passaggio del mouse sulle icone di potenziamenti e indebolimenti sui riquadri boss."
L["Show aura tooltips when hovering this bar's icons."] = "Mostra le descrizioni delle aure al passaggio del mouse sulle icone di questa barra."
L["Show black backgrounds behind minimap indicator buttons (tracking, calendar, mail, crafting, addon buttons, flyout toggle)."] = "Mostra sfondi neri dietro i pulsanti indicatore della minimappa (tracciamento, calendario, posta, professioni, pulsanti addon, attivazione menu a comparsa)."
L["Show button backgrounds even if a spell is not assigned to that slot."] = "Mostra gli sfondi dei pulsanti anche se non è assegnato un incantesimo a quello slot."
L["Show combat indicator preview"] = "Mostra anteprima indicatore combattimento"
L["Show copies of the same item that sit in separate bag slots as one icon with their counts added together. Turn this off to keep every slot separate, for example when you deliberately split stacks. Merging is always paused while the mail, trade, auction house, bank or guild bank window is open, since those take one bag slot at a time."] = "Mostra le copie dello stesso oggetto che si trovano in slot borsa separati come un'unica icona con i loro conteggi sommati insieme. Disattiva per mantenere ogni slot separato, per esempio quando dividi deliberatamente le pile. L'unione è sempre in pausa mentre la finestra di posta, scambio, casa d'aste, banca o banca gilda è aperta, poiché queste occupano uno slot borsa alla volta."
L["Show debuffs on preview"] = "Mostra indebolimenti nell'anteprima"
