L["Show each enchant's name as text (colored to match that item's item level) instead of its icon. The name normally appears only when hovering the icon."] = "Mostra il nome di ogni incantamento come testo (colorato per abbinarsi al livello oggetto di quell'oggetto) invece della sua icona. Il nome normalmente appare solo al passaggio del mouse sull'icona."
L["Show equipped trinkets even if they don't have an on-use effect."] = "Mostra i ciondoli indossati anche se non hanno un effetto d'uso."
L["Show every buff that has a duration (hides permanent buffs). Use the Hide lane below to remove specific filters."] = "Mostra ogni potenziamento che ha una durata (nasconde i potenziamenti permanenti). Usa la corsia Nascondi sotto per rimuovere filtri specifici."
L["Show every buff that has a duration (hides permanent buffs). While this is on, checked filters below are hidden instead of added."] = "Mostra ogni potenziamento che ha una durata (nasconde i potenziamenti permanenti). Mentre questo è attivo, i filtri selezionati sotto vengono nascosti invece che aggiunti."
L["Show every buff. Use the Hide lane below to remove specific filters."] = "Mostra ogni potenziamento. Usa la corsia Nascondi sotto per rimuovere filtri specifici."
L["Show every buff. While this is on, checked filters below are hidden from the bar instead of added."] = "Mostra ogni potenziamento. Mentre questo è attivo, i filtri selezionati sotto vengono nascosti dalla barra invece che aggiunti."
L["Show every buff. While this is on, checked filters below are hidden from the frame instead of added."] = "Mostra ogni potenziamento. Mentre questo è attivo, i filtri selezionati sotto vengono nascosti dal riquadro invece che aggiunti."
L["Show every debuff in the base grid. The Base Filters dropdown is ignored while this is on."] = "Mostra ogni indebolimento nella griglia base. Il menu a tendina Filtri base viene ignorato mentre questo è attivo."
L["Show every debuff in this indicator. Use the Hide lane below to remove specific filters."] = "Mostra ogni indebolimento in questo indicatore. Usa la corsia Nascondi sotto per rimuovere filtri specifici."
L["Show every debuff. Use the Hide lane below to remove specific filters."] = "Mostra ogni indebolimento. Usa la corsia Nascondi sotto per rimuovere filtri specifici."
L["Show every debuff. While this is on, checked filters below are hidden from the bar instead of added."] = "Mostra ogni indebolimento. Mentre questo è attivo, i filtri selezionati sotto vengono nascosti dalla barra invece che aggiunti."
L["Show every debuff. While this is on, checked filters below are hidden from the frame instead of added."] = "Mostra ogni indebolimento. Mentre questo è attivo, i filtri selezionati sotto vengono nascosti dal riquadro invece che aggiunti."
L["Show every debuff. While this is on, checked filters below are hidden from the grid instead of added."] = "Mostra ogni indebolimento. Mentre questo è attivo, i filtri selezionati sotto vengono nascosti dalla griglia invece che aggiunti."
L["Show gear tiles for items already at their maximum item level."] = "Mostra le caselle equipaggiamento per gli oggetti già al loro livello oggetto massimo."
