L["Show one decimal place on health text: health values like 240.5k and health percent like 77.3%. Power text is unaffected. Off by default."] = "Mostra una cifra decimale sul testo della salute: valori di salute come 240.5k e percentuale di salute come 77.3%. Il testo dell'energia non è interessato. Disattivato per impostazione predefinita."
L["Show one plain cast bar per enemy nameplate that is casting, gathered into a single movable group with the spell name, its target, and the cast timer."] = "Mostra una semplice barra di lancio per ogni targhetta nome nemico che sta lanciando, raccolte in un unico gruppo spostabile con il nome dell'incantesimo, il suo bersaglio e il timer di lancio."
L["Show one sub-category per equipment set (named after the set) nested under Item Set Gear. Gear in several sets goes to the first one."] = "Mostra una sottocategoria per ogni set di equipaggiamento (denominata come il set) annidata sotto Equipaggiamento set oggetto. L'equipaggiamento in più set va nella prima."
L["Show one-time video guide badges next to new or complex features. Each badge disappears forever once clicked."] = "Mostra distintivi guida video una tantum accanto a funzionalità nuove o complesse. Ogni distintivo scompare per sempre una volta cliccato."
L["Show only while in a dungeon, raid, arena or battleground. Combine with Combat to show only during instanced combat."] = "Mostra solo mentre sei in un dungeon, un'incursione, un'arena o un campo di battaglia. Combina con Combattimento per mostrare solo durante il combattimento istanziato."
L["Show only while in combat. Combine with Instances to show only during instanced combat."] = "Mostra solo mentre sei in combattimento. Combina con Istanze per mostrare solo durante il combattimento istanziato."
L["Show page up/down arrows next to Action Bar 1 for cycling through action bar pages 1-6."] = "Mostra le freccette pagina su/giù accanto alla Barra delle azioni 1 per scorrere le pagine 1-6 della barra delle azioni."
L["Show player nicknames from supported addons instead of character names on your main frames."] = "Mostra i nomignoli giocatore dagli addon supportati invece dei nomi personaggio sui tuoi riquadri principali."
L["Show private auras on preview"] = "Mostra aure private nell'anteprima"
L["Show quest objective progress on nameplates for open-world mobs."] = "Mostra il progresso dell'obiettivo missione sulle targhette nome per i mob del mondo aperto."
L["Show reminders when remaining buff time is below this many minutes.\n0 = only when fully expired.\nIgnored in combat and during Mythic+ keys (then only when the buff is gone)."] = "Mostra promemoria quando il tempo di potenziamento rimanente è sotto questo numero di minuti.\n0 = solo quando è completamente scaduto.\nIgnorato in combattimento e durante le chiavi Mitica+ (allora solo quando il potenziamento è esaurito)."
L["Show rune count in center and remove recharge text/animation"] = "Mostra conteggio rune al centro e rimuove testo/animazione di ricarica"
L["Show rune count in center and remove recharging text/animation"] = "Mostra conteggio rune al centro e rimuove testo/animazione di ricarica"
L["Show shield effects on preview"] = "Mostra effetti scudo nell'anteprima"
L["Show special reminders while out in the open world."] = "Mostra promemoria speciali quando sei fuori nel mondo aperto."
L["Show special reminders while out in the open world.\nReminders are always hidden in rested areas (cities and inns)."] = "Mostra promemoria speciali quando sei fuori nel mondo aperto.\nI promemoria sono sempre nascosti nelle aree di riposo (città e locande)."
L["Show successful interrupt lockouts in the crowd-control icon slot.\n\nDue to addon restrictions, the duration shown is a generic 4 seconds for all classes, so it is not 100% accurate."] = "Mostra i blocchi da interruzione riusciti nello slot icona controllo folla.\n\nA causa delle restrizioni dell'addon, la durata mostrata è un generico 4 secondi per tutte le classi, quindi non è accurata al 100%."
L["Show targeted spells on preview"] = "Mostra incantesimi bersagliati nell'anteprima"
L["Show the FocusKick bar on your current target's nameplate instead of your focus target's nameplate."] = "Mostra la barra FocusKick sulla targhetta nome del tuo bersaglio attuale invece di quella del tuo bersaglio focus."
L["Show the Mythic+ teleport section in the tooltip. Ready rows are click-to-teleport."] = "Mostra la sezione teletrasporto Mitica+ nella descrizione. Le righe pronte sono clic-per-teletrasportarsi."
L["Show the Pinned Items category in the sidebar and content grid."] = "Mostra la categoria Oggetti fissati nella barra laterale e nella griglia contenuti."
L["Show the Recent Items category in the sidebar and content grid for newly acquired items."] = "Mostra la categoria Oggetti recenti nella barra laterale e nella griglia contenuti per gli oggetti acquisiti di recente."
L["Show the Sated/Exhaustion lockout countdown on the icon."] = "Mostra il conto alla rovescia del blocco Saziato/Esaurimento sull'icona."
L["Show the bar full of its fill color while no global cooldown is running, instead of the background color."] = "Mostra la barra piena del suo colore di riempimento mentre nessun tempo di recupero globale è in corso, invece del colore di sfondo."
L["Show the border style and size controls for the timer bars."] = "Mostra i controlli di stile e dimensione bordo per le barre timer."
L["Show the bright spark at the leading edge of the cast bar fill."] = "Mostra la scintilla luminosa al bordo anteriore del riempimento della barra di lancio."
L["Show the charge and stack counters on this bar's icons."] = "Mostra i contatori di carica e pila sulle icone di questa barra."
L["Show the crafted quality rank on tracked items, matching the rank icon on the action bars. Items with no crafted quality are unaffected. Only shown while the item is owned."] = "Mostra il rango di qualità artigianale sugli oggetti monitorati, corrispondente all'icona rango sulle barre delle azioni. Gli oggetti senza qualità artigianale non sono interessati. Mostrato solo mentre l'oggetto è posseduto."
L["Show the enemy's raid target marker to the left of the spell name."] = "Mostra l'indicatore bersaglio incursione del nemico a sinistra del nome dell'incantesimo."
L["Show the expansion landing page (Omnium Folio) button at the bottom-left of the minimap. Use the cog to nudge its position."] = "Mostra il pulsante della pagina di destinazione dell'espansione (Omnium Folio) in basso a sinistra della minimappa. Usa l'ingranaggio per affinare la sua posizione."
L["Show the expansion landing page (Omnium Folio) button on the minimap. Use the cog to choose its corner and nudge its position."] = "Mostra il pulsante della pagina di destinazione dell'espansione (Omnium Folio) sulla minimappa. Usa l'ingranaggio per scegliere il suo angolo e affinare la sua posizione."
L["Show the game's spell tooltip when you hover a spell in a breakdown window."] = "Mostra la descrizione incantesimo del gioco quando passi il mouse su un incantesimo in una finestra di dettaglio."
L["Show the leader/assistant icon while you are in combat. Disable to hide it during combat."] = "Mostra l'icona capogruppo/assistente mentre sei in combattimento. Disattiva per nasconderla durante il combattimento."
L["Show the main frames' hover highlight border on this frame. Turn off so this frame never recolors on mouseover. No effect when Highlight is off in the main frames' Hover Borders."] = "Mostra il bordo di evidenziazione al passaggio del mouse dei riquadri principali su questo riquadro. Disattiva così questo riquadro non si ricolora mai al passaggio del mouse. Nessun effetto quando Evidenziazione è disattivata nei Bordi al passaggio del mouse dei riquadri principali."
L["Show the name of who the boss is casting on."] = "Mostra il nome di chi il boss sta bersagliando col lancio."
L["Show the part of an absorb that exceeds your empty health and backfills over your current health. When off, absorbs only fill the empty part of the health bar."] = "Mostra la parte di un assorbimento che eccede la tua salute vuota e riempie all'indietro sopra la tua salute attuale. Quando disattivato, gli assorbimenti riempiono solo la parte vuota della barra salute."
L["Show the part of an absorb that exceeds your empty health and backfills over your current health. When off, absorbs only fill the empty part of the health bar; on Default Blizz Frames the glow line stays pinned at the right edge."] = "Mostra la parte di un assorbimento che eccede la tua salute vuota e riempie all'indietro sopra la tua salute attuale. Quando disattivato, gli assorbimenti riempiono solo la parte vuota della barra salute; sui Riquadri Blizz predefiniti la linea di bagliore resta fissata al bordo destro."
L["Show the pet frame whenever you have a pet, ignoring the Player frame's visibility settings."] = "Mostra il riquadro pet ogni volta che hai un pet, ignorando le impostazioni di visibilità del riquadro Giocatore."
L["Show the player's title inline with their name, and/or their guild on a line below it, on friendly nameplates."] = "Mostra il titolo del giocatore in linea con il suo nome, e/o la sua gilda su una riga sotto di esso, sulle targhette nome amiche."
L["Show the player's title or guild in a smaller line below their name on friendly nameplates."] = "Mostra il titolo o la gilda del giocatore in una riga più piccola sotto il suo nome sulle targhette nome amiche."
L["Show the recharge countdown on charge spells while a charge is still banked. When off, the recharge timer only appears at 0 charges (Blizzard default)."] = "Mostra il conto alla rovescia di ricarica sugli incantesimi a cariche mentre una carica è ancora disponibile. Quando disattivato, il timer di ricarica appare solo a 0 cariche (predefinito Blizzard)."
L["Show the resource text only while the power bar is hidden - disabled, filtered off for this spec, a spec with no power, or hidden by \"Hide Power Bar if Resource\". Off = always show the text."] = "Mostra il testo risorsa solo mentre la barra energia è nascosta - disattivata, filtrata per questa spec, una spec senza energia, o nascosta da \"Nascondi barra energia se risorsa\". Disattivato = mostra sempre il testo."
L["Show the rotating cooldown edge on every cooldown in this bar, not just while a charge is recharging. Hide Recharge Edge still overrides this for individual charge spells."] = "Mostra il bordo rotante del tempo di recupero su ogni tempo di recupero in questa barra, non solo mentre una carica si sta ricaricando. Nascondi bordo ricarica sovrascrive comunque questo per i singoli incantesimi a cariche."
L["Show the seasonal Earned / Cap column in the crest table."] = "Mostra la colonna stagionale Guadagnato / Limite nella tabella creste." -- TODO: confirmar termo oficial (Crest)
L["Show the selected action's name next to the selected icon."] = "Mostra il nome dell'azione selezionata accanto all'icona selezionata."
L["Show the tracker as the Rebirth icon or as a compact text line with charges and time until the next one."] = "Mostra il localizzatore come l'icona di Rinascita o come una riga di testo compatta con cariche e tempo fino alla prossima." -- NAO-OFICIAL (Rebirth)
L["Show the unit's tooltip when hovering the frame itself."] = "Mostra la descrizione dell'unità al passaggio del mouse sul riquadro stesso."
L["Show this indicator's buffs in the exact order you arrange (the first 10 arranged buffs are guaranteed; any beyond follow the default sorting)."] = "Mostra i potenziamenti di questo indicatore nell'ordine esatto che disponi (i primi 10 potenziamenti disposti sono garantiti; eventuali oltre seguono l'ordinamento predefinito)."
L["Show this indicator's buffs on every spec of your class, not only this spec."] = "Mostra i potenziamenti di questo indicatore su ogni spec della tua classe, non solo questa spec."
L["Show top 15 entries instead of 8."] = "Mostra le prime 15 voci invece di 8."
L["Show total equipped durability above the character model, colored from green to red."] = "Mostra la durabilità totale equipaggiata sopra il modello del personaggio, colorata dal verde al rosso."
L["Show weapon oil and imbue icons at the front of this bar. They are weapon enchants rather than auras, so they show independently of the options above -- and the aura grid is shifted inward to make room for them, with every row shifting over by the same amount."] = "Mostra le icone di olio e incantamento arma davanti a questa barra. Sono incantamenti arma piuttosto che aure, quindi vengono mostrate indipendentemente dalle opzioni sopra -- e la griglia delle aure viene spostata verso l'interno per fare spazio, con ogni riga che si sposta della stessa quantità."
L["Show while this condition is false"] = "Mostra mentre questa condizione è falsa"
L["Show who each spell is being cast on, exactly like the nameplate cast bars."] = "Mostra su chi ogni incantesimo viene lanciato, esattamente come le barre di lancio delle targhette nome."
L["Show who the spell is being cast on, exactly like the nameplate cast bars."] = "Mostra su chi l'incantesimo viene lanciato, esattamente come le barre di lancio delle targhette nome."
L["Show world latency instead of home latency."] = "Mostra la latenza mondiale invece della latenza domestica."
L["Show your own class buffs on every spec, not only on the tracked healer spec."] = "Mostra i tuoi potenziamenti di classe su ogni spec, non solo sulla spec guaritore monitorata."
L["Show/Hide Hitbox Overlay"] = "Mostra/Nascondi sovrapposizione hitbox"
L["Show/Hide Windows Keybind"] = "Mostra/Nascondi associazione tasti finestre"
L["Show/Hide on Preview"] = "Mostra/Nascondi nell'anteprima"
L["Showing the '%s' override's value. Edit it from that override's editing mode."] = "Mostrando il valore della sovrascrittura '%s'. Modificalo dalla modalità di modifica di quella sovrascrittura."
L["Showing this aura from any caster; click for your casts only."] = "Mostrando questa aura da qualsiasi lanciatore; clicca per i tuoi lanci soltanto."
L["Showing this aura from your casts only; click for any caster."] = "Mostrando questa aura dai tuoi lanci soltanto; clicca per qualsiasi lanciatore."
L["Shown At Cursor"] = "Mostrato al cursore"
L["Shown on Modifier"] = "Mostrato al modificatore"
L["Shown"] = "Mostrato"
L["Shows Blizzard's default icon slot background texture behind empty action bar slots."] = "Mostra la trama di sfondo dello slot icona predefinita di Blizzard dietro gli slot vuoti della barra delle azioni."
L["Shows Sweeping Strikes charges on the resource bar; Unit Frames and the personal Nameplate show them regardless."] = "Mostra le cariche di Colpi Fendenti sulla barra risorsa; i Riquadri unità e la Targhetta nome personale le mostrano comunque." -- NAO-OFICIAL (Sweeping Strikes)
L["Shows a bar that fills over the global cooldown."] = "Mostra una barra che si riempie durante il tempo di recupero globale."
L["Shows a clickable list of online friends and guildmates in the Social and Guild button tooltips."] = "Mostra un elenco cliccabile di amici e compagni di gilda online nelle descrizioni dei pulsanti Sociale e Gilda."
L["Shows a colored overlay at the end of the cast bar representing your network latency for each spell. Helps you time spell queuing."] = "Mostra una sovrapposizione colorata alla fine della barra di lancio che rappresenta la tua latenza di rete per ogni incantesimo. Ti aiuta a temporizzare l'accodamento degli incantesimi."
L["Shows a countdown bar below the queue accept popup indicating how long you have to accept. Works with or without the reskin. Use the swatch and cog to set the countdown text color, text size, bar height and text offset."] = "Mostra una barra con conto alla rovescia sotto il popup di accettazione coda che indica quanto tempo hai per accettare. Funziona con o senza il reskin. Usa il campione e l'ingranaggio per impostare il colore del testo del conto alla rovescia, la dimensione del testo, l'altezza della barra e lo scostamento del testo."
L["Shows a countdown bar below the queue accept popup indicating how long you have to accept. Works with or without the reskin. Use the swatch and cog to set the countdown text color, text size. bar height and text offset."] = "Mostra una barra con conto alla rovescia sotto il popup di accettazione coda che indica quanto tempo hai per accettare. Funziona con o senza il reskin. Usa il campione e l'ingranaggio per impostare il colore del testo del conto alla rovescia, la dimensione del testo. altezza della barra e scostamento del testo."
L["Shows a countdown to the Arcane Soul window over the last seconds of Arcane Surge, then the time left inside it. Sunfury Arcane Mages only."] = "Mostra un conto alla rovescia alla finestra di Anima Arcana durante gli ultimi secondi di Aumento Arcano, poi il tempo rimanente al suo interno. Solo Maghi Arcano Furia Solare." -- NAO-OFICIAL (Arcane Soul, Arcane Surge, Sunfury)
L["Shows a faint white wash over each block on mouseover."] = "Mostra una tenue patina bianca sopra ogni blocco al passaggio del mouse."
L["Shows a house or globe icon marking which latency each value is."] = "Mostra un'icona casa o globo per contrassegnare a quale latenza corrisponde ogni valore."
L["Shows a large on-screen alert (e.g. \"Player DIED!\") whenever a party or raid member dies, so you immediately notice deaths during dungeons and raids. Use Unlock Mode to reposition the alert."] = "Mostra un grande avviso a schermo (es. \"Il giocatore è MORTO!\") ogni volta che un membro del gruppo o dell'incursione muore, così noti immediatamente le morti durante dungeon e incursioni. Usa la Modalità sblocco per riposizionare l'avviso."
L["Shows a large on-screen text when you enter and/or leave combat (e.g. \"+Combat\" / \"-Combat\"). Use the cog to set the display text, size, colors and which transitions are shown; use Unlock Mode to reposition the alert."] = "Mostra un grande testo a schermo quando entri e/o esci dal combattimento (es. \"+Combattimento\" / \"-Combattimento\"). Usa l'ingranaggio per impostare il testo visualizzato, la dimensione, i colori e quali transizioni vengono mostrate; usa la Modalità sblocco per riposizionare l'avviso."
L["Shows a mana percentage row for every healer in your group as its own movable text display. Position it in Unlock Mode."] = "Mostra una riga di percentuale mana per ogni guaritore nel tuo gruppo come propria visualizzazione di testo spostabile. Posizionala in Modalità sblocco."
L["Shows a map icon of the friend's region if they are not playing within your region"] = "Mostra un'icona mappa della regione dell'amico se non sta giocando nella tua regione"
L["Shows a movable strip of recent spell icons. Shift-drag to reposition."] = "Mostra una striscia spostabile di icone incantesimo recenti. Maiusc+trascina per riposizionare."
L["Shows a player's RP title on their unit tooltip."] = "Mostra il titolo RP di un giocatore nella descrizione della sua unità."
L["Shows a popup with party and guild keystones when typing /keys."] = "Mostra un popup con le chiavi di gruppo e gilda quando digiti /keys."
L["Shows a rest icon while your character is resting."] = "Mostra un'icona di riposo mentre il tuo personaggio è a riposo."
L["Shows a single Blood Plague debuff on enemy nameplates instead of one per copy (Blood Boil from weapon copies)."] = "Mostra un solo indebolimento Peste di Sangue sulle targhette nome dei nemici invece di uno per copia (Bollore di Sangue dalle copie dell'arma)." -- NAO-OFICIAL (Blood Plague, Blood Boil)
L["Shows a small white tick mark on the cast bar at the point where the cast will be when your interrupt comes off cooldown."] = "Mostra una piccola tacca bianca sulla barra di lancio nel punto in cui sarà il lancio quando la tua interruzione uscirà dal tempo di recupero."
L["Shows a small white tick mark where the cast will be when your interrupt comes off cooldown."] = "Mostra una piccola tacca bianca dove sarà il lancio quando la tua interruzione uscirà dal tempo di recupero."
L["Shows a special color for nameplates that another tank in your raid has aggro on."] = "Mostra un colore speciale per le targhette nome su cui un altro tank della tua incursione ha aggro."
L["Shows a special color for non caster/mini-boss enemies when you do not have aggro on them."] = "Mostra un colore speciale per i nemici non incantatori/mini-boss quando non hai aggro su di essi."
L["Shows a special color for non caster/mini-boss enemies when you have aggro on them."] = "Mostra un colore speciale per i nemici non incantatori/mini-boss quando hai aggro su di essi."
L["Shows a standalone window with spell cast history as bars. Matches your Damage Meters styling."] = "Mostra una finestra autonoma con la cronologia dei lanci di incantesimi come barre. Corrisponde allo stile dei tuoi Misuratori di danno."
L["Shows an envelope icon when you have unread mail."] = "Mostra un'icona busta quando hai posta non letta."
L["Shows any debuff with a dispel type (Magic, Curse, Disease, Poison, Bleed), even if you cannot remove it"] = "Mostra ogni indebolimento con un tipo di dissolvimento (Magia, Maledizione, Malattia, Veleno, Sanguinamento), anche se non puoi rimuoverlo"
L["Shows each crest's icon in front of its amount."] = "Mostra l'icona di ogni cresta davanti alla sua quantità." -- TODO: confirmar termo oficial (Crest)
L["Shows each healer's name before the number while in a raid. In a party the display always shows numbers only."] = "Mostra il nome di ogni guaritore prima del numero mentre sei in un'incursione. In un gruppo la visualizzazione mostra sempre solo i numeri."
L["Shows elapsed / total duration (e.g. 0.4 / 2.0) instead of counting down from the total."] = "Mostra durata trascorsa / totale (es. 0.4 / 2.0) invece di contare alla rovescia dal totale."
L["Shows every debuff except the ones you or your pet apply"] = "Mostra ogni indebolimento eccetto quelli applicati da te o dal tuo pet"
L["Shows every debuff on this frame."] = "Mostra ogni indebolimento su questo riquadro."
L["Shows external defensives cast on you (Pain Suppression, Ironbark, etc.) in its own movable frame; position it via Unlock Mode."] = "Mostra i difensivi esterni lanciati su di te (Soppressione del Dolore, Scorza di Ferro, ecc.) nel proprio riquadro spostabile; posizionalo tramite Modalità sblocco." -- NAO-OFICIAL (Pain Suppression, Ironbark)
L["Shows full spell and ability descriptions in tooltips instead of just the name. Only enforced on login after you toggle this setting."] = "Mostra le descrizioni complete di incantesimi e abilità nelle descrizioni invece del solo nome. Applicato solo al login dopo che attivi questa impostazione."
L["Shows item level and secondary stats in the Character button's tooltip."] = "Mostra livello oggetto e statistiche secondarie nella descrizione del pulsante Personaggio."
L["Shows large amounts using K/M suffixes (284,208g becomes 284.2Kg) instead of the full grouped number. The tooltip always shows the exact amount."] = "Mostra grandi quantità usando i suffissi K/M (284,208g diventa 284.2Kg) invece del numero completo raggruppato. La descrizione mostra sempre la quantità esatta."
L["Shows only auras flagged for raid frames during combat"] = "Mostra solo le aure contrassegnate per i riquadri incursione durante il combattimento"
L["Shows only auras with a dispel type you can dispel"] = "Mostra solo le aure con un tipo di dissolvimento che puoi dissolvere"
L["Shows only buffs that can be canceled"] = "Mostra solo i potenziamenti che possono essere annullati"
L["Shows only buffs you can spellsteal or purge"] = "Mostra solo i potenziamenti che puoi rubare o dissolvere"
L["Shows only crowd-control auras"] = "Mostra solo le aure di controllo folla"
L["Shows only debuffs Blizzard flags as important"] = "Mostra solo gli indebolimenti che Blizzard contrassegna come importanti"
L["Shows only debuffs Blizzard flags as important."] = "Mostra solo gli indebolimenti che Blizzard contrassegna come importanti."
L["Shows only debuffs applied by bosses"] = "Mostra solo gli indebolimenti applicati dai boss"
L["Shows only debuffs flagged for your role"] = "Mostra solo gli indebolimenti contrassegnati per il tuo ruolo"
L["Shows only debuffs from Blizzard's curated raid-frame debuff set"] = "Mostra solo gli indebolimenti dal set curato da Blizzard per i riquadri incursione"
L["Shows only debuffs not caused by any player or player pet (this is what shows most pve debuffs, do not check this while All Debuffs is selected!"] = "Mostra solo gli indebolimenti non causati da alcun giocatore o pet giocatore (questo è ciò che mostra la maggior parte degli indebolimenti pve, non selezionarlo mentre Tutti gli indebolimenti è selezionato!"
L["Shows only external defensive cooldowns cast on the unit"] = "Mostra solo i tempi di recupero difensivi esterni lanciati sull'unità"
L["Shows only major defensive cooldowns"] = "Mostra solo i principali tempi di recupero difensivi"
L["Shows only priority debuffs"] = "Mostra solo gli indebolimenti prioritari"
L["Shows only the Buffs that appear on Raid Frames"] = "Mostra solo i Potenziamenti che appaiono sui Riquadri incursione"
L["Shows only the Buffs you apply"] = "Mostra solo i Potenziamenti che applichi"
L["Shows only the Buffs/Debuffs that appear on Raid Frames"] = "Mostra solo i Potenziamenti/Indebolimenti che appaiono sui Riquadri incursione"
L["Shows only the Buffs/Debuffs you apply"] = "Mostra solo i Potenziamenti/Indebolimenti che applichi"
L["Shows only the Debuffs that appear on Raid Frames"] = "Mostra solo gli Indebolimenti che appaiono sui Riquadri incursione"
L["Shows only the Debuffs you apply"] = "Mostra solo gli Indebolimenti che applichi"
L["Shows only the buffs you apply"] = "Mostra solo i potenziamenti che applichi"
L["Shows only the debuffs you apply that Blizzard also flags as important."] = "Mostra solo gli indebolimenti che applichi che Blizzard contrassegna anche come importanti."
L["Shows only the debuffs you apply."] = "Mostra solo gli indebolimenti che applichi."
L["Shows only the spells Blizzard flags as Important"] = "Mostra solo gli incantesimi che Blizzard contrassegna come Importanti"
L["Shows only the stricter in-combat subset of the raid set"] = "Mostra solo il sottoinsieme più rigoroso in combattimento del set incursione"
L["Shows only this frame's Tracked Auras; add them with Edit Tracked Auras at the top of this menu."] = "Mostra solo le Aure monitorate di questo riquadro; aggiungile con Modifica aure monitorate in cima a questo menu."
L["Shows saved instance lockouts with boss kill progress on the minimap calendar button tooltip."] = "Mostra i blocchi istanza salvati con il progresso di uccisione boss nella descrizione del pulsante calendario della minimappa."
L["Shows silver and copper, not just gold."] = "Mostra argento e rame, non solo oro."
L["Shows start as a small icon, and the keybind switches between the icon and the full windows. Turn off to show full windows and make the keybind hide and show them."] = "Mostra l'avvio come una piccola icona, e l'associazione tasti passa tra l'icona e le finestre complete. Disattiva per mostrare le finestre complete e far nascondere e mostrare loro dall'associazione tasti."
L["Shows the 'Disable Feature' text below the teleport button. When off, the text is hidden and the window is 20px shorter."] = "Mostra il testo 'Disattiva funzionalità' sotto il pulsante di teletrasporto. Quando disattivato, il testo è nascosto e la finestra è 20px più corta."
L["Shows the Convert to Raid button, which reads Convert to Party while you are in a raid."] = "Mostra il pulsante Convertire in incursione, che diventa Convertire in gruppo mentre sei in un'incursione."
L["Shows the Disband button. It always asks before disbanding, but hiding it puts it out of misclick range for good."] = "Mostra il pulsante Sciogli. Chiede sempre conferma prima di sciogliere, ma nasconderlo lo mette fuori portata da clic accidentali per sempre."
L["Shows the Role Check button in window layouts and enables Right Click: Role Check on Compact Band."] = "Mostra il pulsante Controllo ruolo nei layout finestra e attiva Clic destro: Controllo ruolo sulla Fascia compatta."
L["Shows the Role Check button. Turn it off and the remaining buttons close the gap."] = "Mostra il pulsante Controllo ruolo. Disattivalo e i pulsanti rimanenti chiudono lo spazio."
L["Shows the active talent loadout name."] = "Mostra il nome della configurazione talenti attiva."
L["Shows the approximate distance to your current target as movable on-screen text (default 30-35). Use the cog for format, alignment, and text size; use Unlock Mode to position or Anchor to your Player Frame."] = "Mostra la distanza approssimativa dal tuo bersaglio attuale come testo spostabile a schermo (predefinito 30-35). Usa l'ingranaggio per formato, allineamento e dimensione testo; usa la Modalità sblocco per posizionarlo o Ancora al riquadro Giocatore."
L["Shows the approximate distance to your current target on its nameplate as a range bracket, e.g. 15+ when the target is 15-20 yards away."] = "Mostra la distanza approssimativa dal tuo bersaglio attuale sulla sua targhetta nome come intervallo di portata, es. 15+ quando il bersaglio è a 15-20 metri di distanza."
L["Shows the audio icon next to the volume bar."] = "Mostra l'icona audio accanto alla barra del volume."
L["Shows the checked classes' mobility spell(s) counting down on cooldown. Nothing checked = feature disabled. Use Unlock Mode to reposition/resize."] = "Mostra gli incantesimi di mobilità delle classi selezionate in conto alla rovescia sul tempo di recupero. Nulla selezionato = funzionalità disattivata. Usa la Modalità sblocco per riposizionare/ridimensionare."
L["Shows the coin icon next to the amount."] = "Mostra l'icona moneta accanto alla quantità."
L["Shows the combat status text only while your character is in combat."] = "Mostra il testo di stato combattimento solo mentre il tuo personaggio è in combattimento."
L["Shows the consumable rank (quality) diamond icon on action buttons."] = "Mostra l'icona diamante di rango (qualità) del consumabile sui pulsanti azione."
L["Shows the currency icon next to the amount."] = "Mostra l'icona valuta accanto alla quantità."
L["Shows the currency's description text in the tooltip. Turn off for a compact tooltip with just the name and the amount."] = "Mostra il testo di descrizione della valuta nella descrizione. Disattiva per una descrizione compatta con solo il nome e la quantità."
L["Shows the debuff's dispel type icon (Magic, Curse, Disease, Poison, Bleed) on the bar."] = "Mostra l'icona del tipo di dissolvimento dell'indebolimento (Magia, Maledizione, Malattia, Veleno, Sanguinamento) sulla barra."
L["Shows the debuffs you apply plus important debuffs from anyone."] = "Mostra gli indebolimenti che applichi più gli indebolimenti importanti da chiunque."
L["Shows the default Friends section for friends not in a custom group."] = "Mostra la sezione Amici predefinita per gli amici non in un gruppo personalizzato."
L["Shows the focus target's raid marker icon next to the cast bar itself, instead of (or in addition to) the frame-level marker in Extras."] = "Mostra l'icona indicatore incursione del bersaglio focus accanto alla barra di lancio stessa, invece di (o in aggiunta a) l'indicatore a livello riquadro in Extra."
L["Shows the icon next to the durability readout."] = "Mostra l'icona accanto alla lettura durabilità."
L["Shows the item level on each item in the character sheet gear flyout (the popup of same-slot bag items that appears when hovering an equipped slot), coloured by quality."] = "Mostra il livello oggetto su ogni oggetto nel menu a comparsa equipaggiamento della scheda personaggio (il popup degli oggetti borsa dello stesso slot che appare al passaggio del mouse su uno slot equipaggiato), colorato per qualità."
L["Shows the item level on weapons and armor a vendor sells."] = "Mostra il livello oggetto su armi e armature vendute da un mercante."
L["Shows the items as a list instead of pages."] = "Mostra gli oggetti come elenco invece che come pagine."
L["Shows the map pin next to the zone name."] = "Mostra il puntatore mappa accanto al nome della zona."
L["Shows the marker icon next to the coordinates."] = "Mostra l'icona indicatore accanto alle coordinate."
L["Shows the nameplate-style dragon badge on elite, rare elite, and rare targets."] = "Mostra il distintivo drago in stile targhetta nome sui bersagli elite, elite raro e raro."
L["Shows the online friend and guild counters."] = "Mostra i contatori di amici e gilda online."
L["Shows the overlay only for debuffs you can currently dispel."] = "Mostra la sovrapposizione solo per gli indebolimenti che puoi attualmente dissolvere."

-- == Batch 28 (missing keys diff, 2026-09-12): Shows the ping mark on a member's frame...Stamina ====
L["Shows the ping mark on a member's frame when someone pings them (needs Blizzard's Show Pings on Raid Frames setting on)."] = "Mostra il segno di ping sul riquadro di un membro quando qualcuno lo pinga (richiede l'impostazione di Blizzard Mostra ping sui riquadri incursione attivata)."
L["Shows the plugin's own icon next to its text."] = "Mostra l'icona propria del plugin accanto al suo testo."
L["Shows the plugin's text. Off leaves an icon-only block that still carries the plugin's tooltip and clicks."] = "Mostra il testo del plugin. Disattivato lascia un blocco solo icona che porta comunque la descrizione e i clic del plugin."
L["Shows the profession icons next to the text."] = "Mostra le icone professione accanto al testo."
L["Shows the raid target marker icon on boss frames."] = "Mostra l'icona indicatore bersaglio incursione sui riquadri boss."
L["Shows the rotation-helper ring on the button holding the One Button Assist action."] = "Mostra l'anello assistente rotazione sul pulsante che contiene l'azione Assistenza a un pulsante."
L["Shows the spec icon next to the text."] = "Mostra l'icona spec accanto al testo."
L["Shows the target marker directly before the enemy name text. Uses its own size and does not use the Core Positions raid marker slot."] = "Mostra l'indicatore bersaglio direttamente prima del testo del nome nemico. Usa la propria dimensione e non usa lo slot indicatore incursione di Posizioni principali."
L["Shows the window even when you can do nothing about what it reports. Every column is read from your own client, so this view is complete rather than degraded."] = "Mostra la finestra anche quando non puoi fare nulla su ciò che riporta. Ogni colonna viene letta dal tuo client, quindi questa visualizzazione è completa piuttosto che degradata."
L["Shows the zone and the subzone together instead of the subzone alone."] = "Mostra la zona e la sottozona insieme invece della sola sottozona."
L["Shows tick marks on channeled spells. Only supported spells are shown, request missing spells on Discord."] = "Mostra tacche sugli incantesimi incanalati. Vengono mostrati solo gli incantesimi supportati, richiedi gli incantesimi mancanti su Discord."
L["Shows where your interrupt will be ready during a cast. \"Tick\" marks the exact spot on the cast bar; \"Tick + Bar\" also colours the window during which your interrupt will be available."] = "Mostra dove la tua interruzione sarà pronta durante un lancio. \"Tacca\" contrassegna il punto esatto sulla barra di lancio; \"Tacca + Barra\" colora anche la finestra durante la quale la tua interruzione sarà disponibile."
L["Shows where your interrupt will be ready during an enemy cast. \"Tick\" marks the exact spot on the cast bar; \"Tick + Bar\" also colours the window during which your interrupt will be available."] = "Mostra dove la tua interruzione sarà pronta durante il lancio di un nemico. \"Tacca\" contrassegna il punto esatto sulla barra di lancio; \"Tacca + Barra\" colora anche la finestra durante la quale la tua interruzione sarà disponibile."
L["Shows your best split on upcoming bosses instead of only killed ones."] = "Mostra il tuo miglior tempo parziale sui boss prossimi invece che solo su quelli uccisi."
L["Shows your free bag slots."] = "Mostra i tuoi slot borsa liberi."
