L["Smallest on-screen size a reskinned bar is drawn at.\n\nWidget bars on a nameplate inherit that nameplate's scale, so they come out tiny on small units. Below this size the bar is scaled up instead, text and all.\n\nSet to 0 to mirror Blizzard's size exactly."] = "La dimensione minima a schermo a cui viene disegnata una barra con reskin.\n\nLe barre widget su una targhetta nome erediteranno la scala di quella targhetta nome, quindi risultano minuscole sulle unità piccole. Sotto questa dimensione la barra viene invece scalata verso l'alto, testo compreso.\n\nImposta a 0 per rispecchiare esattamente la dimensione di Blizzard."
