L["Sorting normally packs your items into the first free slots, at the top of the grid. Turn this on to pack them into the last slots instead, so the empty slots end up at the top. The item order itself does not change. This affects the OneBag, MultiBag and bank views -- category views fill their own grid with no gaps, so there is nothing to move. MultiBag and the bank use Blizzard's own sorting, so while this is on it also flips Blizzard's cleanup direction; turning it back off restores the direction you had."] = "L'ordinamento normalmente compatta i tuoi oggetti nei primi slot liberi, in cima alla griglia. Attiva questo per compattarli invece negli ultimi slot, così gli slot vuoti finiscono in cima. L'ordine degli oggetti stesso non cambia. Questo interessa le visualizzazioni OneBag, MultiBag e banca -- le visualizzazioni per categoria riempiono la propria griglia senza vuoti, quindi non c'è nulla da spostare. MultiBag e la banca usano l'ordinamento proprio di Blizzard, quindi mentre questo è attivo inverte anche la direzione di pulizia di Blizzard; disattivandolo di nuovo si ripristina la direzione che avevi."
