L["Suppresses \"You have learned a new spell/ability/passive effect\" and \"You have unlearned ...\" system messages, like the ones spammed every time you switch spec or talent loadout."] = "Sopprime i messaggi di sistema \"Hai imparato un nuovo incantesimo/abilità/effetto passivo\" e \"Hai disimparato ...\", come quelli che invadono ogni volta che cambi spec o configurazione talenti."
L["Suppresses right click targeting. Enemies applies everywhere. Allies In Combat only suppresses friendly targets while you are in combat, so you can still right click vendors and NPCs out of combat.\n\nNote: while this is active, holding Left+Right click to move forward won't work if your cursor is over a suppressed nameplate/unit, since this feature has to take over the right mouse button entirely to block targeting."] = "Sopprime il bersagliamento con clic destro. Nemici si applica ovunque. Alleati in combattimento sopprime i bersagli amichevoli solo mentre sei in combattimento, così puoi comunque fare clic destro su mercanti e PNG fuori dal combattimento.\n\nNota: mentre questo è attivo, tenere premuto Sinistro+Destro per muoverti avanti non funzionerà se il cursore è sopra una targhetta nome/unità soppressa, poiché questa funzionalità deve prendere il controllo completo del tasto destro del mouse per bloccare il bersagliamento."
