L["Switch Blizzard's chat bubbles off for as long as you are inside a dungeon, raid, scenario or battleground, and back on the way out.\n\nEllesmereUI never restyles bubbles inside an instance: the game's bubble frames are off limits to addons there. This decides whether Blizzard's own are visible at all."] = "Disattiva i fumetti chat di Blizzard per tutto il tempo in cui sei dentro un dungeon, un'incursione, uno scenario o un campo di battaglia, e li riattiva all'uscita.\n\nEllesmereUI non applica mai un nuovo stile ai fumetti dentro un'istanza: i riquadri fumetto del gioco sono off limits per gli addon lì. Questo decide se quelli propri di Blizzard sono visibili o no."
