L["Thank you for helping test EllesmereUI during beta! During testing, many systemic changes were made to build the foundation for a stable, flexible addon going forward.\n\nTo ensure a clean experience for everyone, all settings have been automatically reset. You will need to reconfigure your UI. We apologize for the inconvenience, and appreciate your patience.\n\nPrevious profile exports are no longer compatible and will need to be re-created."] = "Grazie per aver aiutato a testare EllesmereUI durante la beta! Durante i test, sono stati fatti molti cambiamenti sistemici per costruire le fondamenta di un addon stabile e flessibile per il futuro.\n\nPer garantire un'esperienza pulita per tutti, tutte le impostazioni sono state reimpostate automaticamente. Dovrai riconfigurare la tua interfaccia. Ci scusiamo per l'inconveniente, e apprezziamo la tua pazienza.\n\nLe esportazioni di profilo precedenti non sono più compatibili e dovranno essere ricreate."
L["Thank you for making EllesmereUI possible."] = "Grazie per aver reso possibile EllesmereUI."
L["Thank you to all who support EllesmereUI and its incredible support team!"] = "Grazie a tutti quelli che supportano EllesmereUI e il suo incredibile team di supporto!"
L["That setting is stored by list position and can't be safely overridden."] = "Quell'impostazione è memorizzata per posizione nell'elenco e non può essere sovrascritta in modo sicuro."
L["The Armory (%d)"] = "L'Armeria (%d)"
L["The Armory"] = "L'Armeria"
L["The Battle.net friend online and offline toast gets a window skin, with its own Friend Notifications card"] = "La notifica di amico Battle.net online e offline riceve una skin finestra, con la propria scheda Notifiche amici"
L["The Battle.net popup when a friend comes online or goes offline, plus broadcasts and invites."] = "Il popup Battle.net quando un amico va online o offline, più le trasmissioni e gli inviti."
L["The Blinding Vale"] = "La Valle Accecante" -- TODO: confirmar termo oficial
L["The Combat Indicator is not available for the Focus frame."] = "L'Indicatore combattimento non è disponibile per il riquadro Focus."
L["The Cooldown Manager can do far more than show cooldowns, it also has per-spell settings, bar glows, tracking bars and more! Check out some tips and tricks for getting more from it."] = "Il Gestore tempi di recupero può fare molto più che mostrare i tempi di recupero, ha anche impostazioni per incantesimo, bagliori barra, barre di tracciamento e altro! Scopri qualche consiglio e trucco per ottenere di più da esso."
L["The Dreamrift (Raid)"] = "La Faglia dei Sogni (Incursione)" -- TODO: confirmar termo oficial
L["The Dreamrift"] = "La Faglia dei Sogni" -- TODO: confirmar termo oficial
L["The Guild & Communities window: roster, chat, and the community list."] = "La finestra Gilda e Comunità: elenco membri, chat e l'elenco comunità."
L["The Hunt\n(Focus)"] = "La Caccia\n(Focus)" -- NAO-OFICIAL
L["The LFG Reminder popup now matches dungeon names on every client language, not only English and Russian."] = "Il popup Promemoria LFG ora corrisponde ai nomi dei dungeon in ogni lingua client, non solo inglese e russo."
L["The Missing Pet reminder no longer appears while mounted or flashes on dismount."] = "Il promemoria Pet mancante non appare più mentre sei in sella né lampeggia allo smontare."
L["The NPC dialog window: greeting text, gossip and quest options, and goodbye button."] = "La finestra di dialogo PNG: testo di saluto, opzioni di chiacchiera e missione, e pulsante di addio."
L["The NPC quest window: quest detail, progress, and reward panels plus the multi-quest greeting list."] = "La finestra missione PNG: pannelli dettaglio, progresso e ricompensa missione più l'elenco di saluto multi-missione."
L["The Pet Bar cannot use group-based visibility."] = "La Barra pet non può usare la visibilità basata su gruppo."
L["The Player Spells window: talents, spec selection, and the spellbook."] = "La finestra Incantesimi giocatore: talenti, selezione spec e il libro degli incantesimi."
L["The Ring of Valor"] = "L'Arena del Valore" -- TODO: confirmar termo oficial
L["The Rookery"] = "Il Nido" -- TODO: confirmar termo oficial
L["The Social window frame, border, title bar, Battle.net bar, search boxes, filter dropdowns and buttons. List contents and the side tab icons stay untouched."] = "Il riquadro finestra Sociale, bordo, barra del titolo, barra Battle.net, caselle di ricerca, menu a tendina filtro e pulsanti. I contenuti dell'elenco e le icone delle schede laterali restano intoccati."
L["The Venomous Abyss"] = "L'Abisso Velenoso" -- TODO: confirmar termo oficial
L["The Voidspire (Raid)"] = "La Guglia del Vuoto (Incursione)" -- TODO: confirmar termo oficial
L["The Voidspire"] = "La Guglia del Vuoto" -- TODO: confirmar termo oficial
L["The Whirlwind and Sweeping Strikes bar honors the Empty Bar Overlay again so spent charges show in Dark Mode, no longer draws a second set of divider lines with Bar Spacing set, hides its threshold strip while thresholds are disabled, and accepts a stack threshold up to 20."] = "La barra Turbine e Colpi Fendenti rispetta di nuovo la Sovrapposizione barra vuota così le cariche spese si mostrano in Modalità Scura, non disegna più un secondo set di linee divisorie con Spaziatura barra impostata, nasconde la sua striscia soglia mentre le soglie sono disattivate, e accetta una soglia pile fino a 20." -- NAO-OFICIAL (Whirlwind, Sweeping Strikes)
L["The \"You received\" popups for loot, currency, and upgrades."] = "I popup \"Hai ricevuto\" per bottino, valuta e miglioramenti."
L["The \"you have been invited to a group\" dialogs, with your role and Accept / Decline."] = "Le finestre di dialogo \"sei stato invitato in un gruppo\", con il tuo ruolo e Accetta / Rifiuta."
L["The achievement window: categories, rows, progress bars, and search."] = "La finestra successi: categorie, righe, barre di progresso e ricerca."
L["The active override's Buff Manager is bound to the open page. Leave the Buff Manager tab to switch overrides."] = "Il Gestore potenziamenti della sovrascrittura attiva è legato alla pagina aperta. Lascia la scheda Gestore potenziamenti per cambiare sovrascrittura."
L["The active override's custom %s is bound to this page. Leave the %s tab to switch to another override."] = "Il %s personalizzato della sovrascrittura attiva è legato a questa pagina. Lascia la scheda %s per passare a un'altra sovrascrittura."
L["The active override's custom Buff Manager is bound to this page. Leave the Buff Manager tab to switch to another override."] = "Il Gestore potenziamenti personalizzato della sovrascrittura attiva è legato a questa pagina. Lascia la scheda Gestore potenziamenti per passare a un'altra sovrascrittura."
L["The addon manager: list rows, checkboxes, and buttons."] = "Il gestore addon: righe elenco, caselle di controllo e pulsanti."
L["The amount of damage you can take"] = "La quantità di danno che puoi subire"
L["The auction house: browse, sell, and my auctions views."] = "La casa d'aste: le visualizzazioni sfoglia, vendi e le mie aste."
L["The background colour behind Dark Mode bars (Unit Frames, Raid Frames, Resource Bars)."] = "Il colore di sfondo dietro le barre in Modalità Scura (Riquadri unità, Riquadri incursione, Barre risorsa)."
L["The bank window catches up to the bags: nest OneBank and OneWarbank by expansion, group items by your bag categories with automatic splits by equipment slot, profession and material, and browse a category sidebar that spans your character bank and warband together."] = "La finestra banca si aggiorna alle borse: annida OneBank e OneWarbank per espansione, raggruppa gli oggetti per le tue categorie borsa con suddivisioni automatiche per slot di equipaggiamento, professione e materiale, e sfoglia una barra laterale categorie che copre insieme la banca del tuo personaggio e quella del warband."
L["The class and profession trainer window: skill list, train button, and cost display."] = "La finestra istruttore di classe e professione: elenco abilità, pulsante addestra e visualizzazione costo."
L["The class resource bar gains a spec picker to choose which specs show it, matching the power and health bars."] = "La barra risorsa di classe guadagna un selettore spec per scegliere quali spec la mostrano, corrispondendo alle barre energia e salute."
L["The customer crafting orders window: browse, order form, and my orders."] = "La finestra ordini di creazione clienti: sfoglia, modulo ordine e i miei ordini."
L["The damage and tank cut of Light of Nitex. The same style refocused on your rotation, procs, and cooldowns front and center."] = "Il taglio danno e tank di Light of Nitex. Lo stesso stile rifocalizzato sulla tua rotazione, proc e tempi di recupero in primo piano."
L["The damage dealer cut of Midnight Lily. A focused, low-clutter layout that keeps your rotation and cooldowns front and center."] = "Il taglio danno di Midnight Lily. Un layout focalizzato e poco affollato che mantiene la tua rotazione e i tempi di recupero in primo piano."
L["The dark counterpart to Lazar's Dawn. A moody, high-contrast layout that keeps focus locked on the fight."] = "La controparte scura di Lazar's Dawn. Un layout suggestivo e ad alto contrasto che mantiene il focus bloccato sullo scontro."
L["The default EllesmereUI look"] = "L'aspetto predefinito di EllesmereUI"
L["The delve difficulty window: tier dropdown, reward list and Enter button. The Map Properties row is left stock -- it is a Blizzard widget display and is not safe to restyle."] = "La finestra difficoltà incursione in solitaria: menu a tendina livello, elenco ricompense e pulsante Entra. La riga Proprietà mappa è lasciata originale -- è una visualizzazione widget di Blizzard e non è sicuro applicarle un nuovo stile."
L["The dispel type icon gains an Icon Size slider in its cog menu so you can make it larger or smaller."] = "L'icona del tipo di dissolvimento guadagna un cursore Dimensione icona nel suo menu ingranaggio così puoi renderla più grande o più piccola."
L["The display language for the EllesmereUI options panel. Auto follows your game client. Untranslated text falls back to English."] = "La lingua di visualizzazione per il pannello opzioni di EllesmereUI. Automatico segue il tuo client di gioco. Il testo non tradotto ricade sull'inglese."
L["The exact inverse of Skyriding (Airborne): anything that is not airborne on a glide-capable mount or flight form, standing on the ground included."] = "L'esatto inverso di Skyriding (In volo): qualsiasi cosa che non sia in volo su una cavalcatura capace di planare o una forma di volo, incluso stare in piedi al suolo."
L["The flat fill colour bars use when Dark Mode is enabled (Unit Frames, Raid Frames, Resource Bars)."] = "Il colore di riempimento uniforme che le barre usano quando la Modalità Scura è attivata (Riquadri unità, Riquadri incursione, Barre risorsa)."
L["The gap between a nested menu's icons and the entry that opens it."] = "Lo spazio tra le icone di un menu annidato e la voce che lo apre."
L["The gem socketing window with squared gem slots."] = "La finestra di incastonatura gemme con slot gemma squadrati."
L["The highlight overlay that appears on a spell button while it is the active/current action. Disable to hide it."] = "La sovrapposizione di evidenziazione che appare su un pulsante incantesimo mentre è l'azione attiva/attuale. Disattiva per nasconderla."
L["The housing dashboard window background, border, and title bar."] = "Lo sfondo, il bordo e la barra del titolo della finestra pannello di controllo alloggio."
L["The interrupt flash now clears the instant a target dies, so the cast bar no longer looks squished by the death animation."] = "Il lampo di interruzione ora si dissolve nell'istante in cui un bersaglio muore, così la barra di lancio non appare più compressa dall'animazione di morte."
L["The item conversion window (catalyst and similar kiosks)."] = "La finestra di conversione oggetti (catalizzatore e chioschi simili)."
L["The item preview / transmog dressing room window."] = "La finestra di anteprima oggetto / camerino transmog." -- JARGAO (Transmog)
L["The item upgrade window: upgrade slot, track selector, cost, and the currency strip."] = "La finestra di potenziamento oggetto: slot potenziamento, selettore traccia, costo e la striscia valuta."
L["The loot window: item rows with squared icons, kept item quality colors."] = "La finestra bottino: righe oggetto con icone squadrate, colori qualità oggetto mantenuti."
L["The macro editor: tabs, icon grid, text well, and buttons."] = "L'editor macro: schede, griglia icone, pozzo di testo e pulsanti."
L["The mailbox: inbox rows, send mail, open mail, and attachment slots."] = "La cassetta postale: righe posta in arrivo, invia posta, apri posta e slot allegati."
L["The monthly calendar grid, event dialogs, and navigation arrows."] = "La griglia calendario mensile, le finestre di dialogo evento e le freccette di navigazione."
L["The most cast bars shown at once. Extra casters take a bar as soon as one frees up."] = "Il numero massimo di barre di lancio mostrate contemporaneamente. I lanciatori extra occupano una barra non appena se ne libera una."
L["The need / greed / pass roll popups, with a squared icon and a flat roll timer."] = "I popup di tiro necessità / avidità / passa, con un'icona squadrata e un timer di tiro uniforme."
L["The overlay that appears on the icon when you hover your mouse over a spell button"] = "La sovrapposizione che appare sull'icona quando passi il mouse sopra un pulsante incantesimo"
L["The overlay that appears on the icon when you press and hold a spell button"] = "La sovrapposizione che appare sull'icona quando premi e tieni premuto un pulsante incantesimo"
L["The override group '%s' already provides the custom unlock mode for your current spec. Customize it there, or remove this spec from that group."] = "Il gruppo di sovrascrittura '%s' fornisce già la modalità sblocco personalizzata per la tua spec attuale. Personalizzala lì, oppure rimuovi questa spec da quel gruppo."
L["The panel the minimap Group Finder eye shows on hover: queue titles, role icons and counts, and time in queue."] = "Il pannello che l'occhio Ricerca gruppo della minimappa mostra al passaggio del mouse: titoli coda, icone e conteggi ruolo, e tempo in coda."
L["The pasted string could not be read completely. Please paste it again."] = "La stringa incollata non ha potuto essere letta completamente. Incollala di nuovo per favore."
L["The pending-rolls window: encounter picker, roll timer, and the result rows."] = "La finestra tiri in sospeso: selettore scontro, timer di tiro e le righe risultato."
L["The pet frame updates its name and portrait when you swap pets (for example Voidwalker to Felhunter)."] = "Il riquadro pet aggiorna il suo nome e ritratto quando cambi pet (per esempio da Vagante del Vuoto a Segugio Vil)." -- NAO-OFICIAL (Voidwalker, Felhunter)
L["The player-to-player trade window: frame, both item columns, the enchant slots, money rows and buttons. Item icons are squared and carry a rarity border. Both portraits are removed, as on every other window."] = "La finestra di scambio tra giocatori: riquadro, entrambe le colonne oggetto, gli slot incantamento, le righe denaro e i pulsanti. Le icone oggetto sono squadrate e portano un bordo rarità. Entrambi i ritratti sono rimossi, come su ogni altra finestra."
L["The profession crafting window: recipe list, schematic, specializations, and crafting orders."] = "La finestra di creazione professione: elenco ricette, schema, specializzazioni e ordini di creazione."
L["The professions overview book with squared icons and flat progress bars."] = "Il libro panoramica professioni con icone squadrate e barre di progresso uniformi."
L["The ready check prompt with its Yes / No buttons, plus the initiator's response list."] = "La richiesta di controllo pronti con i suoi pulsanti Sì / No, più l'elenco risposte dell'iniziatore."
L["The ready check prompt with its Yes / No buttons."] = "La richiesta di controllo pronti con i suoi pulsanti Sì / No."
L["The recipe preview window shown from a linked recipe or an inspected crafter."] = "La finestra di anteprima ricetta mostrata da una ricetta collegata o un creatore ispezionato."
L["The refresh rate now bottoms out at 0.5s (lower saved values move up to it), trimming memory churn during combat."] = "La frequenza di aggiornamento ora si ferma a un minimo di 0.5s (i valori salvati più bassi salgono a esso), riducendo il ricambio di memoria durante il combattimento."
L["The scriptProfile CVar is enabled."] = "La CVar scriptProfile è attivata."
L["The signature EllesmereUI layout exactly as designed. Vibrant class colors, clear cd tracking, and every module working in harmony."] = "Il layout distintivo di EllesmereUI esattamente come progettato. Colori di classe vivaci, tracciamento CD chiaro, e ogni modulo che lavora in armonia."
L["The single stack threshold is off while Multiple Thresholds is on."] = "La soglia pila singola è disattivata mentre Soglie multiple è attiva."
L["The size of your mana pool"] = "La dimensione della tua riserva di mana"
L["The spell picker now ends with a Missing Spells? shortcut that opens Blizzard's Cooldown Manager so you can add spells that are not listed."] = "Il selettore incantesimo ora termina con una scorciatoia Incantesimi mancanti? che apre il Gestore tempi di recupero di Blizzard così puoi aggiungere incantesimi che non sono elencati."
L["The standard buff grid"] = "La griglia potenziamenti standard"
L["The standard debuff grid"] = "La griglia indebolimenti standard"
L["The stricter in-combat subset of the raid set."] = "Il sottoinsieme più rigoroso in combattimento del set incursione."
L["The taintLog CVar is enabled."] = "La CVar taintLog è attivata."
L["The taintLog and scriptProfile CVars are enabled."] = "Le CVar taintLog e scriptProfile sono attivate."
L["The target effect's border size no longer snaps back to normal while a cast bar is shown with Border Wraps Around Cast Bar enabled."] = "La dimensione del bordo dell'effetto bersaglio non torna più bruscamente al normale mentre una barra di lancio è mostrata con Bordo avvolge la barra di lancio attivato."
L["The transmogrification window at the transmogrifier."] = "La finestra di trasmogrificazione al Trasmogrificatore."
L["The vendor window: item list, buyback, and bottom money bar."] = "La finestra venditore: elenco oggetti, riacquisto e barra denaro inferiore."
L["The widest angle a nest's entries may spread over. They stay on one ring for as long as they fit inside it; the rest go onto a second ring further out."] = "L'angolo più ampio su cui le voci di un nido possono distribuirsi. Restano su un anello finché ci stanno dentro; il resto va su un secondo anello più esterno."
L["The widest angle a nest's entries may spread over."] = "L'angolo più ampio su cui le voci di un nido possono distribuirsi."
L["The world map window chrome and the quest log side panel."] = "La cornice della finestra mappa del mondo e il pannello laterale registro missioni."
L["Themed Blizzard frames: Character Sheet, tooltips, menus, popups, Dragon Riding HUD."] = "Riquadri Blizzard a tema: Scheda personaggio, descrizioni, menu, popup, HUD Cavalcare Draghi."
L["Themed Blizzard frames: window skins, tooltips, menus, popups, Dragon Riding HUD."] = "Riquadri Blizzard a tema: skin finestra, descrizioni, menu, popup, HUD Cavalcare Draghi."
L["These are the same settings found on each module's own pages, not separate ones."] = "Queste sono le stesse impostazioni trovate nelle pagine proprie di ogni modulo, non separate."
L["These settings prioritize frame rate and visual clarity over environmental detail. Textures stay high quality so your character and the world still look perfect."] = "Queste impostazioni privilegiano il frame rate e la nitidezza visiva rispetto al dettaglio ambientale. Le trame rimangono di alta qualità così il tuo personaggio e il mondo appaiono ancora perfetti."
L["These specs hold override values that no group's editing mode can reach anymore (left behind by membership changes). They still apply. Remove one to return that spec to the shared default."] = "Queste spec contengono valori di sovrascrittura che nessuna modalità di modifica di gruppo può più raggiungere (lasciati indietro da cambi di appartenenza). Si applicano comunque. Rimuovine una per far ritornare quella spec al valore predefinito condiviso."
L["Thick"] = "Spesso"
L["Thickness applies to Solid Border and Pixel Glow"] = "Lo spessore si applica a Bordo a tinta unita e Bagliore pixel"
L["Thickness in physical pixels for Solid Border and Pixel Glow."] = "Spessore in pixel fisici per Bordo a tinta unita e Bagliore pixel."
L["Thickness in physical pixels. -1 follows the Debuff Manager's Border setting, 0 hides the dispel color border."] = "Spessore in pixel fisici. -1 segue l'impostazione Bordo del Gestore indebolimenti, 0 nasconde il bordo colore dissolvimento."
L["Thickness of any Pixel Glow assigned to this bar's buttons. Assign glows by right-clicking an icon in the preview."] = "Spessore di qualsiasi Bagliore pixel assegnato ai pulsanti di questa barra. Assegna bagliori con clic destro su un'icona nell'anteprima."
L["Thickness of the Pixel Glow applied to this bar's buff icons."] = "Spessore del Bagliore pixel applicato alle icone potenziamento di questa barra."
L["Thickness"] = "Spessore"
L["Thin Line Bottom"] = "Linea sottile in basso"
L["Thin Line Top"] = "Linea sottile in alto"
L["Third Timer"] = "Terzo timer"
L["This Action Bar is also used as the Moonkin Form bar.\nChanging spells on a Druid for this bar will also change them on your Moonkin Form bar."] = "Questa Barra delle azioni viene usata anche come barra Forma di Gufo Lunare.\nCambiare gli incantesimi su un Druido per questa barra li cambierà anche sulla tua barra Forma di Gufo Lunare." -- NAO-OFICIAL (Moonkin Form)
L["This Setting Has Overrides"] = "Questa impostazione ha sovrascritture"
L["This bar has an Additional Bar Offset (X %1$s, Y %2$s) set in its options. Unlock mode shows the base position; the offset re-applies when you exit."] = "Questa barra ha uno Scostamento barra aggiuntivo (X %1$s, Y %2$s) impostato nelle sue opzioni. La modalità sblocco mostra la posizione base; lo scostamento si riapplica quando esci."
L["This bar sizes its blocks itself, so the width is not this block's to choose."] = "Questa barra dimensiona i propri blocchi da sé, quindi la larghezza non è di questo blocco da scegliere."
L["This bar will always be attached to your current target's nameplate"] = "Questa barra sarà sempre collegata alla targhetta nome del tuo bersaglio attuale"
L["This bar will always be attached to your focus target's nameplate"] = "Questa barra sarà sempre collegata alla targhetta nome del tuo bersaglio focus"
L["This bar will only show if you have an enemy targeted"] = "Questa barra si mostrerà solo se hai un nemico come bersaglio"
L["This block is already the 'Fill Remaining Space' block. Check another block to move the role."] = "Questo blocco è già il blocco 'Riempi spazio rimanente'. Seleziona un altro blocco per spostare il ruolo."
L["This can't change which spells the user tracks in Blizzard's CDM.\nIt's recommended to also share your Blizzard CDM layout for any spec you choose here."] = "Questo non può cambiare quali incantesimi l'utente monitora nel CDM di Blizzard.\nSi consiglia di condividere anche il tuo layout CDM di Blizzard per qualsiasi spec tu scelga qui."
L["This cannot be undone. Consider exporting this profile as a backup first."] = "Questa azione non può essere annullata. Considera di esportare prima questo profilo come backup."
L["This cannot be undone. Export your own profile as a backup first."] = "Questa azione non può essere annullata. Esporta prima il tuo profilo come backup."
L["This change requires a UI reload to take effect."] = "Questa modifica richiede un ricaricamento dell'interfaccia per avere effetto."
L["This condition is coming in a future update."] = "Questa condizione arriverà in un futuro aggiornamento."
L["This conditional is not active right now. Meet one of its conditions first (for example, enter the dungeon) so you can arrange the layout in its real context."] = "Questo condizionale non è attivo al momento. Soddisfa prima una delle sue condizioni (per esempio, entra nel dungeon) così puoi disporre il layout nel suo contesto reale."
L["This control recently changed direction: it now copies FROM the frame you choose. Confirming will copy all shared settings FROM %1$s TO %2$s."] = "Questo controllo ha recentemente cambiato direzione: ora copia DAL riquadro che scegli. Confermare copierà tutte le impostazioni condivise DA %1$s A %2$s."
L["This element cannot use group-based visibility."] = "Questo elemento non può usare la visibilità basata su gruppo."
L["This element doesn't support both Height and Width matching"] = "Questo elemento non supporta sia l'abbinamento Altezza che Larghezza"
L["This element shows as soon as ONE Show condition matches. Hide keeps its meaning in both match modes: a checked Hide always hides, on every row."] = "Questo elemento si mostra non appena UNA condizione Mostra corrisponde. Nascondi mantiene il suo significato in entrambe le modalità di corrispondenza: un Nascondi selezionato nasconde sempre, su ogni riga."
L["This element shows as soon as ONE condition matches, and a Hide lane then means show while that condition is false."] = "Questo elemento si mostra non appena UNA condizione corrisponde, e una corsia Nascondi allora significa mostra mentre quella condizione è falsa."
L["This element will only show while you are inside a house or plot"] = "Questo elemento si mostrerà solo mentre sei dentro una casa o un terreno"
L["This element will only show while you are mounted"] = "Questo elemento si mostrerà solo mentre sei in sella"
L["This export includes cross profile settings that will overwrite the importing user's settings including Quality of Life, Hovercast and more that should typically not be shared with standard profiles. THIS IS NOT RECOMMENDED for public sharing of profiles."] = "Questa esportazione include impostazioni cross-profilo che sovrascriveranno le impostazioni dell'utente che importa, incluse Qualità della vita, Hovercast e altro che tipicamente non dovrebbe essere condiviso con profili standard. QUESTO NON È CONSIGLIATO per la condivisione pubblica di profili."
L["This feature optimizes your in-game graphics settings to give you the best combination of high FPS and visual clarity.\n\nYou can revert all changes at any time by clicking \"Restore My Settings\" which will appear after optimizing.\n\n\nWhat we change:\n\n"] = "Questa funzionalità ottimizza le tue impostazioni grafiche in gioco per darti la miglior combinazione di FPS elevati e nitidezza visiva.\n\nPuoi annullare tutte le modifiche in qualsiasi momento cliccando \"Ripristina le mie impostazioni\" che apparirà dopo l'ottimizzazione.\n\n\nCosa cambiamo:\n\n"
L["This feature optimizes your in-game graphics settings to give you the best combination of high FPS and visual clarity.\n\nYou can revert all changes at any time by clicking \"Restore My Settings\" which will appear after optimizing.\n\n\nWhat we change:\n\nShadow Quality - Fair (balanced quality/FPS)\nLiquid Detail - Disabled\nParticle Density - Set to Ultra (keeps important spell effects)\nSSAO (Ambient Occlusion) - Disabled\nDepth Effects - Disabled\nCompute Effects - Disabled\nOutline Mode - Disabled\nTexture Resolution - Set to High\nSpell Density - Set to Essential\nProjected Textures - Enabled (needed for ground effects)\nView Distance - Reduced to 1\nEnvironment Detail - Reduced to 1\nGround Clutter - Reduced to 1\nRaid/Dungeon Settings - Uses same settings everywhere\nResample Sharpening - Enabled (crisper image)\nContrast - Boosted by +10 (if currently 55 or below)\nEnable Reverb - Disabled (spell and interrupt audio cues stay crisp)\n\nThese settings prioritize frame rate and visual clarity over environmental detail. Textures stay high quality so your character and the world still look perfect."] = "Questa funzionalità ottimizza le tue impostazioni grafiche in gioco per darti la miglior combinazione di FPS elevati e nitidezza visiva.\n\nPuoi annullare tutte le modifiche in qualsiasi momento cliccando \"Ripristina le mie impostazioni\" che apparirà dopo l'ottimizzazione.\n\n\nCosa cambiamo:\n\nQualità ombre - Discreta (qualità/FPS bilanciati)\nDettaglio liquidi - Disattivato\nDensità particelle - Imposta su Ultra (mantiene gli effetti incantesimo importanti)\nSSAO (Occlusione ambientale) - Disattivata\nEffetti di profondità - Disattivati\nEffetti calcolati - Disattivati\nModalità contorno - Disattivata\nRisoluzione trama - Imposta su Alta\nDensità incantesimi - Imposta su Essenziale\nTrame proiettate - Attivate (necessarie per gli effetti al suolo)\nDistanza di visualizzazione - Ridotta a 1\nDettaglio ambiente - Ridotto a 1\nDetriti al suolo - Ridotti a 1\nImpostazioni Incursione/Dungeon - Usa le stesse impostazioni ovunque\nNitidezza ricampionamento - Attivata (immagine più nitida)\nContrasto - Aumentato di +10 (se attualmente 55 o meno)\nAttiva riverbero - Disattivato (gli indizi audio di incantesimi e interruzioni restano nitidi)\n\nQueste impostazioni privilegiano il frame rate e la nitidezza visiva rispetto al dettaglio ambientale. Le trame rimangono di alta qualità così il tuo personaggio e il mondo appaiono ancora perfetti."
L["This feature requires Snap Elements to be enabled"] = "Questa funzionalità richiede che Aggancio elementi sia attivato"
L["This feature runs continuous range checks against every visible enemy nameplate. It is one of the more expensive features in EllesmereUI and can measurably increase CPU usage in crowded areas."] = "Questa funzionalità esegue controlli di portata continui contro ogni targhetta nome nemico visibile. È una delle funzionalità più costose in EllesmereUI e può aumentare in modo misurabile l'uso della CPU in aree affollate."
L["This frame's source changes require a UI reload to take effect."] = "I cambi di fonte di questo riquadro richiedono un ricaricamento dell'interfaccia per avere effetto."
L["This group's custom Buff Manager can only be activated or edited while playing one of its specs."] = "Il Gestore potenziamenti personalizzato di questo gruppo può essere attivato o modificato solo mentre giochi una delle sue spec."
L["This group's custom Debuff Manager can only be activated or edited while playing one of its specs."] = "Il Gestore indebolimenti personalizzato di questo gruppo può essere attivato o modificato solo mentre giochi una delle sue spec."
L["This is a voice preview"] = "Questa è un'anteprima voce"
L["This is the Spell Queue Window, it helps with making sure you can't queue up too many spells at once which makes the game feel laggy. Recommended settings are generally a minimum of 200 + your local ping. If you are unsure of exactly what this setting does, leave it at 400."] = "Questa è la Finestra coda incantesimi, aiuta ad assicurare che non puoi accodare troppi incantesimi alla volta, il che fa sentire il gioco laggoso. Le impostazioni consigliate sono generalmente un minimo di 200 + il tuo ping locale. Se non sei sicuro di cosa faccia esattamente questa impostazione, lasciala a 400."
L["This is the Spell Queue Window, it helps with making sure you can't queue up too many spells at once which makes the game feel laggy. Recommended settings are generally ~150 for melee and ~300 for casters. Higher if you have high local ping."] = "Questa è la Finestra coda incantesimi, aiuta ad assicurare che non puoi accodare troppi incantesimi alla volta, il che fa sentire il gioco laggoso. Le impostazioni consigliate sono generalmente ~150 per il corpo a corpo e ~300 per i lanciatori. Più alto se hai un ping locale elevato."
L["This is the full overlay that swipes from right to left on the icon during its cast duration"] = "Questa è la sovrapposizione completa che spazza da destra a sinistra sull'icona durante la sua durata di lancio"
L["This is the spec you're syncing from -- it's always included."] = "Questa è la spec da cui stai sincronizzando -- è sempre inclusa."
L["This is where you can control the settings of Unlock Mode.\n\nElements can be repositioned by dragging or arrow keys (+shift)\nAnchor, Height Match, or Width match any element.\nSnapping is based on closest element, but you can snap only to\n a specific element via right click or the settings icon."] = "Qui puoi controllare le impostazioni della Modalità sblocco.\n\nGli elementi possono essere riposizionati trascinando o con i tasti freccia (+shift)\nAncora, Abbina altezza o Abbina larghezza a qualsiasi elemento.\nL'aggancio si basa sull'elemento più vicino, ma puoi agganciare solo a\n un elemento specifico tramite clic destro o l'icona impostazioni."
L["This makes it so the width of the cast bar includes the icon, rather than placing it to the left of the cast bars width."] = "Questo fa in modo che la larghezza della barra di lancio includa l'icona, invece di posizionarla a sinistra della larghezza della barra di lancio."
L["This module can't be overridden. Exit the override editing session to open it."] = "Questo modulo non può essere sovrascritto. Esci dalla sessione di modifica sovrascrittura per aprirlo."
L["This module is excluded from Spec Overrides."] = "Questo modulo è escluso dalle Sovrascritture spec."
L["This option Show Duration (Inside Cog) Enabled"] = "Questa opzione Mostra durata (dentro l'ingranaggio) attivata"
L["This option allows you to set custom frame sizing and positioning to different raid sizes. Note: This does NOT resize/reposition frames while in combat, if players join/leave mid combat it will resize after combat completes."] = "Questa opzione ti permette di impostare dimensionamento e posizionamento personalizzati del riquadro per diverse dimensioni di incursione. Nota: questo NON ridimensiona/riposiziona i riquadri durante il combattimento, se i giocatori entrano/escono a metà combattimento si ridimensionerà dopo che il combattimento finisce."
L["This option applies to bar-type resources only (pips use stack counts)."] = "Questa opzione si applica solo alle risorse di tipo barra (i puntini usano i conteggi pile)."
L["This option applies to pip-type resources only."] = "Questa opzione si applica solo alle risorse di tipo puntino."
L["This option can't be used while Expand Power Bar if No Resource is enabled."] = "Questa opzione non può essere usata mentre Espandi barra energia se nessuna risorsa è attivata."
L["This option can't be used while Shift Elements if No Resource is enabled."] = "Questa opzione non può essere usata mentre Sposta elementi se nessuna risorsa è attivata."
L["This option can't be used while you have the Power Bar Height Matched in the Unlock Mode."] = "Questa opzione non può essere usata mentre hai l'Altezza barra energia abbinata nella Modalità sblocco."
L["This option does not apply while Anchor to Cursor is enabled"] = "Questa opzione non si applica mentre Ancora al cursore è attivato"
L["This option does not work with Blizzard Bars. Please use Blizzard Edit Mode."] = "Questa opzione non funziona con le Barre Blizzard. Usa la Modalità modifica di Blizzard."
L["This option is currently under maintenance"] = "Questa opzione è attualmente in manutenzione"
L["This option is disabled while a Center Text is selected."] = "Questa opzione è disattivata mentre un Testo centrale è selezionato."
L["This option is not available for custom shaped icons"] = "Questa opzione non è disponibile per le icone con forma personalizzata"
L["This option is not supported for this bar type"] = "Questa opzione non è supportata per questo tipo di barra"
L["This option is now controlled by the Raid Frames addon"] = "Questa opzione è ora controllata dall'addon Riquadri incursione"
L["This option is only available for abilities with multiple charges"] = "Questa opzione è disponibile solo per le abilità con cariche multiple"
L["This option is only available for formats that display a percentage."] = "Questa opzione è disponibile solo per i formati che mostrano una percentuale."
L["This option is only available for the Custom Color Theme"] = "Questa opzione è disponibile solo per il Tema colore personalizzato"
L["This option is only available when Portrait Mode is Detached."] = "Questa opzione è disponibile solo quando la Modalità ritratto è Distaccata."
L["This option is only used by the Basic border."] = "Questa opzione è usata solo dal bordo Base."
L["This option only affects Raid Buffs and Paladin Beacons"] = "Questa opzione interessa solo Potenziamenti incursione e Fari Paladino" -- NAO-OFICIAL (Beacon of Light)
L["This option requires %s to be enabled"] = "Questa opzione richiede che %s sia attivato"
L["This option requires <text> to be enabled"] = "Questa opzione richiede che <text> sia attivato"
L["This option requires Add Friendly Boss Group to be set to Healers or Always."] = "Questa opzione richiede che Aggiungi gruppo boss amico sia impostato su Guaritori o Sempre."
L["This option requires Blizzard Style Action Bars to be disabled"] = "Questa opzione richiede che Barre delle azioni in Stile Blizzard sia disattivato"
