L["This option requires Class Resource to be set to Modern."] = "Questa opzione richiede che Risorsa di classe sia impostata su Moderno."
L["This option requires Combine Spell Name and Target to be disabled."] = "Questa opzione richiede che Combina nome incantesimo e bersaglio sia disattivato."
L["This option requires Countdown Format to count GCDs inside Arcane Soul"] = "Questa opzione richiede che Formato conto alla rovescia conti i CGC dentro Anima Arcana" -- NAO-OFICIAL (Arcane Soul)
L["This option requires Dark Mode Class Resource to be disabled. Dark Mode colors can be adjusted in Global Settings -> Fonts & Colors."] = "Questa opzione richiede che Risorsa di classe Modalità Scura sia disattivato. I colori della Modalità Scura possono essere modificati in Impostazioni globali -> Caratteri e colori."
L["This option requires Display Style to be set to Icon"] = "Questa opzione richiede che Stile visualizzazione sia impostato su Icona"
L["This option requires Display Style to be set to Text"] = "Questa opzione richiede che Stile visualizzazione sia impostato su Testo"
L["This option requires Fill Color to be set to Custom"] = "Questa opzione richiede che Colore riempimento sia impostato su Personalizzato"
L["This option requires Icon Shape to be set to None or Cropped"] = "Questa opzione richiede che Forma icona sia impostata su Nessuno o Ritagliata"
L["This option requires Pixel Glow to be the selected glow type"] = "Questa opzione richiede che Bagliore pixel sia il tipo di bagliore selezionato"
L["This option requires Portrait Mode to be set to Detached."] = "Questa opzione richiede che la Modalità ritratto sia impostata su Distaccata."
L["This option requires Set UI Scale to 0.5333 to be disabled"] = "Questa opzione richiede che Imposta scala interfaccia a 0.5333 sia disattivato"
L["This option requires Show Tanks in Extra Group or a bound hotkey."] = "Questa opzione richiede Mostra Tank nel gruppo extra o un tasto rapido associato."
L["This option requires Show Tooltips to be set to hide tooltips"] = "Questa opzione richiede che Mostra descrizioni sia impostato per nascondere le descrizioni"
L["This option requires Split Compare to include a key level"] = "Questa opzione richiede che Confronto tempo parziale includa un livello chiave"
L["This option requires Subtitle Text to include the Guild Name"] = "Questa opzione richiede che Testo sottotitolo includa il Nome gilda"
