L["This option requires Tooltips to be set to Shown on Modifier"] = "Questa opzione richiede che Descrizioni sia impostato su Mostrato al modificatore"
L["This option requires a Border Size above 0."] = "Questa opzione richiede una Dimensione bordo sopra 0."
L["This option requires a Class Icon other than None."] = "Questa opzione richiede un'Icona classe diversa da Nessuno."
L["This option requires a Duration Text position other than None"] = "Questa opzione richiede una posizione Testo durata diversa da Nessuno"
L["This option requires a Glow Type other than None"] = "Questa opzione richiede un Tipo bagliore diverso da Nessuno"
L["This option requires a Health Text format other than None"] = "Questa opzione richiede un formato Testo salute diverso da Nessuno"
L["This option requires a Name Text position other than None"] = "Questa opzione richiede una posizione Testo nome diversa da Nessuno"
L["This option requires a Power Text format other than None"] = "Questa opzione richiede un formato Testo risorsa diverso da Nessuno"
L["This option requires a Split Compare mode"] = "Questa opzione richiede una modalità Confronto tempo parziale"
L["This option requires a Stacks Text position other than None"] = "Questa opzione richiede una posizione Testo pile diversa da Nessuno"
L["This option requires a cooldown-tracking bar"] = "Questa opzione richiede una barra di tracciamento tempo di recupero"
L["This option requires a custom glow to be selected"] = "Questa opzione richiede che sia selezionato un bagliore personalizzato"
L["This option requires a custom thickness to be set."] = "Questa opzione richiede che sia impostato uno spessore personalizzato."
L["This option requires a detached position to be active."] = "Questa opzione richiede che sia attiva una posizione distaccata."
L["This option requires a dropdown selection other than Above Health Bar"] = "Questa opzione richiede una selezione dal menu a tendina diversa da Sopra la barra salute"
L["This option requires a gradient to be set"] = "Questa opzione richiede che sia impostato un gradiente"
L["This option requires a non-custom button shape"] = "Questa opzione richiede una forma pulsante non personalizzata"
