L["This option requires a non-custom shaped action bar"] = "Questa opzione richiede una barra delle azioni con forma non personalizzata"
L["This option requires a perpendicular Group Growth"] = "Questa opzione richiede una Crescita gruppo perpendicolare"
L["This option requires a style that draws the glow ring"] = "Questa opzione richiede uno stile che disegna l'anello del bagliore"
L["This option requires a text position other than none."] = "Questa opzione richiede una posizione testo diversa da nessuno."
L["This option requires a text selection other than none."] = "Questa opzione richiede una selezione testo diversa da nessuno."
