L["This option requires the module to be enabled"] = "Questa opzione richiede che il modulo sia attivato"
L["This option requires the position setting to be detached"] = "Questa opzione richiede che l'impostazione posizione sia distaccata"
L["This override has no indicators for this spec, so nothing shows here until you add some."] = "Questa sovrascrittura non ha indicatori per questa spec, quindi non appare nulla qui finché non ne aggiungi qualcuno."
L["This overwrites the chosen frame's current settings. Frame position, visibility, and enable state are not changed."] = "Questo sovrascrive le impostazioni attuali del riquadro scelto. Posizione riquadro, visibilità e stato di attivazione non vengono modificati."
L["This overwrites this action menu's current settings. Its actions, name, and keybind are not changed."] = "Questo sovrascrive le impostazioni attuali di questo menu azione. Le sue azioni, nome e associazione tasti non vengono modificati."
L["This overwrites this frame's current settings. Frame position, visibility, and enable state are not changed."] = "Questo sovrascrive le impostazioni attuali di questo riquadro. Posizione riquadro, visibilità e stato di attivazione non vengono modificati."
L["This page is excluded from overrides."] = "Questa pagina è esclusa dalle sovrascritture."
L["This permanently overwrites this profile's settings with the override '%s': its captured settings and its custom Unlock Mode and Buff Manager layouts (where present) become the profile's own baseline for every spec. ALL spec override groups on this profile are then deleted and the UI reloads. Conditional overrides are not affected."] = "Questo sovrascrive permanentemente le impostazioni di questo profilo con la sovrascrittura '%s': le sue impostazioni catturate e i suoi layout personalizzati di Modalità sblocco e Gestore potenziamenti (dove presenti) diventano la base propria del profilo per ogni spec. TUTTI i gruppi di sovrascrittura spec su questo profilo vengono poi eliminati e l'interfaccia si ricarica. Le sovrascritture condizionali non sono interessate."
L["This preset"] = "Questo preset"
L["This profile already holds 16 action menus"] = "Questo profilo contiene già 16 menu azione"
L["This profile string does not carry any Window & Tooltip Skins settings."] = "Questa stringa profilo non porta alcuna impostazione Skin finestra e descrizione."
