L["This profile string does not carry any global settings."] = "Questa stringa di profilo non contiene impostazioni globali."
L["This profile string does not carry any override data."] = "Questa stringa di profilo non contiene dati di override."
L["This profile was made at %1$d%% UI scale; yours is %2$d%%. Change your UI scale to match the imported profile? This will show all profiles at this scale as UI Scale is not a per-profile setting, but can be changed at any time back to your original value."] = "Questo profilo è stato creato con una Scala interfaccia del %1$d%%; la tua è %2$d%%. Vuoi modificare la Scala interfaccia per farla corrispondere al profilo importato? Questo mostrerà tutti i profili con questa scala, poiché la Scala interfaccia non è un'impostazione per singolo profilo, ma può essere ripristinata al valore originale in qualsiasi momento."
L["This replaces %d existing value(s) for this setting across your specs."] = "Questo sostituisce %d valore/i esistente/i per questa impostazione in tutte le tue specializzazioni."
L["This replaces %d existing value(s) for this setting across your specs. Do you want to continue?"] = "Questo sostituisce %d valore/i esistente/i per questa impostazione in tutte le tue specializzazioni. Vuoi continuare?"
L["This replaces %d existing value(s) for this setting on this bar."] = "Questo sostituisce %d valore/i esistente/i per questa impostazione su questa barra."
L["This replaces %d existing value(s) for this setting on this bar. Do you want to continue?"] = "Questo sostituisce %d valore/i esistente/i per questa impostazione su questa barra. Vuoi continuare?"
L["This replaces 3 existing value(s) for this setting across your specs. Do you want to continue?"] = "Questo sostituisce 3 valore/i esistente/i per questa impostazione in tutte le tue specializzazioni. Vuoi continuare?"
L["This resets every EUI addon, not just the current one."] = "Questo ripristina ogni addon EUI, non solo quello attuale."
L["This setting already has an override for %s"] = "Questa impostazione ha già un override per %s"
L["This setting can't be overridden."] = "Questa impostazione non può avere un override."
L["This setting requires a UI reload to take effect."] = "Questa impostazione richiede un ricaricamento dell'interfaccia per avere effetto."
L["This setting's active Apply to Bar (All Specs) value will be replaced."] = "Il valore attivo di Applica a barra (Tutte le specializzazioni) di questa impostazione verrà sostituito."
L["This setting's active Apply to Bar value will be replaced."] = "Il valore attivo di Applica a barra di questa impostazione verrà sostituito."
L["This spec doesn't have this spell."] = "Questa specializzazione non ha questo incantesimo."
L["This spec's custom unlock mode is owned by '%s'. Customize it there, or remove the spec from that group."] = "La modalità sblocco personalizzata di questa specializzazione appartiene a '%s'. Personalizzala lì, oppure rimuovi la specializzazione da quel gruppo."
L["This spell"] = "Questo incantesimo"
L["This spell is already being used on %s"] = "Questo incantesimo è già usato su %s"
L["This string is a FULL ACCOUNT export. It replaces your account-wide settings with the sender's, including Quality of Life, HoverCast bindings, Cooldown Manager spell setups, unlock anchors, UI scale, and profile keybinds -- not just a profile. Your other profiles are kept, but a profile with the same name is replaced."] = "Questa stringa è un'esportazione ACCOUNT COMPLETO. Sostituisce le tue impostazioni a livello di account con quelle di chi l'ha condivisa, incluse Quality of Life, associazioni HoverCast, configurazioni degli incantesimi del Gestore recuperi, ancoraggi di sblocco, Scala interfaccia e tasti di scelta rapida dei profili -- non solo un profilo. I tuoi altri profili vengono mantenuti, ma un profilo con lo stesso nome viene sostituito."
L["This unit uses the Blizzard default frame -- there are no EllesmereUI settings to configure here."] = "Questa unità usa il riquadro predefinito di Blizzard -- non ci sono impostazioni di EllesmereUI da configurare qui."
L["This unit's frame is hidden -- there are no EllesmereUI settings to configure here."] = "Il riquadro di questa unità è nascosto -- non ci sono impostazioni di EllesmereUI da configurare qui."
L["This will change the color of your bar if you have more than your chosen number of stacks"] = "Questo cambia il colore della tua barra se hai più del numero di cariche scelto"
L["This will create a fully unique Buff Manager for this conditional group. Changes made to your default Buff Manager will no longer affect it."] = "Questo crea un Gestore potenziamenti completamente unico per questo gruppo condizionale. Le modifiche fatte al tuo Gestore potenziamenti predefinito non lo influenzeranno più."
L["This will create a fully unique Buff Manager for this conditional group. Your current Buff Manager settings are copied as its starting point, and changes made to your default Buff Manager will no longer affect it."] = "Questo crea un Gestore potenziamenti completamente unico per questo gruppo condizionale. Le impostazioni attuali del tuo Gestore potenziamenti vengono copiate come punto di partenza, e le modifiche fatte al tuo Gestore potenziamenti predefinito non lo influenzeranno più."
L["This will create a fully unique Buff Manager for this override group. Changes made to your default Buff Manager will no longer affect these specs."] = "Questo crea un Gestore potenziamenti completamente unico per questo gruppo di override. Le modifiche fatte al tuo Gestore potenziamenti predefinito non influenzeranno più queste specializzazioni."
L["This will create a fully unique Buff Manager for this override group. Your current Buff Manager settings are copied as its starting point, and changes made to your default Buff Manager will no longer affect these specs."] = "Questo crea un Gestore potenziamenti completamente unico per questo gruppo di override. Le impostazioni attuali del tuo Gestore potenziamenti vengono copiate come punto di partenza, e le modifiche fatte al tuo Gestore potenziamenti predefinito non influenzeranno più queste specializzazioni."
L["This will create a fully unique Debuff Manager for this conditional group. Your current Debuff Manager settings are copied as its starting point, and changes made to your default Debuff Manager will no longer affect it."] = "Questo crea un Gestore indebolimenti completamente unico per questo gruppo condizionale. Le impostazioni attuali del tuo Gestore indebolimenti vengono copiate come punto di partenza, e le modifiche fatte al tuo Gestore indebolimenti predefinito non lo influenzeranno più."
L["This will create a fully unique Debuff Manager for this override group. Your current Debuff Manager settings are copied as its starting point, and changes made to your default Debuff Manager will no longer affect these specs."] = "Questo crea un Gestore indebolimenti completamente unico per questo gruppo di override. Le impostazioni attuali del tuo Gestore indebolimenti vengono copiate come punto di partenza, e le modifiche fatte al tuo Gestore indebolimenti predefinito non influenzeranno più queste specializzazioni."
L["This will create a fully unique unlock mode for this conditional group. Changes made to your default unlock mode will no longer affect it."] = "Questo crea una modalità sblocco completamente unica per questo gruppo condizionale. Le modifiche fatte alla tua modalità sblocco predefinita non la influenzeranno più."
L["This will create a fully unique unlock mode for this override group. Changes made to your default unlock mode will no longer affect these specs."] = "Questo crea una modalità sblocco completamente unica per questo gruppo di override. Le modifiche fatte alla tua modalità sblocco predefinita non influenzeranno più queste specializzazioni."
L["This will disable EllesmereUI Tracking Bars and show Blizzard's default Tracked Bars display instead."] = "Questo disattiva le Barre di monitoraggio di EllesmereUI e mostra invece la visualizzazione predefinita delle Barre monitorate di Blizzard."
L["This will discard your custom party settings for this section and use raid settings instead."] = "Questo scarta le tue impostazioni personalizzate del gruppo per questa sezione e usa invece le impostazioni dell'incursione."
L["This will display ALL of your debuffs on enemy nameplates, rather than only the important ones."] = "Questo mostra TUTTI i tuoi indebolimenti sulle targhette nemiche, invece che solo quelli importanti."
L["This will display the word \"FOCUS\" below caster/miniboss mobs in M+ if you have not set your focus. Disabled for specs with no kick."] = "Questo mostra la parola \"FOCUS\" sotto i mostri che lanciano incantesimi/miniboss in M+ se non hai impostato il tuo focus. Disattivato per le specializzazioni senza interruzione."
L["This will keep appearing each login until the layout is correct."] = "Questo continuerà a comparire a ogni accesso finché il layout non sarà corretto."
L["This will not override sorting by role"] = "Questo non sovrascrive l'ordinamento per ruolo"
L["This will not reset addon-specific Quick Setup."] = "Questo non ripristina la Configurazione rapida specifica dell'addon."
L["This will overwrite %1$s settings on the selected profiles with your current settings. Continue?"] = "Questo sovrascriverà le impostazioni %1$s dei profili selezionati con le tue impostazioni attuali. Continuare?"
L["This will physically scatter items to random positions in your bags. The changes persist even if you disable EllesmereUI Bags."] = "Questo sparpaglia fisicamente gli oggetti in posizioni casuali nelle tue borse. Le modifiche persistono anche se disattivi EllesmereUI Borse."
L["This will pin your bar to the window when it is not within the visible area"] = "Questo aggancia la tua barra alla finestra quando non è nell'area visibile"
L["This will replace YOUR Blizz UI Enhanced settings (the Window Skins and Tooltips, Menus & Popups tabs) with the sharer's, across ALL of your profiles. Your current settings on those two tabs cannot be recovered afterward."] = "Questo sostituisce LE TUE impostazioni di Interfaccia Blizz migliorata (le schede Skin finestre e Tooltip, menu e popup) con quelle di chi condivide, su TUTTI i tuoi profili. Le tue impostazioni attuali su quelle due schede non potranno essere recuperate in seguito."
L["This will reset all default bar spell assignments for the current spec to match Blizzard's CDM layout. Custom bars are not affected. Continue?"] = "Questo ripristina tutte le assegnazioni predefinite degli incantesimi delle barre per la specializzazione attuale in modo che corrispondano al layout del CDM di Blizzard. Le barre personalizzate non sono interessate. Continuare?"
L["This will reset all default bar spell assignments for the current spec to match Blizzard's CDM layout. Spells you added yourself (presets, custom IDs and racials) are kept. Continue?"] = "Questo ripristina tutte le assegnazioni predefinite degli incantesimi delle barre per la specializzazione attuale in modo che corrispondano al layout del CDM di Blizzard. Gli incantesimi che hai aggiunto tu stesso (preimpostazioni, ID personalizzati e abilità razziali) vengono mantenuti. Continuare?"
L["This will reset all saved panel positions and reload your UI."] = "Questo ripristina tutte le posizioni dei pannelli salvate e ricarica la tua interfaccia."
L["This will reset all saved panel positions and zoom levels and reload your UI."] = "Questo ripristina tutte le posizioni dei pannelli salvate e i livelli di zoom e ricarica la tua interfaccia."
