L["Tint an entry that would do nothing right now: red when the target is out of range, blue when you are short of the resource, and gray when the game refuses it for any other reason. Spells and items only -- the game reports every toy as unusable, and a macro's usability depends on what its body resolves to."] = "Colora una voce che al momento non farebbe nulla: rosso quando il bersaglio è fuori portata, blu quando ti manca la risorsa, e grigio quando il gioco la rifiuta per qualsiasi altro motivo. Solo incantesimi e oggetti -- il gioco segnala ogni giocattolo come inutilizzabile, e l'utilizzabilità di una macro dipende da come si risolve il suo contenuto."
L["Tint the bar with the Important colour when the enemy casts a spell the game flags as important."] = "Colora la barra con il colore Importante quando il nemico lancia un incantesimo che il gioco segnala come importante."
L["Tint the cast bar with the Important colour when the enemy casts a spell the game flags as important. Overrides the Interruptible Cast colour; your interrupt being on cooldown still takes priority."] = "Colora la barra di lancio con il colore Importante quando il nemico lancia un incantesimo che il gioco segnala come importante. Sovrascrive il colore Lancio interrompibile; se la tua interruzione è in ricarica ha comunque la priorità."
L["Tint the cast bar with the Important colour when the unit casts a spell the game flags as important. Your interrupt being on cooldown still takes priority."] = "Colora la barra di lancio con il colore Importante quando l'unità lancia un incantesimo che il gioco segnala come importante. Se la tua interruzione è in ricarica ha comunque la priorità."
L["Tint the combat icon by the member's class color. Not available for the Arcade/Dungeoneer/Classic/Cross/Circle/Square styles."] = "Colora l'icona di combattimento in base al colore di classe del membro. Non disponibile per gli stili Arcade/Dungeoneer/Classic/Cross/Circle/Square."
L["Tints the pattern with the bar's current color instead of the custom overlay color."] = "Colora il motivo con il colore attuale della barra invece del colore di sovrapposizione personalizzato."
L["Tints this block's slot with its own color."] = "Colora lo slot di questo blocco con il proprio colore."
