L["Toggles Blizzard's Show Numbers for Cooldowns setting (the countdownForCooldowns CVar) live. This is never saved to EllesmereUI -- it is the same as changing the option in Blizzard's settings."] = "Alterna dal vivo l'impostazione Mostra numeri per i tempi di recupero di Blizzard (la CVar countdownForCooldowns). Questo non viene mai salvato in EllesmereUI -- equivale a cambiare l'opzione nelle impostazioni di Blizzard."
