L["Toggles the Raid Tools panels, in or out of combat.\n\nLeft-click to set a keybind.\nRight-click to unbind."] = "Alterna i pannelli degli Strumenti raid, dentro o fuori dal combattimento.\n\nClic sinistro per impostare un'associazione tasti.\nClic destro per rimuovere l'associazione."
