L["Unlock Mode is how you move and resize everything in EllesmereUI, and it is packed with tools: anchors, width matching, fallback anchors, per-group layouts. This video gets you fluent fast."] = "La Modalità sblocco è il modo in cui sposti e ridimensioni tutto in EllesmereUI, ed è ricca di strumenti: ancoraggi, abbinamento larghezza, ancoraggi di riserva, layout per gruppo. Questo video ti rende esperto in fretta."
L["Unlock Mode is where you can adjust\npositioning for all the elements of EllesmereUI"] = "La Modalità sblocco è dove puoi regolare\nil posizionamento di tutti gli elementi di EllesmereUI"
L["Unlock Window to Close"] = "Sblocca finestra per chiudere"
