L["Use a world marker entry again to pick that marker back up. Off places the marker again, at the new position.\nThis does not change the entry that clears all world markers, or the cycling entry."] = "Usa di nuovo una voce indicatore di mondo per riprendere quell'indicatore. Off lo posiziona di nuovo, nella nuova posizione.\nQuesto non modifica la voce che rimuove tutti gli indicatori di mondo, né la voce di ciclo."
L["Use arrow keys to move selected element 1px any direction"] = "Usa i tasti freccia per spostare l'elemento selezionato di 1px in qualsiasi direzione"
L["Use the dropdown above to add a new bar"] = "Usa il menu a tendina sopra per aggiungere una nuova barra"
L["Use unique backgrounds for each bar"] = "Usa sfondi unici per ogni barra"
L["Used by the movement alert's Bar display mode."] = "Usato dalla modalità di visualizzazione Barra dell'avviso di movimento."
L["User-created info bars: clock, gold, XP, micro menu and more."] = "Barre informative create dall'utente: orologio, oro, XP, micro menu e altro."
L["Uses Blizzard's coin textures instead of the letter suffixes."] = "Usa le texture a moneta di Blizzard invece dei suffissi a lettera."
L["Uses Blizzard's own party switch, independent of the other channels. Instance chat, the one an LFG or LFR group talks in, is covered here too."] = "Usa l'interruttore del gruppo proprio di Blizzard, indipendente dagli altri canali. Anche la chat istanza, quella in cui parla un gruppo LFG o LFR, è coperta qui."
L["Uses Blizzard's own raid switch, which it ships off. Ticking this turns that switch on, and it is put back the way you had it when you untick it or switch the feature off."] = "Usa l'interruttore dell'incursione proprio di Blizzard, che viene spedito disattivato. Selezionando questa opzione lo attivi, e viene riportato com'era quando la deselezioni o disattivi la funzione."
L["Uses a random hearthstone toy variant each cast."] = "Usa una variante casuale di giocattolo Pietra Focolare a ogni lancio."
L["Uses the Hover Effect color and opacity. Set to None for the flat hover highlight."] = "Usa il colore e l'opacità dell'Effetto al passaggio del mouse. Imposta su Nessuno per l'evidenziazione piatta al passaggio del mouse."
L["Uses the entry you are pointing at while a menu is kept open with Toggle Menu Open. One key shared by every menu, claimed only while a menu is up -- a mouse button keeps its normal use the rest of the time."] = "Usa la voce su cui punti mentre un menu è mantenuto aperto con Mantieni menu aperto. Un tasto condiviso da ogni menu, riservato solo mentre un menu è aperto -- un pulsante del mouse mantiene il suo uso normale nel resto del tempo."
L["Uses the entry you are pointing at while a menu is kept open with Toggle Menu Open. One key shared by every menu, claimed only while a menu is up -- a mouse button keeps its normal use the rest of the time.\n\nLeft-click to set a keybind, then press any key or\nclick any mouse button to use it.\nEscape cancels. Right-click here to unbind."] = "Usa la voce su cui punti mentre un menu è mantenuto aperto con Mantieni menu aperto. Un tasto condiviso da ogni menu, riservato solo mentre un menu è aperto -- un pulsante del mouse mantiene il suo uso normale nel resto del tempo.\n\nClic sinistro per impostare un'associazione tasti, poi premi un tasto qualsiasi o\nclicca un pulsante del mouse per usarlo.\nEsc annulla. Clic destro qui per rimuovere l'associazione."
