L["When Present"] = "Quando presente"
L["When disabled, EUI relinquishes full control of friendly player nameplates to Blizzard. Use Blizzard's own Nameplate settings (Esc > Options > Nameplates) to control them."] = "Quando disattivato, EUI cede il controllo completo delle targhette dei giocatori amici a Blizzard. Usa le impostazioni Targhette di Blizzard (Esc > Opzioni > Targhette) per controllarle."
L["When enabled, BM and MM specs show Focus as the standard power bar instead of a class resource bar."] = "Quando attivato, le specializzazioni BM e MM mostrano il Focus come barra energia standard invece che come barra risorsa di classe."
L["When enabled, EUI relinquishes full control of friendly player nameplates to Blizzard."] = "Quando attivato, EUI cede il controllo completo delle targhette dei giocatori amici a Blizzard."
L["When enabled, Shift+Click any minimap button (mail, calendar, tracking, addon buttons) to drag it to a custom position."] = "Quando attivato, Maiusc+clic su qualsiasi pulsante della minimappa (posta, calendario, monitoraggio, pulsanti addon) per trascinarlo in una posizione personalizzata."
L["When enabled, Shift+Click any minimap button (mail, calendar, tracking, addon buttons) to drag it to a custom position. While dragging, buttons snap to nearby buttons and the minimap border; hold Ctrl together with Shift to disable snapping."] = "Quando attivato, Maiusc+clic su qualsiasi pulsante della minimappa (posta, calendario, monitoraggio, pulsanti addon) per trascinarlo in una posizione personalizzata. Durante il trascinamento, i pulsanti si aggancano ai pulsanti vicini e al bordo della minimappa; tieni premuto Ctrl insieme a Maiusc per disattivare l'aggancio."
L["When enabled, Shift+Click any sidebar icon to drag it to a custom position."] = "Quando attivato, Maiusc+clic su qualsiasi icona della barra laterale per trascinarla in una posizione personalizzata."
L["When enabled, debuff icons keep Blizzard's colored border instead of using the custom border."] = "Quando attivato, le icone degli indebolimenti mantengono il bordo colorato di Blizzard invece di usare il bordo personalizzato."
L["When enabled, left-click dragging a window will save its position without needing to hold Shift. Ctrl+drag still does a temporary move."] = "Quando attivato, trascinare una finestra con clic sinistro salva la sua posizione senza dover tenere premuto Maiusc. Ctrl+trascina esegue comunque uno spostamento temporaneo."
L["When enabled, left-click dragging the bag window will move it without needing to hold Shift."] = "Quando attivato, trascinare la finestra delle borse con clic sinistro la sposta senza dover tenere premuto Maiusc."
L["When enabled, nameplates stack vertically instead of overlapping."] = "Quando attivato, le targhette si accatastano verticalmente invece di sovrapporsi."
L["When enabled, the extra buttons (Great Vault, M+ Portals, Friends Online, Group Button) and any ungrouped minimap buttons only show while the mouse is over the minimap. The M+ Portals flyout keeps them shown until it closes."] = "Quando attivato, i pulsanti extra (Grande Forziere, Portali M+, Amici online, Pulsante gruppo) e qualsiasi pulsante minimappa non raggruppato si mostrano solo mentre il mouse è sulla minimappa. Il menu a comparsa dei Portali M+ li mantiene mostrati finché non si chiude."
L["When hovering any action bar set to Mouseover, all Mouseover bars will appear."] = "Al passaggio del mouse su qualsiasi barra azione impostata su Mouseover, tutte le barre Mouseover appariranno."
L["When on, augment rune/flask/food/weapon reminders still show (dimmed) when you have no matching item in your bags, as a prompt to restock.\nWhen off, they are hidden entirely if you don't carry the item."] = "Se attivo, i promemoria di rune di potenziamento/pozioni/cibo/arma continuano a mostrarsi (attenuati) quando non hai l'oggetto corrispondente nelle borse, come promemoria per rifornirti.\nSe disattivo, sono completamente nascosti se non porti l'oggetto."
L["When on, flask/food/weapon reminders still show (dimmed) when you have no matching item in your bags, as a prompt to restock.\nWhen off, they are hidden entirely if you don't carry the item."] = "Se attivo, i promemoria di pozioni/cibo/arma continuano a mostrarsi (attenuati) quando non hai l'oggetto corrispondente nelle borse, come promemoria per rifornirti.\nSe disattivo, sono completamente nascosti se non porti l'oggetto."
L["When the class resource bar is not shown, this automatically adds the class resource height to the power bar."] = "Quando la barra risorsa di classe non è mostrata, questo aggiunge automaticamente l'altezza della risorsa di classe alla barra energia."
L["When the current spec has no bars in this group, keeps elements anchored to the group in place and shifts them up or down by one bar height (tune with the cog's Extra Y Offset) to cover its empty slot."] = "Quando la specializzazione attuale non ha barre in questo gruppo, mantiene gli elementi ancorati al gruppo sul posto e li sposta in alto o in basso di un'altezza di barra (regola con lo Scostamento Y extra dell'ingranaggio) per coprire il suo slot vuoto."
L["When using custom raid sizes, don't count members in hidden groups toward the raid-size breakpoint. For example, if you hide groups 7 and 8, a full 40-man raid is sized as if it were 24-man instead of jumping to the 30-man frame size. Has no effect unless you have custom raid sizes set up."] = "Quando usi dimensioni di incursione personalizzate, non contare i membri nei gruppi nascosti per il punto di soglia della dimensione incursione. Ad esempio, se nascondi i gruppi 7 e 8, un'incursione completa da 40 persone viene dimensionata come se fosse da 24 invece di passare alla dimensione riquadro da 30. Non ha effetto se non hai configurato dimensioni di incursione personalizzate."
L["When you are solo, center the player frame on the party frame instead of anchoring it at the top."] = "Quando sei da solo, centra il riquadro del personaggio sul riquadro del gruppo invece di ancorarlo in alto."
L["When you join a Group Finder group for a dungeon that has a teleport, shows a small movable popup with the dungeon name and a one-click teleport button. It hides when you enter the dungeon, leave the group, or enter combat."] = "Quando entri in un gruppo della Ricerca gruppo per un dungeon che ha un teletrasporto, mostra un piccolo popup mobile con il nome del dungeon e un pulsante di teletrasporto a un clic. Si nasconde quando entri nel dungeon, lasci il gruppo o entri in combattimento."
L["When you press Escape or Space during a cinematic, the confirmation prompt is automatically accepted."] = "Quando premi Esc o Spazio durante una cinematica, la richiesta di conferma viene accettata automaticamente."
L["When you press an ability's keybind, show the action button's \"pushed down\" look on its icon on this bar -- even while the ability is on cooldown."] = "Quando premi l'associazione tasti di un'abilità, mostra l'aspetto \"premuto\" del pulsante azione sulla sua icona su questa barra -- anche mentre l'abilità è in ricarica."
L["When your bags have none of one combat potion type, its icon swaps to track the next type you own."] = "Quando le tue borse non hanno nessuna pozione di combattimento di un tipo, la sua icona passa a monitorare il prossimo tipo che possiedi."
L["When your bags have none of one potion type, its icon swaps to track the other type."] = "Quando le tue borse non hanno nessuna pozione di un tipo, la sua icona passa a monitorare l'altro tipo."
L["When your interrupt is on cooldown now but will be ready before the enemy cast finishes, color the part of the cast bar during which your interrupt will be available. The color clears the instant your interrupt comes off cooldown."] = "Quando la tua interruzione è in ricarica ora ma sarà pronta prima che il lancio del nemico finisca, colora la parte della barra di lancio durante la quale la tua interruzione sarà disponibile. Il colore si azzera nell'istante in cui la tua interruzione esce dalla ricarica."
L["When your spec has no class resource, automatically adds the class resource height to the power bar. Automatically disabled when Power Bar height is matched to another element."] = "Quando la tua specializzazione non ha risorsa di classe, aggiunge automaticamente l'altezza della risorsa di classe alla barra energia. Disattivato automaticamente quando l'altezza della Barra energia è abbinata a un altro elemento."
L["Whenever not airborne on a skyriding mount."] = "Ogni volta che non sei in volo su una cavalcatura skyriding." -- JARGAO (skyriding mantido em inglês, mesma decisão já usada em "Skyriding (Airborne)")
L["Where the block's content sits inside its slot."] = "Dove si trova il contenuto del blocco all'interno del suo slot."
L["Where the icon strip sits inside its slot."] = "Dove si trova la striscia di icone all'interno del suo slot."
L["Where to Show"] = "Dove mostrare"
L["Which audio channel the block's volume bar adjusts."] = "Quale canale audio regola la barra del volume del blocco."
L["Which direction new icons extend from the frame's edge."] = "In quale direzione si estendono le nuove icone dal bordo del riquadro."
L["Which end of the crest ladder comes first."] = "Quale estremità della scala delle creste viene prima."
L["Which enemy buffs show on nameplates. Important shows the buffs Blizzard flags for enemy nameplates plus anything dispellable; Dispellable shows only buffs that can be dispelled, purged or soothed. With a Dispel Glow style set, every dispellable buff shown glows."] = "Quali potenziamenti nemici mostrare sulle targhette. Importante mostra i potenziamenti che Blizzard segnala per le targhette nemiche più qualsiasi cosa dissolvibile; Dissolvibile mostra solo i potenziamenti che possono essere dissolti, purgati o calmati. Con uno stile Bagliore dissolvenza impostato, ogni potenziamento dissolvibile mostrato brilla."
L["Which enemy buffs show on nameplates. Important shows the buffs Blizzard flags for enemy nameplates plus anything dispellable; Only Dispellable shows just the buffs that can be dispelled, purged or soothed. With a Dispel Glow style set, every dispellable buff shown glows."] = "Quali potenziamenti nemici mostrare sulle targhette. Importante mostra i potenziamenti che Blizzard segnala per le targhette nemiche più qualsiasi cosa dissolvibile; Solo dissolvibile mostra solo i potenziamenti che possono essere dissolti, purgati o calmati. Con uno stile Bagliore dissolvenza impostato, ogni potenziamento dissolvibile mostrato brilla."
L["Which hearthstone the left click uses. Random Hearthstone picks a random owned variant each cast. Right click always rolls a random one."] = "Quale Pietra Focolare usa il clic sinistro. Pietra Focolare casuale scegli una variante posseduta a caso a ogni lancio. Il clic destro tira sempre una a caso."
L["Which latency to show: home, world, or both side by side."] = "Quale latenza mostrare: locale, mondiale, o entrambe fianco a fianco."
L["Which layer the windows and the collapsed icon draw on, relative to other frames on screen."] = "Su quale strato vengono disegnate le finestre e l'icona compressa, rispetto ad altri riquadri sullo schermo."
L["Which micro menu buttons this block shows."] = "Quali pulsanti del micro menu mostra questo blocco."
L["Which minimap corner the Blizzard element row (tracking, calendar, mail, crafting) builds out from and the direction it grows."] = "Da quale angolo della minimappa si estende la riga degli elementi di Blizzard (monitoraggio, calendario, posta, crafting) e la direzione in cui cresce."
L["Which minimap corner the button row builds out from and the direction it grows."] = "Da quale angolo della minimappa si estende la riga di pulsanti e la direzione in cui cresce."
L["Which of the season's crests this block shows."] = "Quale delle creste della stagione mostra questo blocco."
L["Which sections the gold tooltip shows."] = "Quali sezioni mostra il tooltip dell'oro."
L["Which view bags (and the bank) open to by default. The bank has no MultiBag view, so MultiBag opens the bank to OneBank."] = "In quale visualizzazione si apre per default le borse (e la banca). La banca non ha una visualizzazione MultiBag, quindi MultiBag apre la banca su OneBank."
L["Which way new bars stack as more enemies start casting."] = "In quale direzione si accatastano le nuove barre quando più nemici iniziano a lanciare."
L["Which way spell flyouts (e.g. Wild Mushroom, Tiger's Fury) open from this bar. Automatic opens away from the nearest screen edge."] = "In quale direzione si aprono i menu a comparsa degli incantesimi (es. Fungo selvatico, Furia della Tigre) da questa barra. Automatico si apre lontano dal bordo dello schermo più vicino." -- NAO-OFICIAL
L["Which way the rows stack as healers are added."] = "In quale direzione si accatastano le righe quando vengono aggiunti guaritori."
L["Which way the windows extend from the collapsed icon when they open. The close button always lands at that same corner."] = "In quale direzione si estendono le finestre dall'icona compressa quando si aprono. Il pulsante di chiusura finisce sempre in quello stesso angolo."
L["While dragging a spell or item, this bar appears so you can drop onto it."] = "Mentre trascini un incantesimo o un oggetto, questa barra appare così puoi rilasciarlo su di essa."
L["While either grouping toggle is on, drop the trailing block of empty slots so the view only shows items. Turn this off to keep the free slots visible for depositing."] = "Mentre uno dei due interruttori di raggruppamento è attivo, elimina il blocco finale di slot vuoti così la visualizzazione mostra solo gli oggetti. Disattiva questa opzione per mantenere visibili gli slot liberi per il deposito."
L["While on a glide-capable mount, ground included, where Blizzard shows its vigor HUD. Skyriding (Airborne) additionally requires you to be flying."] = "Mentre sei su una cavalcatura capace di volo radente, terreno incluso, dove Blizzard mostra il suo HUD del vigore. Skyriding (In volo) richiede inoltre che tu stia volando." -- JARGAO (skyriding mantido em inglês, mesma decisão já usada em "Skyriding (Airborne)")
L["While resting, in a city or at an inn."] = "Mentre riposi, in una città o in una locanda."
L["While seated in a vehicle."] = "Mentre sei seduto in un veicolo."
L["While the spellbook or macro panel is open, this bar appears so you can drag abilities onto it."] = "Mentre il libro degli incantesimi o il pannello macro è aperto, questa barra appare così puoi trascinarvi sopra le abilità."
L["While you are inside a house or plot."] = "Mentre sei dentro una casa o un terreno."
