L["With Hide Active State on, a charge cooldown's recharge swipe and edge now stay visible instead of disappearing while a charge is in hand or when you press another ability."] = "Con Nascondi stato attivo attivato, la spazzata di ricarica e il bordo di un tempo di recupero a cariche ora rimangono visibili invece di scomparire mentre una carica è disponibile o quando premi un'altra abilità."
L["With health decimals on, full health renders 100% instead of 100.0% while real decimals like 99.5% stay"] = "Con i decimali della salute attivati, la salute piena viene mostrata come 100% invece di 100,0% mentre i decimali reali come 99,5% restano"
L["With the Rectangular shape, player and party arrows no longer draw in the hidden bands above and below the map, and combat transitions no longer leave the map cut off wrong."] = "Con la forma Rettangolare, le freccette del personaggio e del gruppo non si disegnano più nelle bande nascoste sopra e sotto la mappa, e le transizioni di combattimento non lasciano più la mappa tagliata male."
