L["Works in and out of combat, unlike Auto-Repair. When a group-wide raid buff's column header shows it's missing on someone, the icon blinks and sends the buff's spell link. In a raid, left-click reaches a provider in groups 1-4 and right-click one in groups 5-8; outside a raid, left-click reaches the only provider found. Hovering the icon always shows who each click would whisper, or that everyone already has it."] = "Funziona dentro e fuori dal combattimento, a differenza di Auto-riparazione. Quando l'intestazione di colonna di un potenziamento da incursione a livello di gruppo mostra che manca a qualcuno, l'icona lampeggia e invia il link dell'incantesimo del potenziamento. In un'incursione, il clic sinistro raggiunge un fornitore nei gruppi 1-4 e il clic destro uno nei gruppi 5-8; fuori da un'incursione, il clic sinistro raggiunge l'unico fornitore trovato. Passare il mouse sull'icona mostra sempre a chi ogni clic sussurrerebbe, o che tutti lo hanno già."
