L["You changed settings while profile sync is active. Please reload your UI for sync changes to take effect."] = "Hai cambiato impostazioni mentre la sincronizzazione dei profili è attiva. Ricarica la tua interfaccia perché le modifiche di sincronizzazione abbiano effetto."
L["You changed the default value of a setting that has overrides. Overrides keep their own values, so this change will not reach the specs or conditions they cover. To change it for an override, pick that override from the class glyph beside the module search bar and edit it there."] = "Hai cambiato il valore predefinito di un'impostazione che ha degli override. Gli override mantengono i propri valori, quindi questa modifica non raggiungerà le specializzazioni o le condizioni che coprono. Per modificarla per un override, scegli quell'override dal glifo di classe accanto alla barra di ricerca del modulo e modificalo lì."
