L["Your Edit Mode layout is a Blizzard preset which cannot be modified by addons. Please switch to a custom Edit Mode layout so EllesmereUI can manage your CDM settings.\n\nOpen Edit Mode to create or select a custom layout."] = "Il tuo layout Modalità modifica è un preset di Blizzard che non può essere modificato dagli addon. Passa a un layout Modalità modifica personalizzato in modo che EllesmereUI possa gestire le tue impostazioni CDM.\n\nApri Modalità modifica per creare o selezionare un layout personalizzato."
L["Your Keystone"] = "La tua Pietra chiave" -- TODO: confirmar termo oficial (Keystone)
L["Your chat position is now controlled by Blizzard Edit Mode.\nPlease adjust its position there."] = "La posizione della tua chat è ora controllata dalla Modalità modifica di Blizzard.\nRegola la sua posizione lì."
L["Your current spec has an assigned profile so you cannot switch to another. Please unassign to switch."] = "La tua specializzazione attuale ha un profilo assegnato quindi non puoi passare a un altro. Rimuovi l'assegnazione per cambiare."
L["Your current spec has its own custom Buff Manager, so conditional Buff Managers never apply to it."] = "La tua specializzazione attuale ha un proprio Gestore potenziamenti personalizzato, quindi i Gestori potenziamenti condizionali non le si applicano mai."
L["Your current spec has its own custom Debuff Manager, so conditional Debuff Managers never apply to it."] = "La tua specializzazione attuale ha un proprio Gestore indebolimenti personalizzato, quindi i Gestori indebolimenti condizionali non le si applicano mai."
L["Your current spec has its own custom unlock mode, so conditional unlock modes never apply to it. Swap to a spec without one to customize this."] = "La tua specializzazione attuale ha una propria modalità sblocco personalizzata, quindi le modalità sblocco condizionali non le si applicano mai. Passa a una specializzazione senza per personalizzare questo."
L["Your focus target's nameplate never fades with the non-target opacity."] = "La targhetta del bersaglio del tuo focus non si affievolisce mai con l'opacità dei non bersagli."
